(function(){
  var C=window.YLT_CFG||{};var books=C.books||(window.GAME_CONFIG&&window.GAME_CONFIG.books)||[];var byId={};for(var i=0;i<books.length;i++)byId[books[i].id]=books[i];
  function acc(id,chs){var b=byId[id];if(!b)return;b.chapters=(b.chapters||[]).concat(chs);}
  acc("b_jingyue",[{"n": 37, "text": "卷三十七\n\n硼砂（一钱） 朱砂（三钱） 马牙硝 寒水石（飞，各二钱） 冰片（半字） \n上为细末。每用一字，掺舌上，咽亦不妨。喉痛者吹入咽中。 \n\\x孙真人口疮方\\x \n单用朴硝含之，甚良。 \n\\x皂角散\\x 治重舌喉痹。 \n皂角（不蛀者四、五挺，去皮核，炙焦） 荆芥穗（二钱） \n上为细末，以米醋调涂肿处。 \n\\x千金口臭方\\x 亦治舌上出血如簪孔。 \n用香薷一把，以水一斗，煮取三升，稍稍含漱咽之。 \n《圣惠》\\x口齿方\\x 治口臭秽及齿慝肿痛。 \n用北细辛一两，煮取浓汁热漱，冷即吐之，立效。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下齿牙方\n\n属性：（东垣）\\x神功丸\\x 治多食肉人口臭不可近，牙齿疳蚀，牙龈肉脱血出，并治血崩血痢，肠 \n风下血，及逆气上行等证。 \n黄连（酒洗） 砂仁（各五钱） 生地 甘草（各三钱） 当归 木香 藿香叶 升麻 兰叶（各一 \n钱，无亦可） \n上为末，以汤浸蒸饼和丸，绿豆大。每服百丸或二百丸，白汤食远服。 \n（东垣）\\x清胃散\\x 方在寒阵。治齿龈溃烂，喜冷恶热。 \n《秘验》\\x清胃饮\\x 方在寒阵。治一切风热牙床肿痛，出血动摇。 \n《三因》\\x安肾丸\\x 治肾虚牙齿肿痛。 \n此与《局方》安肾丸同，但少肉桂、茯苓二味，方在热阵。 \n《直指》\\x立效散\\x 治牙痛不可忍，痛连头脑项背，微恶寒饮，大恶热饮。 \n防风（一钱） 升麻（七分） 炙甘草 细辛叶（各三分） 草龙胆（酒洗，四分） \n上用水一钟，煎五分，去滓。以匙抄在口中， 痛处少时，立止。如多恶热饮， \n更加草龙胆一钱。此法不定，宜随寒热多少临时加减。若恶风作痛，须去草龙胆，加草豆蔻 \n、黄连各五分，累用得效。 \n\\x细辛煎\\x 治牙齿肿痛不可忍，及口气臭。 \n用北细辛一味煎浓汁，乘热噙漱良久，吐之，极妙。 \n\\x驱毒饮\\x 治热毒上攻，宣露出血，牙龈肿痛不可忍。 \n屋游（此即瓦上青苔，不拘多少洗净） \n上用水煎汤，澄清入盐一撮，频频漱之。 \n《御药》\\x丁香散\\x 治牙齿痛。 \n丁香 荜茇 蝎梢 大椒 \n上等分为末。每用少许擦于患处。 \n《选要》\\x芫花散\\x 治风虫诸牙痛。 \n芫花 细辛 川椒 蕲艾 小麦 细茶（等分） \n上咀。水一钟，煎七分，温漱之，日三、四次，吐涎出即愈。 \n\\x如神散\\x 治风牙虫牙攻蛀疼痛，牙齿动摇，连颊浮肿。 \n川椒（炒出汗） 蜂房（炙） \n上等分，为细末。每用二钱，水煎数沸，热漱即止。 \n\\x赴筵散\\x 治风虫牙痛。 \n良姜 草乌 细辛 荆芥穗 \n上等分为末。擦牙，有涎吐之。 \n\\x蟾酥膏\\x 治风蛀诸牙疼痛。 \n蟾酥（少许） 巴豆（去油，研如泥） 杏仁（烧焦） \n上共研如泥，以绵裹如粟米大。若蛀牙塞入蛀处，风牙塞牙缝中，吐涎尽愈。 \n\\x虫牙痛\\x \n苍耳 艾 小麦 花椒 芫花 黑豆 \n煎熬，屡漱之即愈。 \n\\x韭子汤\\x 治虫牙。 \n用韭菜子一撮，以碗足盛之，用火烧烟，外用小竹梗将下截劈为四开，以纸糊如喇叭样 \n，引烟熏其蛀齿。如下牙蛀者，以韭子煎浓汤漱之，虫自出。 \n\\x瑞竹堂方\\x 治虫牙疼痛不已。 \n用天仙子不拘多少，烧烟，以竹筒抵牙引烟熏之，其虫即死。 \n\\x巴豆丸\\x 治虫牙疼痛，蚀孔空虚。 \n巴豆（一枚） 花椒（五十粒，细研） \n上为极细末，饭丸，黍米大。绵包塞蛀孔。 \n\\x藜芦散\\x 治虫牙疼痛。 \n用藜芦为末，塞牙孔中，勿令咽汁，有涎吐之，大有神效。 \n\\x北枣丹\\x 治走马牙疳。 \n用北枣去核，每个内入信一厘，烧存性，研细。每以些小敷患处。 \n\\x青金散\\x 治走马牙疳，蚀损唇舌，腐臭牙落，其效如神。 \n铜绿 砒霜（等分） \n上为细末。每用些少敷患处。 \n\\x三仙散\\x 治走马牙疳，一时腐烂即死。 \n铜绿（三分） 麝香（一分） 妇人溺桶中垢（白者，火 ，一钱） \n上为极细末。敷齿上，不可太多。 \n\\x麝矾散\\x 治走马牙疳危恶证候。 \n麝香（少许） 胆矾（一钱） 铜绿（半两） 白矾（生用，五分） \n上为细末。敷牙患处。 \n\\x神授丹\\x 治牙疳。 \n枯矾（七分） 白毯灰（三分） 麝香（一分） \n为末。以竹管吹疮上。 \n\\x黄连散\\x 治齿龈间出血，吃食不得。 \n黄连 白龙骨 马牙硝（各一钱） 枯矾（五分） 冰片（半分） \n上为细末。每用少许敷牙根下。 \n\\x雄黄麝香散\\x 治牙龈肿烂出血。 \n雄黄（一钱半） 铜绿 轻粉 黄连 黄丹（炒，各一钱） 血竭 枯矾（各五分） 麝香（一分） \n上为细末，研匀。每用些少敷患处。 \n齿缝出血。 \n上用纸 子蘸干蟾酥少许，于血出处按之，立止。 \n\\x固齿雄鼠骨散\\x 治肾水不足，牙齿浮动脱落，或缝中痛而出血，或但动不痛者。 \n雄鼠骨 当归 没石子 熟地 榆皮 青盐 细辛（等分） \n上为细末，用绵纸裹倏 牙床上缝中，则永固不落矣。 \n《秘方》\\x雄鼠骨散\\x 治牙落可以重生。 \n雄鼠骨（一具，生打活雄鼠一个，剥去皮、杂，用盐水浸一时，炭火上炙，肉自脱落，取 \n骨炙燥，入众药内同研为末） 香附 白芷 川芎 桑叶（晒干） 地骨皮 川椒 蒲公英 \n青盐 川槿皮 旱莲草 \n上为末。擦牙，百日复出，固齿无不效。 \n《良方》\\x荆槐散\\x 治牙宣出血，疼痛不止。 \n荆芥穗 槐花 \n上等分为末。擦牙患处。 \n\\x石膏升麻散\\x 治阳明风热流注，齿牙肿痛出血，化为脓汁等证。 \n石膏 羊胫骨灰 地骨皮 升麻 \n上等分为末。每用少许擦牙齿根上。或加麝香少许更妙。 \n\\x姜黄散\\x 治牙疼不可忍。 \n姜黄 白芷 细辛（等分） \n上为粗末。擦患处，须臾吐涎，以盐汤漱口。面赤肿者，去姜黄，加川芎，其肿立消。 \n《济生》\\x香盐散\\x 牢牙去风。 \n大香附（炒焦黑，三两） 青盐（一两半） \n上为末。如常擦牙。乃铁瓮先生良方。 \n（子和）\\x牙宣散\\x \n良姜 胡椒 荜茇 细辛 乳香 麝香 雄黄 青盐（下四味各另研） \n上等分为细末。先以温水漱净牙后，以药末擦患处，追出涎沫吐之，漱十余次，痛立止。忌油、盐二日。 \n\\x槐盐散\\x 治食甘甜过多牙痛。 \n食盐 青盐 槐枝（一斤，切断，用水五碗，煎一碗听用） \n上将二盐先炒干，乃入槐枝汤煮干，取起为末，用铅盒盛。擦牙固齿最妙。 \n\\x椒盐散\\x 治牙痛用清凉药不效或反甚者，宜从此以治。 \n川椒 青盐 荜茇 薄荷 荆芥穗 细辛 朝脑 \n上为末。擦痛牙处，或煎汤漱之亦可。 \n\\x宣风牢牙散\\x 驻颜补肾，牢牙固齿。 \n细辛 青盐（各七钱） 当归（酒洗） 川芎（各一两） \n上为末。每用少许，清晨擦牙满口，漱良久，连药咽下，或先以温水漱口净，然后擦而咽之亦可。 \n（万氏）\\x青白散\\x 治一切牙疼，固齿。 \n青盐（二两） 食盐 川椒（煎汁，各四两） \n上以椒汁拌盐，炒干为末。擦牙，永无齿疾；以漱水洗面目，亦无疾。此药极妙。 \n\\x御前白牙散\\x \n石膏（四两，另研） 大香附（一两） 白芷（七钱半） 甘松 三奈 藿香 沉香 川芎 零陵香 \n（各三钱半） 细辛 防风（各半两） \n上为细末。先以温水漱口，次擦之妙。 \n（东垣）\\x白牙散\\x \n升麻（一钱） 羊胫骨灰（二钱） 软石膏（三钱） 白芷（七分） 麝香（少许） \n上为细末。先以温水漱口，次擦之妙。 \n\\x《道藏经》方\\x 治牙齿动摇，血出不止。 \n用白蒺藜不拘多少，捣为细末。每日擦牙及患处，最妙。 \n取牙不犯手。 \n草乌 荜茇（各钱半） 川椒 细辛（各三钱） \n上为细末。每用少许，点在患牙内外，一时其牙自落。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下咽喉方\n\n属性：《局方》\\x甘桔汤\\x 治一切风热上壅，咽喉肿痛。钱氏方用甘草二钱，苦梗一钱。 \n甘草（二钱） 桔梗（四钱） \n水二钟，煎八分，食后服。此方加荆芥穗二、三钱，《三因方》即名荆芥汤，尤效。 \n《拔萃》\\x甘桔汤\\x 治热肿喉痹 \n甘草 桔梗 薄荷 连翘 黄芩（各等分） \n水二钟，加竹叶煎服。一方有山栀子。 \n\\x加味甘桔汤\\x 方在痘疹。治咽喉肿痛。 \n《医林》\\x诃子甘桔汤\\x 治火盛失音。 \n诃子（四个，半生半煨） 桔梗（一两五钱，半生半炒） 甘草（二寸，半生半炙） \n上咀，分二服，每服水二钟，童便一钟，煎八分，食后温服。 \n\\x清咽利膈散\\x 治咽喉肿痛，痰涎壅盛。 \n防风 金银花 荆芥 薄荷 桔梗 黄芩 黄连（各一钱半） 山栀 连翘 玄参 大黄 \n朴硝 牛蒡子（炒研） 甘草（各七分） \n水二钟，煎一钟，食远服。 \n\\x消梨饮\\x 治喉痹。 \n单用消梨汁频频饮之，或将梨削浸凉水中，频频饮之，尤妙。此物大解热毒。或南方少 \n梨之处，但择好萝卜杵汁，加玄明粉徐饮，大效。 \n《医林》\\x透天一块冰\\x 治一切风热喉痹，口舌生疮头目不清，痰涎壅盛。 \n黄连（二钱） 脑荷 月石 槟榔 蒲黄 甘草（各一钱） 荆芥穗 黄柏（各五分） 冰片（半分或 \n一分） 白砂糖（半两） \n上为细末，炼蜜为丸，芡实大。每服一丸，噙化。 \n\\x靛花丸\\x 治缠喉风声不出。 \n靛花 薄荷叶（苏州者） \n上等分，为细末，炼蜜丸，弹子大。每服一丸，临睡噙化。 \n《医林》\\x杏仁煎\\x 治咳嗽暴重，声音不出。 \n杏仁（泡，去皮尖，研如泥） 冬蜜 姜汁 砂糖（各一小盏） 木通 桑白皮（去赤皮，炒） \n贝母 紫菀茸 北五味（各一两） 石菖蒲 款冬蕊（各半两） \n上将后七味为咀，用水五升，煎半去滓，入杏、蜜、姜、糖四味合和，微火煎取一升半 \n。每服三合，两日夜服之。 \n《三因》\\x蜜附子\\x 治隔阳咽闭，吞吐不通，及脏寒闭塞等证。 \n用大附子一枚，去皮脐，切作大片，用蜜涂炙令黄，含口中，咽津；甘味尽，再涂蜜炙 \n用，或易之。或用炮附子，以唾津调涂脚心。一方用肉桂含之。 \n\\x牛黄益金散\\x 治虚火炎上伤肺，咽喉生疮破烂。 \n黄柏（为末，用蜜炙数次，以热为度，另研为极细末） 白硼砂 白僵蚕（净，各钱半） 牛黄（三分） \n上用蜜调如稀糊涂敷患处；或丸如龙眼大，含化咽之。按∶此方必加冰片半分方妙。 \n《秘方》\\x三黄丸\\x 治喉痹极佳。 \n大黄 黄连 黄芩（各一两） 黄药子 白药子（各七钱半） 黄柏 山豆根 苦参（各三钱） 月 \n石京墨（各钱半） 麝香（少许） 冰片（五分） \n上为末，猪胆调，甑内蒸三次，临后入片、麝、硼砂为丸，豆大。噙化一丸，津咽，日 \n夜常噙，勿脱药味方妙。 \n\\x人参平补汤\\x 治肾虚声哑不出。 \n人参 川芎 当归 熟地黄 白芍药 白茯苓 菟丝子（制） 杜仲（制） 北五味子 白 \n术巴戟（去心） 半夏曲 橘红（各半两） 牛膝（酒洗） 破故纸（炒） 益智仁 葫芦巴（炒） \n炙甘草（各二钱半） 石菖蒲（一钱半） \n上咀。每服五钱，姜五片，枣二枚，煎七分，吞山药丸百余粒。凡五鼓后肾气开时，不 \n得咳唾言语，再进上药，则功效胜常。 \n\\x百合丸\\x 治肺燥失声不语。 \n百合 百药煎 杏仁（去皮尖） 诃子 薏苡仁（等分） \n上为末，鸡子清和丸，弹子大。临卧噙化。或用蜜丸亦妙。 \n《秘方》\\x竹衣麦门冬汤\\x 治一切劳瘵痰嗽，声哑不出，难治者，服之神效。 \n竹衣（取金竹内衣膜鲜者，一钱） 竹茹（弹子大一丸。即金竹青皮也，刮取之） 竹沥（即 \n取金竹者） 麦冬（三钱） 甘草 橘红（各五分） 白茯苓 桔梗（各一钱） 杏仁（七粒，去皮尖，研） \n上咀。水一钟半，加竹叶十四片，煎七分，入竹沥一杯，和匀服。 \n\\x射干丸\\x 治悬壅肿痛，咽喉不利。 \n射干 炙甘草（各半两） 川升麻 川大黄 木鳖仁（各二钱半） 杏仁（去皮尖、双仁，麸炒 \n微黄，半两） \n上为细末，炼蜜丸，小弹子大。常含一丸，津咽。 \n《医林》\\x铁笛丸\\x 治讴歌动火，失音不语者神效。 \n薄荷叶（四两） 连翘 桔梗 甘草（各二两半） 诃子（煨） 大黄（酒蒸） 砂仁（各一两） 川芎 \n（一两半） 百药煎（二两） \n上为细末，鸡子清和丸，弹子大。临卧噙化一丸。或炼蜜丸亦可。 \n《三因》\\x雄黄解毒丸\\x 治急喉风双蛾肿痛，汤药不下。 \n雄黄（飞） 郁金（各一两） 巴霜（十四枚） \n上为末，醋糊丸，绿豆大。热茶清下七丸，吐出顽涎即苏，未吐再服，大效。如口噤， \n以物斡开灌之，下咽无有不活者。如小儿惊热，痰涎壅塞，或二丸三丸，量大小与之。一法 \n，以此丸三粒，用醋磨化灌之，其痰立出，尤妙。 \n《三因》\\x玉钥匙\\x 治风热喉痹及缠喉风。 \n月石（五钱） 牙硝（一两半） 白僵蚕（一钱） 冰片（一字） \n上为细末。每用五分，以竹管吹入喉中，立愈。此方加雄黄二钱，即名密钥匙。 \n《济生》\\x二圣散\\x 治缠喉风，急喉痹。 \n胆矾（二钱半） 白僵蚕（炒，半两） \n为细末。用少许吹入喉中。 \n《秘方》\\x夺命散\\x 治急喉风。 \n白矾（枯） 僵蚕（炒） 月石 皂角（炙烟尽，各等分） \n为细末，每用少许吹喉中，痰出即愈。 \n\\x马牙硝散\\x 治喉痈，及伤寒热后咽痛，闭塞不通，毒瓦斯上冲。 \n马牙硝细研。每服一钱，绵裹含咽津，以通为度。 \n\\x烧盐散\\x 治喉中悬壅垂长，咽中妨碍。 \n烧盐 枯矾（各等分） \n上和匀研细，以箸头蘸点即消。 \n《宝鉴》\\x开关散\\x 治喉风气息不通。 \n白僵蚕（炒，去丝嘴） 枯白矾（等分） \n上为细末。每服二、三钱，生姜、蜜水调下，细细饮之。 \n\\x七宝散\\x 治喉闭及缠喉风。 \n僵蚕（直者，十个） 硼砂 雄黄 全蝎（十个，全者，去毒） 明矾 牙皂（一挺，去皮弦， \n（各一钱） 胆矾（五分） \n上为细末。每用一字，吹入喉中即愈。 \n\\x破关丹\\x 治乳蛾喉闭，缠喉风等证。 \n硼砂末（五钱） 霜梅肉（一两，捣烂） \n上二味，和匀丸，芡实大。每服一丸，噙化咽下，内服荆防败毒散。 \n\\x通气散\\x 方在外科。治时毒肿甚，咽喉不利，取嚏以泄其毒。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下诸毒方\n\n属性：\\x紫金锭\\x 一名神仙太乙丹。一名玉枢丹。一名万病解毒丹。解除一切中毒积毒，虫毒蛊 \n毒，茵蕈、砒石、死牛、死马、河豚等毒，及时行瘟疫，山岚瘴气，喉闭喉风，癫邪鬼气， \n狂乱迷死，牙关紧急，小儿急惊等证。凡行兵兴役之处，尤不可无。 \n文蛤（捶破洗焙，净末，三两） 山茨菰（去皮，净末，二两） 千金子（去油取霜，一两） 红芽 \n大戟（去芦，焙干为末，一两五钱） 麝香（另研，三钱） \n上用糯米煮浓饮为丸，分作四十锭。每服半锭，用井花水或薄荷汤磨服，利一、二次， \n用粥止之。若治痈疽恶毒，汤火蛇虫犬兽所伤，以东流水磨服，并敷患处。如治癫邪鬼气， \n鬼胎，挛急疼痛，须暖酒磨服。凡修合时日，须用端午、七夕、重阳，或天德、月德日，于 \n净室焚香修制。凡奇怪之病，屡用如神，效验不可尽述，医家、大家，皆不可一日无之。 \n《三因》\\x解毒丸\\x 治误食毒草，或中蛊毒，并百物毒，救人于必死。 \n板蓝根（洗净晒干，四两） 贯众（去毛） 青黛（研） 生甘草（各一两） \n上为末，炼蜜丸，桐子大，另以青黛为衣。如稍觉精神恍惚，即是误中诸毒，急取十五 \n丸嚼烂，用新汲水送下即解。或用水浸蒸饼丸，尤佳。 \n\\x蓝根散\\x 解毒药热药诸毒。 \n蓝根（锉，一握） 芦根（锉，一握） 绿豆（三钱，研） FS 脚（一合，研） \n上先将二根，以水一碗，煎至七分，去滓，次入后药，和匀，分三服。或一、二服利下 \n恶物，不用再服。 \n\\x白扁豆散\\x 解诸毒入腹及砒毒。 \n用白扁豆不拘多少，为细末，入青黛等分，细研，再入甘草末少许。巴豆一枚，去壳不 \n去油，别研为细末，取一半入药内。外以砂糖一大块，用水化开和药，共成一大盏饮之，毒 \n随利去，后却服五苓散之类。 \n\\x八毒赤丸\\x 方在攻阵。治一切邪崇鬼疰等毒。 \n\\x饮食中毒\\x \n凡中饮食毒，而觉烦热胀满者，急用苦参三两，苦酒一升半，煮半沸，陆续饮之，吐食 \n出即瘥。或以水煮亦得。或用犀角汤亦可解。 \n\\x中酒毒\\x 饮酒中毒者，经日不醒是也，谓之中酒。 \n黑豆一升煮汁，温服一盏，不过三盏即愈。 \n\\x解面毒\\x \n只以萝卜生啖之，或捣汁服之。麦面大热，萝卜能解其性。或用大蒜嚼食之，亦善解面毒。 \n\\x解一切食毒\\x 解一切饮食之毒，及饮酒不知中何毒，卒急无药可解者。 \n荠 生甘草（各二两） \n上锉细。以水五盏，同煎取二盏，停冷去滓，分三服。一方∶加蜜少许，同煎服之，解一切毒。 \n\\x食鱼中毒\\x \n凡食鱼后中毒物烦乱者，用陈皮浓煎汁服之即解。 \n\\x河豚毒\\x \n五倍子 白矾（等分） \n上为细末，水调服之。一方∶凡中河豚鱼毒，一时困殆，仓卒无药，急以清油多灌之， \n使毒尽吐出即愈。 \n解河豚鱼脍及食狗肉不消胀满毒。 \n芦柴根，鲜者捣汁饮之，干者煎汁温饮之。 \n解食鳝鱼龟鳖虾蟆自死禽兽等毒 \n豆豉一合，新汲水煎浓，顿温服之可解。 \n\\x中蟹毒\\x \n凡食蟹中毒，用紫苏叶浓煮汁饮之；或用紫苏子捣汁饮之亦良。或捣藕汁，或捣蒜汁饮 \n之俱可解。或用冬瓜汁，或食冬瓜亦可。 \n\\x食牛马肉中毒\\x \n粉草擂无灰酒服，当吐泻。若渴者不可饮水，饮水必死。一方∶淡豆豉擂入乳服之即解。 \n\\x食鸡子毒\\x \n好醋饮之即愈，未愈再服。 \n\\x食斑鸠毒\\x \n葛粉二合，水调服可解，姜汤调服亦解。 \n\\x解花椒毒\\x 有服川椒气闭欲绝者。 \n冷水饮之解，地浆水更妙。 \n\\x解诸菜毒\\x \n食后多腹胀者，是毒也，以醋解之。 \n\\x解蕈毒\\x \n忍冬叶生啖之愈，或煎浓汁饮之。崇宁间，苏州天平山白云寺僧五人，行山间，得蕈一 \n丛甚大，摘而食之，发吐，三人急采怨鸯草生啖之即愈；二人不甚吐，至死。此即忍冬藤， \n亦名金银花，亦名鹭鸶藤也。 \n\\x解巴豆毒\\x 其证口干，两脸赤，五心热，下利不止。 \n干姜（炮） 黄连（微炒，各等分） \n上为细末。每服二钱，水调下，如人行五里许再服。又方∶煮绿豆汤冷服之即愈。一方 \n∶黄连、甘草煎汁，凉饮之。一方∶芭蕉根叶捣汁饮之，利止而安。 \n\\x解砒毒\\x 凡中砒毒者，其人烦躁如狂，心腹绞痛，头眩呕吐，面色青黑，四肢逆冷，六 \n脉洪数。饮食中得者为易愈，若空心酒醋服者难救。 \n以地浆水顿服，若吐出，又服，所谓洗净腹中毒，全凭地上浆是也。其法掘地成坑，以 \n水灌注，搅成混水饮之，谓之地浆。 \n又方∶解砒毒最良，此为第一。 \n用生绿豆半升擂粉，入新汲水搅和，去 取汁饮之。 \n又方∶用新鲜羊血、鸭血饮之，皆可解。一方∶用甘草汁同蓝汁饮之即愈。 \n\\x钩吻毒\\x \n钩吻生池旁，与芹菜相似，无他异，惟茎有毛，以此别之，误食杀人。解之之法，用荠 \n八两，水六升，煮取二升。分温二服（此即甜桔梗也）。一方用桂汤效。 \n\\x解附子等药毒\\x \n凡服附子酒多，而觉头重唇裂血流，或见内热诸证，急用绿豆、黑豆嚼服，或捣汁饮之 \n，或浓煎二豆汤常饮食之。凡服散风药过多，以致闷乱不省，以醋灌之，或浓煎甘草同生姜 \n自然汁顿饮之。一方；大豆汁、饧糖、枣汤，并能解附子毒。一方∶用田螺捣碎调水饮之。 \n\\x解乌头草乌毒\\x \n甘草煎浓汤服之。或米醋调沙糖俱可解。 \n\\x解半夏毒\\x \n生姜捣汁饮之。有中此毒，口不能言，倒地将死者，速用姜汁灌之，须臾自苏。 \n\\x解斑蝥芫青毒\\x \n猪脂油和大豆汁饮之。 \n\\x解藜芦毒\\x \n雄黄为末，温酒调服一钱。一方∶煮葱汁服。 \n\\x解雄黄毒\\x \n汉防己煎汤饮之。有用雄黄擦疮，或熏阴囊疮受毒者，防己煎汤洗数次愈。 \n\\x解杏仁毒\\x \n蓝子研水服则解。 \n\\x解服丹毒\\x \n地浆服之为上。一方∶用蚌肉食之良。 \n\\x解中药箭毒\\x \n交广黎人以焦铜作箭，中人破皮即死。粪清饮之立解，患处以粪涂洗之。 \n\\x解盐卤毒\\x \n凡妇女有服盐卤垂危者，急取活鸭或鸡，斩去头，将颈塞口中，以热血灌之可解。若卤 \n多者，必数只方足尽收其咸毒。 \n\\x解漆毒\\x \n一州牧以生漆涂囚眼，囚即盲。适一村叟见而怜之，语之曰∶汝急寻蟹捣碎，取汁滴眼 \n内，漆当随汁流散，疮亦愈矣。如其言，觅得一小蟹用之，目睛果愈，略无损。或成红斑烂 \n疮，取生蟹黄涂之，不数次即愈。一方∶用杉木煎汁洗之。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下虫毒方\n\n属性：\\x解虎伤毒\\x \n麻油一碗饮之即无妨，仍用葛根汤洗伤处，绵试干，香油涂之，再以青布作条燃火入竹 \n筒中，放烟熏伤处。口渴者，沙糖调水饮之。 \n\\x蛇毒\\x \n凡被蛇伤，即用针刺伤处出血，用雄黄等药敷之，仍须中留一孔，使毒瓦斯得泄，乃内服 \n解毒等药。凡伤处两头俱用绳扎缚，庶不致毒瓦斯内攻，流布经络。 \n一方∶治毒蛇咬伤，急取三七捣烂罨之，毒即消散，神妙无比。 \n一方∶治蛇虫伤毒，用五灵脂、雄黄等分为末，每服二钱，酒调服，仍敷疮留口，如干 \n燥，须以油润之。凡居山野阴湿之处，每用雄黄如桐子大一丸，烧烟以熏衣袍被褥之类，则 \n毒不敢侵，百邪皆远避矣。 \n一、凡蛇入七窍，急以艾灸蛇尾。又法以刀破蛇尾少许，入川椒数粒，以纸封之，蛇自 \n出。即用雄黄、朱砂末煎人参汤调灌之，或食蒜饮酒，内毒即解。 \n一、山居人被蛇伤，急用溺洗咬处，拭干，以艾灸之立效。又方∶用独头大蒜切片置患 \n处，以艾于蒜上灸之，每三壮换蒜，多灸为妙，凡被毒蛇所伤皆效。 \n《肘后方》∶用小蒜捣汁服，滓敷伤处。 \n\\x雄黄辟蛇毒\\x \n南海地多蛇，而广府尤甚。某侍郎为帅，闻雄黄能禁制此毒，乃卖数百两分贮绢囊，挂 \n于寝室四隅。经月余，一日，卧榻外常有黑汁从上滴下，臭甚，使人穿承尘窥之，则巨蟒横 \n其上死腐矣。于是尽令撤去障蔽，蛇死者长丈许，大如柱，旁又得十数条，皆蟠虬成窠，并 \n他屋内所驱放者合数百，自是官舍清宁。 \n\\x疯犬伤人\\x \n急于无风处吮出疮口恶血，如或无血，则以针刺出血，用小便洗净，外用香油调雄黄少 \n加麝香敷之。一、凡遇恶犬咬伤，如仓卒无药，即以百草霜、麻油调敷，或用葱捣烂贴之， \n牛粪敷之，或蚯蚓粪敷之，或口嚼杏仁烂敷之，皆能救急。如少延缓，恐毒瓦斯入经为害。一 \n方∶拔去顶上红发，急令人吮去恶血，以艾灸伤处五、七壮，甚者灸百壮，神效。一方∶用 \n米泔水洗净，沙糖敷之。一方∶用杏仁炒黑，捣成膏贴之。 \n\\x避犬法\\x \n《琐碎录》云∶凡行道遇恶犬，即以左手大拇指掐寅上，吹气一口，轮至戌上掐之，犬即退伏。 \n\\x糯米散\\x 治疯犬伤毒。 \n大斑蝥（二十一个，去头足翅） \n上用糯米一撮，先将斑蝥七个入米内，慢火炒，勿令焦，去蝥；又入七个，炒令焦色变 \n，又去之；再入七个炒米赤烟为度，去蝥不用，只将米研为末。分三分，冷水入香油少许， \n空心调下一服，须臾又进一服，以二便利下恶物为度。若腹痛，急以青靛调冷水解之，或先 \n用黄连、甘草煎汤，待冷服之，不可食热物。或用冷水调益元散解之，甚妙。甚者，终身禁 \n食犬肉，每见食犬肉而复作者不救。又见单服斑蝥而死者亦有之，盖斑蝥毒之尤者，虽曰以 \n毒攻毒，惟少用之。兹用糯米以夺其气，尤宜预备青靛、黄连以解其毒，而况单服斑蝥者， \n岂有不死？ \n《宝鉴》\\x定风散\\x 治诸犬伤毒。 \n南星（生用） 防风（等分） \n上为末。凡被犬咬，先以口含浆水吮洗伤处，或小便、盐汤俱可，洗净，用绵拭干，方 \n上药末，即不发。或用制过南星一、二钱为末，以童便调下。亦可治破伤风。 \n\\x诸犬咬虫伤灸法\\x \n凡野狼、犬、蛇、蝎、蜈蚣诸伤痛极危急，或因伤受风而牙关紧急，腰背反胀，不省人事 \n者，速切蒜片或捣烂罨伤处，隔蒜灸之，或二、三十壮，或四、五十壮，无不应手而愈，取 \n效多矣，故《本草》谓蒜疗疮毒，有回生之功。夫积在肠胃，尚为难疗，况四肢受患，则经 \n络远绝，药不易及，故古人有淋洗灸刺等法，正为通经逐邪，导引气血而设也。 \n\\x解毒散\\x 一名国老饮。治蛊毒及一切蛇虫恶兽所伤，重者毒瓦斯入腹，则眼黑口噤，手足 \n强直。此药平易，不伤元气，大有神效，不可以易而忽之也。 \n明矾 甘草（各一两） \n上为末。每服二钱，不拘时冷水调下，亦可敷患处。 \n\\x治马咬伤\\x 毒瓦斯入心则危。 \n马齿苋捣烂煎汤服，外以栗子嚼敷患处。 \n\\x蜈蚣毒\\x \n以盐擦咬处，或盐汤洗伤处，痛即止。用后蝎螫方最妙，已试。一方∶用吴茱萸嚼烂擦 \n之，或取井底泥敷之。 \n\\x解误吞蜈蚣方\\x \n昔有婢用火筒吹火，不知内有蜈蚣，向火一吹，蜈蚣惊窜入口，不觉下喉，求救，人无 \n措手。适有人云取小鸡一只，断喉取血顿饮之，复灌以香油取吐，蜈蚣随出。 \n\\x蝎螫毒\\x \n用生半夏、白矾等分为末，以醋和敷伤处（亦治蜈蚣伤，无白矾亦可）。又蝎怕胆矾，蛇 \n性雄黄。徐春甫云∶亲见蝎螫肿痛用胆矾擦之立消。可见南方人家不可无雄黄，北方人家不 \n可无胆矾，此制蝎第一药也。 \n\\x解蜂螫毒\\x \n以小便洗擦拭干，以香油涂之。或以雄黄末擦之。或以蝎螫方治之。 \n\\x治鼠咬毒\\x \n猫毛烧存性，入麝香少许，香油调敷伤处则不害。 \n\\x治误吞水蛭\\x \n昔一人夜间饮水，误吞水蛭入腹，经停日久，复生水蛭，食人肝血，腹痛不可忍，面目 \n黄瘦，全不进食，不治必死。方用田中泥一块，小死鱼三枚，同猪膏溶捣匀，再用巴豆十粒 \n去油，同鱼膏四味捣匀，丸如绿豆大。用田中冷水吞下，大人五、七丸，小儿三丸，须臾泻 \n下水蛭尽，却用八珍汤调理。 \n\\x中蚯蚓毒\\x \n锻石泡热水凉洗患处，久浸之则愈。小儿多受蚯蚓毒，则阴茎及囊俱肿如水泡，用鸭血 \n涂之，或以鸭口含少时则消。一方∶用盐汤温洗之即效。 \n\\x治蚕咬毒\\x 蚕咬人，毒入肉中，令人发寒热。 \n苎叶捣敷之，汁涂之。今治蚕家以苎近蚕，则蚕不生发也。 \n\\x解蜘蛛咬毒\\x \n姜汁调胡粉敷疮口，或用清油擦之，内饮羊乳。 \n《本草》云∶蜘蛛咬人，令人一身生丝，惟羊乳饮之可解。贞元十年，崔员外从质云目 \n击有人被蜘蛛咬，腹大如孕，其家弃之，乞食于道，一僧遇之，教饮羊乳，未几日而平。 \n《青囊》\\x神授散\\x 治传尸劳瘵，血气末甚虚损者，不必多方，只以此药早服，则虫自不 \n能为患。无有不愈者。此方得之河南郡王府，济世之功不可尽述。 \n川椒（二升，去合口者，略炒出汗） \n上为细末，空心米饮调服二钱。或酒煮米粉糊为丸，桐子大。每服三十丸，以渐增至五 \n、六十丸，或用酒送。 \n\\x解射工溪毒\\x 葱白散。治溪涧中射工虫专射行人形影，人中其毒，则病如疟状，或若伤 \n寒，俗云沙发，中之深者死，急用后方治之。 \n葱白（一握，切） 豉（半升） 葛根（二两） 升麻（七钱半） \n上锉如豆大。每服四钱匕，水二盏，煎一盏，去滓。不拘时温服，移时再服。 \n《千金》\\x雄黄兑散\\x 治时气病 ，下部生虫。 \n雄黄（半两） 桃仁（一两） 青葙子 黄连 苦参（各三两） \n上五味为末，绵裹如枣核大，纳下部。亦可用枣汁服方寸匕，日三。 \n《千金》\\x治大孔虫痒方\\x \n用大枣蒸烂为膏，以水银和捻长二、三寸许，绵裹纳大孔中过宿，明旦虫皆出。但水银 \n损肠，宜慎之。愚按∶此方水银不必生用，但如治头虱法，烧烟以枣肉拌之用，必更妙。头 \n发生虱方在新因。 \n\\x雄麝散\\x 治五种蛊毒。 \n明雄黄 麝香（各一字，另研） \n用生羊肺一指大，以刀切开，安药在内吞下。 \n《医林》\\x丹砂丸\\x 治蛊毒。 \n雄黄 朱砂（各另研） 藜芦（略炒） 鬼臼 巴豆霜（各二钱半） \n上为末，炼蜜丸，桐子大。每服二丸，空心姜汤下，当利恶物并蛊毒。如烦闷，以鸭血为羹食之。 \n《良方》\\x七宝丸\\x 治蛊毒。 \n败鼓皮 蚕蜕纸 刺 皮（各烧存性） 五倍子（炒） 续随子 朱砂（另研） 雄黄（另研，等分） \n上为细末，糯米粥丸，小豆大。每服七丸，空心白水下。 \n\\x蜜髓煎\\x 治中蛊令人腹内坚痛，面目青黄，病变无常。 \n真蜜（一碗） 猪骨髓（五两，研） \n上同煎熟。分作十服，日三服即瘥。 \n\\x归魂散\\x 凡国中蛊毒在膈上者，当用此药吐之。 \n白矾 建茶（各一两） \n上二味，为细末。每服五钱，新汲水调下顿服之，一时久当吐毒出。若此药入口，其味 \n甘甜，并不觉苦味者，即其证也。 \n\\x麦面散\\x 治中蛊毒吐血。 \n用小麦面二合，分为三服，以冷水调下，半日服尽，当下蛊即瘥。 \n\\x挑生蛊毒简易方\\x \n一方∶明矾、芽茶，等分为末，凉水调三钱。 \n一方∶青蓝汁，频频服半合则解。 \n一方∶石榴皮，煎汁饮之，当吐出活虫而愈。 \n\n\n\n<目录>卷之六十宙集·古方八阵\\因阵\n\n<篇名>以下杂方\n\n属性：\\x嗽烟筒\\x 治一切犯寒咳嗽，遇冬便作。 \n款冬蕊 鹅管石 雄黄 艾叶（各等分） \n上为末，铺艾上，用纸卷筒，烧烟吸入口内吞下，即咽茶水一口压之，自效。一方有佛 \n耳草，无艾叶，用纸卷成条，每切一节，约长三、五分许，焚炉中，吸烟咽之。 \n\\x灵宝烟筒\\x 治一切寒喘咳嗽。 \n黄蜡 雄黄（各三钱） 佛耳草 款冬蕊（各一钱） 艾叶（三分） \n先将蜡溶化，涂纸上，次以艾铺之，将三味细研匀，掺卷成筒。用火点一头，吸烟吞之 \n，清茶送下。 \n\\x七宝美髯丹\\x 补肾元，乌须发，延年益寿。 \n何首乌（赤、白，各一斤） 川牛膝（半斤） \n将何首乌先用米泔水浸一日，以竹刀刮去粗皮，切作大片，用黑豆铺甑中一层，却铺何 \n首乌一层，再铺豆一层，却铺牛膝一层，又豆一层，重重相间，面上铺豆盖之，蒸以豆熟为 \n度，取起晒干，次日如前换豆再蒸，如此七次，去豆用。 \n破故纸（半斤，洗净，用黑芝麻同炒无声为度，去芝麻） 白茯苓（半斤，用人乳浸透，晒干 \n蒸熟） 赤茯苓（半斤，用黑牛乳浸透，晒干蒸熟） 当归身（半斤，酒洗） 枸杞子（半斤，去枯蒂者） \n上共为末，炼蜜丸，龙眼大。每日空心嚼二、三丸，温酒、米汤、盐汤俱可送下。制药 \n勿犯铁器。按∶此即七珍至宝丹少菟丝子一味。 \n\\x北京乌须方\\x 两京各处乌须者，惟此方颇好，用之虽未至简妙，然不坏须伤肉，制用得 \n法者，可黑一月。 \n五倍子（择川中之大者，打作碎粒，分粗细为二。先将粗者于锅内用文火炒成糊，次入 \n细者同炒，初时大黑烟起，取出不住手炒，将冷，又上火炒，则黄烟起，叉取出炒，将冷， \n再上火炒，则青黄白烟间出，即可住火，先以真青布一大片浸湿，将倍子倾在布上，包成一 \n团，用脚踏成饼，上用湿泥一担 一夜，色如乌羽为妙，瓷器收贮听用） 红铜花（用 \n细红铜丝炭火 ，醋中淬之，不拘遍数，以化尽为度，去醋取铜花晒干） 皂矾 明矾（各三 \n分） 没石子 食盐（各二分） 硼砂（净，一分） \n上每次染时，旋配旋用，以制倍子二钱为则，加铜花四分，余皆一、二分，和匀作一服 \n，研细，以浓茶汁或烧酒用瓷钟调如稀糊，坐汤中煮之，看钟内绿气生面为佳。先用皂角汤 \n洗须净，拭干，以抿柄涂上，用皮纸搭湿包之，或以青布囊囊之过夜，次早温水洗之。如不 \n润，用胡桃油捻指润之。一连染二夜，其黑如漆亦妙。 \n\\x擦牙乌须方\\x 先期而擦者，永久不白。 \n青盐（一斤） 嫩槐枝叶（五斤，切） 黑铅（四两） 没石子（尖者，七钱） \n上将黑铅、青盐入锅内，槐枝搅炒俱成灰炭取起，将没石子研细末和入，用瓷罐盛之， \n每日早晚以药擦牙，漱水吐掌上擦须鬓，久久自然润黑。 \n\\x便易擦牙方\\x \n用五倍子大者一百个，装食盐一斤，铺在锅内，大火烧过存性，为末。每日擦之，久则须髯皆黑。 \n（丹溪）\\x疝气神方\\x 其病甚，至气上冲如有物筑塞心脏欲死，手足冷者，二、三服除根。 \n陈皮 荔枝核（为末，炒焦黄） 硫黄（火中溶化，即投水中去毒，研细，各等分） \n上为末，饭丸，桐子大。每服十四、五丸，酒下，其疼立止。若疼甚不能支持，略加五 \n、六丸，再不可多也。 \n\\x神仙六子丸\\x 男子三十岁后服此药，一岁二单，制服不息，永不白须发。四十以上，或 \n见微白，及少年发黄不润者，服此百日，自然漆黑，其效如神。 \n菟丝子（制） 金铃子 覆盆子 五味子 枸杞子 蛇床子（炒，各一两） 何首乌（酒浸， \n蒸极熟，焙） 牛膝（酒浸蒸） 熟地（酒蒸，捣） 地骨皮（各三两） 舶上茴香（盐炒） 川木瓜 \n（各二两） \n上十二味，为细末，用浸菟丝酒作糊为丸，梧子大。每服五、七十丸，食前温酒或白汤 \n送下。一方加人参、白术、白茯苓各一两，尤有神效。服此大忌三白。 \n疝气方重。 \n\\x四制川楝子丸\\x 治疝气，一切下部之病，悉皆治之，凡肿痛缩小，虽多年亦可除根。 \n川楝子（净肉，一斤，分四分。内一分用盐一两，茴香一协议炒黄色，去盐、香不用。外 \n三分，一分用巴豆四十九个，一分用斑蝥四十九个，一分用巴戟一两，仍各加麦面一协议炒 \n黄色，俱去面、药不用） 木香（一两） 破故纸（一两，炒） \n上为末，酒糊丸，梧子大。每服五、七十丸，盐汤送下，甚者日进二、三服，或空心、或食前。 \n\\x木香导气丸\\x 治男子小肠气肚疼，一切气积，下元虚冷，脾胃不和，并宜服之有效。 \n木香 丁香 乳香 香附 川楝子肉 大茴香 破故纸 葫芦巴（炒） 甘草（炙） 三棱 \n（各一两） 杜仲（炒，半两） \n上为细末，酒糊丸，梧子大。每服三、五十丸，加至七、八十丸，用温酒，或盐汤食前 \n送下，日进二、三服。 \n\\x去铃丸\\x 治疝消铃。 \n用大茴香一升，以老生姜二斤，取自然汁浸茴香一宿，以姜汁渗尽为度，入好青盐二两 \n同炒赤，取出焙干为末，用无灰酒浸蒸饼为丸，梧子大。空心、食前酒下二、三十丸，或米 \n饮亦可。此方实脾疏肝，所以治疝多效，非如常法之克伐，故为妙也。 \n\\x事后中寒腹痛方\\x \n凡房事后中寒厥冷，呕恶腹痛者，用葱、姜捣烂冲热酒服之，睡少顷，出汗即愈。如腹 \n痛甚者，以葱白头捣烂摊脐上，以艾灸之或熨之亦可解。鼻尖有汗，其痛痛即止。 \n湿疝阴丸作痛。 \n蕲艾 紫苏叶（烘干热） 川椒（炒热，各三两） \n上三味，拌匀，乘热用绢袋盛夹囊下，勿令走气，冷即易之。 \n\\x熏熨脱肛方\\x 治气痔脱肛。 \n枳壳（面炒） 防风（去叉，各一两） 枯矾（二钱半） \n上咀，用水三碗，煎至二碗，乘热熏之，仍以软帛蘸汤熨之，通手即淋洗。 \n\\x熏洗脱肛法\\x \n用赤皮葱、韭菜二味各带根者煎汤，入大枫子、防风末各数钱，乘热熏洗立收上。一方 \n∶用五倍子煎汤洗，以赤石脂末掺上托入。或脱长者，以两床相并，中空尺许，以瓷瓶盛汤 \n，令病患仰卧浸瓶中，逐日易之，收尽为度。又涩肠散方，在小儿五四。 \n\\x参术芎归汤\\x 治泻痢产育气虚脱肛，脉濡而弦者。 \n人参 白术 川芎 当归 黄 （酒炒） 山药（炒） 白芍药 白茯苓 升麻 炙甘草 \n上生姜水煎服。按∶此方若治泄痢虚滑脱肛，仍须加制附子、肉豆蔻方效。 \n\\x凉血清肠散\\x 治大肠血热脱肛。 \n生地黄 当归 芍药（各钱半） 黄芩 黄连 防风 荆芥 升麻（各一钱） 香附 川芎 甘 \n草（各五分） \n水一钟半，煎服。 \n\\x缩砂散\\x 治大肠伏热，脱肛红肿。 \n缩砂仁 黄连 木贼（等分） \n上为细末。每服二钱，空心米饮调下。 \n\\x诃子人参汤\\x 治证同前。 \n诃子（煨，去核） 人参 白茯苓 白术 炙甘草 莲肉 升麻 柴胡（等分） \n水一钟半，加生姜，煎服。 \n\\x涩肠散\\x 治久痢火肠滑脱。 \n诃子 赤石脂 龙骨（等分） \n上为末。以腊茶少许和药，掺肠头上，用绢帛揉入。又方用鳖头 存性，入枯矾少许，如上揉入。 \n\\x蟠龙散\\x 治阳证脱肛肿痛。 \n地龙（晒干，一两） 风化硝（二两） \n上为末。每用一、二钱，肛门湿，则干掺；燥，则清油调擦。先以见肿消，荆芥、生葱 \n煮水候温洗，轻轻拭干，然后敷药。 \n\\x伏龙肝散\\x 治阴症脱肛。 \n伏龙肝（一两） 鳖头骨（五钱） 百药煎（二钱半） \n上为末。每用一、二钱，浓煎紫苏汤候温洗过，以清麻油调药敷如前法。 \n\\x独蒜通便方\\x 治小便不通。 \n独蒜（一枚） 栀子（三、七枚） 盐花（少许） \n上捣烂摊纸上贴脐，良久即通。未通，涂阴囊上立通。 \n小便不通经验方。 \n以朴硝为末。每服二钱，空心煎茴香汤下。又方∶用蚯蚓杵，以凉水摅过，浓服半碗立 \n通，大解热疾不知人事欲死，服之甚效。 \n\\x小水不通葱熨法\\x \n用葱三斤，慢火炒香熟，以绢帕裹，更替熨脐下即通。或用盐炒热熨之，冷则再易，须臾即通。 \n\\x鸡内金散\\x 治气虚溺尿。 \n用雄鸡 并肠烧为末。温酒调服。 \n\\x狐腋气五方\\x 治阴汗 臭，两腋下臭不可与人同行。 \n枯白矾 密陀僧 黄丹（各二钱半） 麝香（五分） \n上于乳钵内研细。以醋于手心内调药擦腋下，经两时许，即以香白芷煎汤洗之，一日用一次。 \n又∶治腋气神效方。 \n密陀僧（四两） 枯白矾（二两） 轻粉（三钱） \n上为细末。频擦两腋，擦至半月见效，半年全愈。 \n又∶腋气方。 \n用热蒸饼一枚，擘作两片，掺密陀僧细末一钱许，急挟在腋下，略睡少时，候冷弃之。 \n如一腋有病，只用一半。叶元方平生苦此疾，来绍兴偶得此方，用一次遂绝根本。 \n又∶腋气方。 \n单用枯矾为极细末，以绢袋盛之。常以扑于腋下，不过十度即愈。一方以唾调涂之。 \n又∶腋气方。 \n先剃去腋毛令净，用白定粉水调擦敷患处，至六、七日后，清晨看腋下有一黑点如针孔 \n大者，以笔点定，即用小艾炷灸七壮，灸过或有浊气攻心作痛者，当用后药下之∶ \n丁香 青木香 槟榔 檀香 麝香 大黄 \n上煎服，以下为度。 \n\\x脚汗牡蛎散\\x 治脚汗，除秽气。 \n牡蛎（ ） 枯白矾 密陀僧 黄丹（等分） \n上为细末。每用少许，干掺脚指缝中即收。 \n\\x燥囊牡蛎散\\x 治阴囊湿痒，搔之则汁水流珠，用此极效。 \n牡蛎（醋 ，一两） 雄黄（一钱） 枯矾 硫黄 苦参 蛇床子（各二钱） \n上为细末。先用苍术、椒、盐煎汤洗湿处，后用此药掺之。 \n\\x蒸洗阴囊法\\x 治一切阴囊湿痒。 \n陈茶（一撮） 苍术（二钱） 花椒 蛇床子 白矾（各一钱） 苍耳草（量入） 炒盐（半两） 朴硝（三钱） \n上用水四碗，先将前五味煎汤，去 ，乃入后三味泡化，先熏后洗，三、四次绝痒。 \n\\x梅苏丸\\x \n龙脑薄荷 粉草 冰糖（各四两） 乌梅肉（三两） 白檀香 紫苏叶（各二两） \n上为极细末，以熟枣肉捣丸，芡实大。勿用铁器。 \n\\x冰梅丸\\x \n龙脑薄荷（二两） 白糖 柿霜（各四两） 乌梅肉 桔梗（各五钱） 儿茶（三钱） 甘草（一钱） 冰片 \n（一分） \n上为极细末，炼蜜丸，龙眼核大。 \n\\x龙脑上清丸\\x \n乌梅肉 脑荷（各四两） 白檀香 苏叶 儿茶 硼砂 沙糖（各二两） 冰糖 柿霜（各八两） \n干葛 粉草（各一两） 冰片（三分） \n上为极细末，蜜丸，樱桃大。 \n\\x上清丸\\x 佳方。 \n脑荷（二两） 雨茶 白硼砂（七钱） 乌梅肉 贝母 诃子（各三钱） 冰片（三分） \n炼蜜丸。 \n\\x辟邪丹\\x 方在痘疹。辟一切秽寒邪气。 \n\\x福建香茶饼\\x 能辟一切瘴气时疫，伤寒秽气，不时噙口中，邪气不入。 \n沉香 白檀（各一两） 儿茶（二两） 粉草（五钱） 麝香（五分） 冰片（三分） \n上为极细末，糯米调饮汤为丸，黍米大。噙化。 \n香发木 油 \n采桂花半开者，去茎蒂令净，每花二升，用真麻油一斤，轻手拌匀，纳瓷瓶中，用油纸 \n紧封器口，坐釜中汤煮一饷，持起顿燥处，十日后掀出，用麻布滤绞清油，封闭紧密收之， \n愈久愈香。或用菜子油亦可。 \n\\x玉容散\\x 治面生黑鼾雀斑。 \n甘松 三奈 茅香（各半两） 白芷 白芨 白蔹 白僵蚕 白附子 天花粉 绿豆粉（各一 \n两） 防风 零陵香 本（各二钱） 肥皂（二钱，去皮弦） \n上为细末。每早、晚蘸末洗面。 \n\\x硫黄膏\\x 治面部生疮，或鼻赤风刺粉刺。 \n硫黄 白芷 天花粉 水粉（各五分） 全蝎（一枚） 蝉蜕（五个） 芫青（七个，去头足） \n上为细末，用麻油、黄蜡约多寡，如合面油，熬匀离火，方入前末药和匀。每于临卧时 \n洗面净，以少许涂面，勿近眼，数日间肿处自平，赤鼻亦消。如退风刺，一夕见效。 \n\n\n\n<目录>卷之六十一长集·妇人规古方\n\n<篇名>妇人\n\n属性：\\x安胎饮\\x 治妊娠五、七个月，用数服可保全产。 \n人参 白术 当归 熟地 川芎 白芍药 陈皮 甘草（炙） 紫苏 炙黄芩（各一钱） \n上为姜、水煎服。一方有砂仁。 \n\\x安胎散\\x 治妊娠卒然腰痛下血。 \n熟地 艾叶 白芍（炒） 川芎 黄 （炒） 阿胶（炒） 当归 甘草（炙） 地榆（各一钱） \n上为姜、枣，水煎服。 \n\\x泰山盘石散\\x 治妇人血气两虚，或肥而不实，或瘦而血热，或脾肝素虚，倦怠少食，屡 \n有堕胎之患。此方平和，兼养脾胃气血。觉有热者，倍黄芩，少用砂仁；觉胃弱者，多用砂 \n仁，少加黄芩。更宜戒欲事恼怒，远酒醋辛热之物，可永保无堕。徐东皋曰∶妇人凡怀胎二 \n、三个月，惯要堕落，名曰小产，此由体弱气血两虚，脏腑火多，血分受热，以致然也。医 \n家又谓安胎，多用艾、附、砂仁热补，尤增祸患而速其堕矣。殊不知血气清和，无火煎烁， \n则胎自安而固。气虚则提不住，血热则溢妄行，欲其不堕，得乎？香附虽云快气开郁，多用 \n则损正气；砂仁快脾气，多用亦耗真气，况香燥之性，气血两伤，求以安胎，适又损胎而反 \n堕也。今惟泰山盘石散、千金保孕丸二方，能夺化工之妙，百发百效，万无一失，甫故表而 \n出之，以为好生君子共知也。 \n人参 黄 当归 川续断 黄芩（各一钱） 川芎 白芍药 熟地（各八分） 白术（二钱） 炙 \n甘草 砂仁（各五分） 糯米（一撮） \n水一钟半，煎七分，食远服。但觉有孕，三、五日常用一服，四月之后方无虑也。 \n\\x地黄当归汤\\x 一名内补丸。治妊娠冲任脉虚，补血安胎。 \n熟地（二两） 当归（一两） \n上每服五钱，水煎服。为丸法∶以当归炒为末，熟地蒸捣膏和丸，桐子大，每服百余丸 \n，温酒或滚汤下。许学士曰∶大率妊娠惟在抑阳助阴，然胎前药最恶阴阳杂乱，致生他病， \n惟枳壳汤所以抑阳，四物汤所以助阴耳。然枳壳汤其味多寒，若单服恐致胎寒腹痛，更以内 \n补丸佐之，则阳不致强，阴不致弱，阴阳调和，有益胎嗣，此前人末尝论及也。 \n《良方》\\x当归汤\\x 治胎动烦躁，或生理不顺，唇口青黑，手足厥冷。 \n当归 人参（各二、三钱） 阿胶（炒） 甘草（炒，各一钱） 连根葱白（一握） \n上水四碗，煎四味至半，去滓，下葱再煎一碗，分二服。 \n《良方》\\x阿胶散\\x 或顿仆，或因毒药胎动不安，或胁痛腹痛，上抢短气。 \n阿胶 艾叶 当归 熟地 川芎 白芍 黄 炙甘草（等分） \n上每服四钱，姜、枣、水煎。 \n《良方》\\x胶艾汤\\x 治妊娠顿仆，胎动不安，腰腹疼痛，或胎上抢，或去血腹痛。又《金 \n匮》胶艾汤在后。 \n阿胶（炒，一两） 艾叶（数茎） \n上二味，以水五升，煮取二升，分三服。 \n\\x七味阿胶散\\x 治胎动腹痛。 \n阿胶（炒） 白茯苓 白术（炒） 川芎 当归 陈皮（各一钱） 甘草（炒，三分） \n上姜、枣，水煎服。 \n《良方》\\x黄 汤\\x 治气虚胎动，腹痛下水。 \n糯米（一合） 黄 （炒） 川芎（各一两） \n上水煎，分三服。 \n《良方》\\x钩藤汤\\x 治妊娠胎动腹痛，面青冷汗，气欲绝。 \n钩藤钩 当归 茯神 桑寄生 人参（各一钱） 苦梗（一钱半） \n上水煎服。如有烦热，加石膏。 \n《良方》\\x白术散\\x 治妊娠伤寒内热等证。 \n白术 黄芩（炒，各二钱） \n上用姜、枣、水煎服。若阴证者不可用。 \n《良方》\\x三味白术汤\\x 治妊娠内热心痛。 \n白术（四钱） 赤芍药（三钱） 黄芩（炒，二钱） \n上水煎服。忌桃李、雀肉。 \n《良方》\\x四味白术汤\\x 治妊娠胃虚，恶阻吐水，甚至十余日浆粥不入。 \n白术（炒，一钱） 人参（五分） 甘草（炒） 丁香（各二分） \n上姜、水煎服。 \n\\x全生白术散\\x 治妊娠面目虚浮，四肢肿如水气，名曰胎肿。 \n白术（一两） 生姜皮 大腹皮 陈皮 白茯苓（各半两） \n上为末，每服二钱，米饮下。如未应，佐以人参、甘草。 \n\\x探胎饮\\x 妇人经水不来三月，疑似，用此验之。 \n川芎（不拘多少，为末，不见火） \n空心煎艾汤调下方寸匕，觉腹中动则有胎也。脐之下动者，乃血瘕也；不动者，血凝也，病也。 \n\\x当归芍药汤\\x 治妊娠心腹急痛，或去血过多而眩运。 \n当归 白芍药（炒） 白术（炒） 茯苓 泽泻（各一钱） 川芎（二钱） \n上水煎服。 \n\\x益母地黄汤\\x 治妊娠跌坠，腹痛下血。 \n生地 益母草（各二钱） 当归 黄 （炒，各一钱） \n上姜、水煎服。 \n《良方》\\x独圣散\\x 治妊娠有所伤触，激动胎元，腹痛下血极效。 \n砂仁（不拘多少，带皮同炒，勿令焦黑，取仁为末） \n上用热酒调服四、五分，或一钱。此物有安胎导滞易产之功，实妊妇之要药也。 \n《良方》\\x安胎寄生汤\\x 治妊娠下血，或胎不安，或腰腹作痛。 \n桑寄生 白术 茯苓（各五分） 甘草（一钱） \n上水煎服。 \n\\x二黄散\\x 治胎漏下血，或内热晡热，或头痛头晕，或烦躁作渴，或胁肋胀痛等证。 \n生地 熟地。 \n上为末。每服三钱，煎白术枳壳汤下。 \n\\x四圣散\\x 治漏胎下血。 \n条芩 白术 砂仁 阿胶（各等分） \n上为细末。每服二钱，艾汤调下。一方有芍药无阿胶。按∶此方若改为汤，砂仁用当减半。 \n《良方》\\x续断汤\\x 治妊娠下血尿血。 \n当归 生地黄（各一两） 续断 赤芍药（各半两） \n上为末。每服二钱，空心用葱白煎汤调下。 \n\\x枳壳汤\\x 治胎漏下血，或因事下血。亦进食和中，并治恶阻。 \n枳壳（炒） 黄芩（炙，各半两） 白术（炒，一两） \n上为末。每服一钱，白汤调下。前四证若因脾胃虚弱，宜用补中益气汤加五味。若因脾 \n胃虚陷，宜用前汤倍加升麻、柴胡。若因晡热内热，宜用逍遥散。 \n\\x滑胎枳壳散\\x 此方能令胎瘦产易。湖阳公主每产累日不下，南山道人进此方。 \n粉草（炒，一两） 商州枳壳（麸炒，二两） \n上为末。每服二钱，空心沸汤调，日三服。凡孕六、七月宜服之。温隐居方加当归、广 \n木香各等分。或加香附一两亦可。 \n\\x枳壳散\\x 方在寒阵。治妇人血热气滞，经候不调。 \n《千金》\\x鲤鱼汤\\x 治妊娠腹胀，胎中有水气，遍身浮肿，小便不利，或胎死腹中皆效。 \n当归 芍药（各一钱） 白术（一钱） 茯苓（一钱半） 橘红（五分） 鲤鱼（一尾，不拘大小） \n上作一服，将鲤鱼去鳞脏，白水煮熟，去鱼，用汁钟半入药，加生姜五片，煎一钟，空 \n心服，当见胎水下。如水未尽，胎死腹中，胀闷未除，再制一服，水尽胀消乃已。 \n\\x竹叶汤\\x 治妊娠心惊胆怯，烦闷不安，名曰子烦。一方有当归、防风、栀子仁。 \n白茯苓 麦门冬 黄芩（各三两） \n上每服四钱，竹叶五片，水煎服。若因血虚烦热，宜兼用四物；若因中气虚弱，宜兼用四君。 \n\\x紫苏饮\\x 治妊娠失调，胎气不安，上 作痛，名曰子悬，或临产气结不下等证。 \n大腹皮 川芎 白芍药 陈皮 苏叶 当归（各一两） 人参 甘草（各半两） \n上每服一两，姜、葱、水煎服。一方有香附，无人参。若肝脾气血虚而有火不安，宜兼 \n逍遥散；若脾气虚弱而不安，宜用四君、芎、归。 \n\\x安荣散\\x 治妊娠小便涩少，遂成淋沥，名曰子淋，甚妙。 \n麦门冬 通草 滑石 当归 灯心 甘草 人参 细辛（等分） \n上水煎服。一方人参、细辛加倍，为末，每服二钱，麦冬汤调服。若因肺经郁热，宜用 \n黄芩清肺饮；若因膏粱浓味，宜用清胃散；若因肝经湿热，宜用加味逍遥散。 \n\\x天仙藤散\\x 治妊娠三月之后，足指发肿，渐至腿膝，饮食不甘，状似水气，或脚指间出 \n黄水，名曰子气。 \n天仙藤（洗，略炒） 香附（炒） 陈皮 甘草 乌药（等分） \n上每服三、五钱，加生姜、木瓜各三片，紫苏三叶，水煎，食前，日进三服。若因脾胃 \n虚弱，宜兼六君子；中气下陷，须用补中益气汤。 \n\\x羚羊角散\\x 治妊娠虚风，颈项强直，筋脉挛急，语言蹇涩，痰涎不利，不省人事，名曰子痫。 \n羚羊角（镑） 川独活 枣仁 五加皮 薏苡仁（炒） 防风 当归 川芎 茯神 杏仁（ \n去皮尖，各五分） 炙甘草 木香（各一分） \n上加姜五片，水煎服。若因肝经风热，或怒火所致，须用加味逍遥散。 \n\\x人参橘皮汤\\x 治妊娠脾胃虚弱，气滞恶阻，呕吐痰水，饮食少进，益胃和中。一名参橘散。 \n人参 陈皮 麦门冬 白术（各一钱） 浓朴（制） 白茯苓（各五分） 炙甘草（三分） \n上加淡竹茹一块，姜、水煎，温服。若因中脘停痰，宜用二陈、枳壳；若因饮食停滞， \n宜用六君加枳壳；若因脾胃虚，宜用异功散。 \n\\x竹茹汤\\x 治孕妇呕吐不止，恶心少食，服此止呕清痰。 \n竹茹（弹子大一丸） 陈皮 半夏 茯苓（各钱半） 生姜（二钱） \n水钟半，粳米一撮，煎七分，温服。忌羊肉、鸡、鱼、面食。 \n《良方》\\x半夏茯苓汤\\x 治妊娠脾胃虚弱，饮食不化，呕吐不止。 \n半夏（泡，炒黄） 陈皮 砂仁（炒，各一钱） 白茯苓（二钱） 甘草（炒，五分） \n上用姜、枣、乌梅、水煎服。一、二剂后，用茯苓丸（在三九）。 \n\\x乌附汤\\x 治孕妇恶心阻食，养胃，调和元气。 \n乌药 香附（制） 白术（土炒） 陈皮（各一钱） 人参 炙甘草（各八分） \n水钟半，姜三片，煎七分服。吐甚者，加丁香、砂仁各七粒。 \n《千金》\\x保孕丸\\x 治妊妇腰背痛，善于小产，服此可免堕胎之患。此即《良方》杜仲丸，但彼等分用。 \n杜仲（四两，同糯米炒去丝） 川续断（二两，酒洗） \n上为末，山药糊丸，桐子大，每服八、九十丸，空心米饮下。忌酒、醋、恼怒。 \n\\x一母丸\\x 一名知母丸。治妊娠血热顿仆，胎动不安，或欲堕产。 \n知母（炒，为末） \n上捣枣肉为丸，弹子大。每服一丸，人参汤嚼送。或丸桐子大，每服三、四十丸。白汤 \n下，或嚼咽之。 \n\\x束胎丸\\x 怀胎七、八个月，恐胎气展大难产，用此扶母气，束儿胎，易产。然必胎气强盛者乃可服。 \n条黄芩（酒炒，勿太熟。冬月一两，夏月半两） 白术（三两） 陈皮（二两） 白茯苓（七钱半） \n上为末，粥糊丸，桐子大，每服五十丸，白汤下。 \n\\x茯苓丸\\x 治妊娠烦闷头晕，闻食吐逆，或胸腹痞闷。 \n赤茯苓 人参 桂心 干姜（炮） 半夏（泡洗，炒黄） 橘红（各一两） 白术（炒） 甘草（ \n炒） 枳壳（麸炒，各二两） \n上为末，蜜丸，桐子大。每服五十丸，米饮下，日三服。上原方仍有葛根二两，似非所 \n宜也，用者当酌之。达生散 妊娠临月服十余剂则易产，或加砂仁、枳壳。如兼别证，以 \n意增减。《诗》云∶诞弥厥月，先生如达。注曰∶先生，首生也。达，小羊也。羊子易生，故以此名之。 \n人参 白术 当归 白芍 陈皮 紫苏（各一钱） 炙甘草（二钱） 大腹皮（酒洗，晒干，三钱） \n水一钟半煎服。一方无当归、白芍、白术。 \n\\x佛手散\\x 一名芎归汤。亦名当归汤。治产后去血过多，烦晕不省，并一切胎气不安，亦下死胎。 \n川芎（二钱） 当归（三、五钱） \n上咀，每用半两，水煎服。若腹疼加桂；若腹痛自汗，头眩少气，加羊肉；若不应，用 \n八珍汤；若用下胎，当为末，以酒调服。 \n（钱氏）\\x生化汤\\x 此钱氏世传治妇人者。 \n当归（五钱） 川芎（二钱） 甘草（炙，五分） 焦姜（三分） 桃仁（十粒，去皮尖、双仁） 熟地（三钱） \n上 咀，水二钟，枣二枚，煎八分，温服。一方无熟地。附加减法∶凡胎衣不下 \n，或血冷气闭，血枯气弱等证，连服生化汤二、三剂即下，或用此送益母丸一丸即下。盖益 \n母草行血养血，性善走而不伤人者也；一、凡妇人无论胎前产后，皆宜此药；一、凡血晕虚 \n晕，加荆芥穗六、七分；一、凡产妇气虚气脱，倦怠无力，加人参、黄 ；一、凡阳虚厥逆 \n，加附子、肉桂；一、脉虚烦渴，加麦冬、五味；一、气壅有痰，加陈皮、竹沥；一、血虚 \n血燥便结，加麻仁、杏仁、苁蓉；一、多汗不眠，加茯神、枣仁、黄 ；上体多汗，加麻黄 \n根；下体多汗，加汉防己；一、烦热，加丹皮、地骨皮；一、口噤如风，反张螈 者，加荆 \n芥、防风各三、四分；一、恶露未尽，身发寒热，头痛胁胀，其小腹必然胀痛，加红花、丹 \n皮、肉桂各三、四分，玄胡一钱；一、内伤饮食，加山楂、陈皮、砂仁，或神曲、麦芽；一 \n、外伤寒湿，或加苍术、白术；一、血积食积，胃有燥粪，脐腹胀痛，加大黄二钱；一、产 \n后下血不止，或如屋漏水沉黑不红，或断或来，或如水，或有块，淋沥不休，此气血大虚之 \n候，不可误用寒凉。其脉浮，脱者，可加附子辈诸阳分药，否则无救矣。佛手散单用当归三 \n钱，川芎二钱，此即其变方也。 \n会稽《钱氏世传》曰∶尝论产证，本属血虚，阴亡阳孤，气亦俱病。如大补则气血陡生 \n，倘失调则诸邪易袭。四物避芍药之寒，四物得姜、桃之妙。气毋耗散，法兼补虚；食必扶 \n脾，勿专消导。热不可用芩、连，恐致宿秽凝滞；寒不宜用桂、附，反招新血流崩。三阳见 \n表证之多，似可汗也，用麻黄则重竭其阳；三阴见里证之剧，似可下也，用承气则大涸其血 \n。耳聋胁病，乃肾虚恶露之停，休用柴胡；谵语汗多，乃元弱似邪之证，毋同胃实。厥由阳 \n气之衰，难分寒热，非大补不能回阳； 因阴血之亏，岂论刚柔，非滋营胡以润络？潮 \n热似疟，以疟治则迁延；神乱如邪，以邪论则立困。总属大虚，须从峻补。去血多而大便燥 \n，苁蓉加于生化，非润肠和气之能通；患汗出而小便难，六君倍用参、 ，必生津助液之可 \n利。加参生化频服，救产后之危；活命长生调摄，须产前加意。 \n\\x当归川芎汤\\x 治小产后瘀血，心腹疼痛，或发热恶寒。 \n当归 熟地黄 白芍药（炒） 玄胡索（炒） 川芎 桃仁 红花 香附 青皮（炒） 泽兰 牡丹皮 \n上水煎，入童便、酒各小半。若以手按腹愈痛，此是瘀血为患，宜用此药，或失笑散消 \n之。若按之反不痛，此是血虚，宜用四物、参、苓、白术。若痛而作呕，此是胃虚，宜用六 \n君子。若或作泻，此是脾虚，宜用六君子送二神丸。 \n\\x加味芎归汤\\x 治分娩交骨不开，或五、七日不下垂死者。 \n生男女妇人发（一握，烧存性） 自死龟壳（一个，或占过者亦可，酥炙） 川芎 当归（各一两） \n上咀。每用一两，水煎服，良久，不问生死胎，自下。 \n\\x当归黄 汤\\x 方在补阵。治妊娠下痢腹痛。 \n\\x芎归补中汤\\x 治气血虚半产。 \n川芎 当归 黄 （炙） 白术（炒） 人参 芍药（炒） 杜仲（炒） 艾叶 阿胶（炒） 五 \n味子（杵，炒，各一钱） 甘草（炙，五分） \n上每服五钱，水煎服。若脾气虚弱，须用补中益气汤；若气虚有火，宜用安胎饮。 \n\\x保生无忧散\\x 临产服之，补其血，顺其气，或胞胎肥浓，根蒂坚牢者，皆可使之易产。 \n又治小产瘀血腹痛。 \n当归 川芎 白芍 乳香 枳壳 南木香 血余 \n上等分，每服二、三钱，水煎，日二服。若胞衣既破，其血已涸，或元气困惫，急用八 \n珍汤斤许，水数碗，煎熟时饮救之，饮尽再制，亦有得生。 \n\\x人参黄 汤\\x 治小产气虚，血下不止。 \n人参 黄 （炒） 当归 白术（炒） 白芍（炒） 艾叶（各一钱） 阿胶（炒，二钱） \n上作一剂，水煎服。 \n《良方》\\x牛膝散\\x 治胎衣不下，腹中胀痛，急服此药腐化而下，缓则不救。 \n牛膝 川芎 朴硝 蒲黄（各三两） 当归（一两半） 桂心（半两） \n上每服五钱，姜三片，加生地黄一钱，水煎服。 \n《局方》\\x黑神散\\x 一名乌金散。《灵苑方》名肉桂散。治产后恶露不尽，胎衣不下，血 \n气攻心，腹痛不止，及治脾肾阴虚，血不守舍，吐衄等证。 \n黑豆（二两，炒） 当归（去芦，酒洗） 熟地 蒲黄 白芍 甘草（炙） 干姜（炮） 肉桂（各一两） \n上为末。每服二钱，童便、酒各半调服。《良方》黑神散有炮附子半两，无蒲黄。 \n《简易》\\x黑神散\\x 方在和阵。治一切失血。 \n\\x经验滑石散\\x 治产难，凡水下胎干，胎滞不生，用此最效。 \n滑石（飞过，一两） 白蜜 香油（各半盏） \n上将油、蜜慢火熬熟三、四沸，掠去沫，调滑石末顿服，外以油调于产妇脐腹，上下摩 \n之，立效。 \n\\x难产方\\x \n令产妇以自己发梢含于口中，恶心即下，亦治胎衣不下。 \n《良方》\\x桂心散\\x 治妊娠因病胎不能安者，可下之。 \n桂心 栝蒌 牛膝 瞿麦（各五分，或一钱） 当归（一钱或二、三钱） \n上水煎。 \n\\x桂香散\\x 治胎死腹中不下。 \n桂心（三钱） 麝香（五分） \n上为末。作一服，酒调下。 \n下胎短剧方。 \n用麦 一升，擂碎，水二升，煮一升，服之即下，神效。按∶麦 能损气破血 \n如此，故凡脾胃虚弱，及饮食不化者，不宜用明矣。又方用牛膝一两，酒一钟，煎七分，作二服即下。 \n《广济》\\x下胎方\\x 并下死胎俱效。 \n天花粉（四两） 肉桂 牛膝 豆豉（各三两） \n上咀。用水七碗，煎二碗半，分三服，每服后一时许又进一服。 \n\\x扶羸短剧方\\x 虚弱人欲下胎宜用此。 \n人参 粉草 川芎 肉桂 干姜 桃仁 黄芩 蟹爪 \n上等分，每服一两，水二钟，煎八分，空心服，未动再服。 \n下死胎 凡胎死腹中，其舌多见青黑，口中甚秽而呕，腹中不动，只觉阴冷重坠者是。 \n用平胃散一两，以黄酒、河水各一钟，煎至一钟，入朴硝三、五钱，再煎三、五沸。温 \n服，其死胎即化水而出，万不失一。又方∶单用朴硝末三钱，以热酒和热童便调服立出，或 \n用佛手散以酒调服亦妙。 \n《千金》\\x去胎方\\x \n大麦曲（五升） \n渍酒一斗，煮二、三沸，去滓，分五服，隔宿勿食，旦再服，其胎如糜，母无所苦，千金不传。 \n《良方》\\x硫黄散\\x 治产后阳气虚寒，玉门不闭。 \n硫黄 乌贼骨（各半两） 五味子（五钱） \n上为末，掺患处，日三易。 \n\\x硫黄汤\\x 治产后玉门不敛，阴户突出。 \n硫黄（三钱） 菟丝子 吴茱萸（各二钱） 蛇床子（一钱半） \n上研匀，用水二钟，煎汤频洗自收。 \n《良方》\\x益母丸\\x 一名返魂丹。治妇人赤白带，恶露时下不止，及治妇人胎前产后经中 \n诸般奇痛，无所不疗。 \n《本草》云∶此草胎前无滞，产后无虚，故名益母。 \n益母草一味 一名充蔚子，一名野天麻。方梗，对节生叶，叶类火麻，四五月间开紫花 \n是，白花者非。 \n上于五月采取晒干，连根茎叶，勿犯铁器，磨为细末，炼蜜丸，如弹子大。每服一丸， \n用热酒和童便化下，或随证用汤引送下。一方∶以此为末，每服二钱，或酒或童便，或随证 \n用引服之。一方∶凡产时仓卒未合，只用生益母草捣汁，入蜜少许服之，其效甚大。一、益 \n母膏方∶根据前采取捣烂，以布滤取浓汁，用砂锅文武火熬成膏，如黑砂糖色为度，入瓷罐收 \n贮。每服二、三匙，酒、便调下，或于治血汤药中加一匙服之，尤妙。 \n《良方》\\x夺命丹\\x 治瘀血入胞，胀满难下，急服此药，血即消，衣自下。按∶此方颇有 \n回生丹之功用，下死胎必效，须用当归方。 \n附子（炮，半两） 干漆（碎之，炒烟尽） 牡丹皮（各一两） \n上为细末，另用大黄末一两，以好醋一升同熬成膏，和前药丸，桐子大。温酒吞五、七 \n丸。一方有当归一两。 \n\\x回生丹\\x 治妇人产后诸疾，污秽未净，及一切实邪疼痛，死胎瘀血冲逆等证。 \n大黄膏法∶用苏木（三两，河水五碗，煎至三碗，去 听用） 红花（三两，炒黄色，用 \n好酒一大壶，煮十余滚，去 听用） 黑豆（三升，煮熟存汁三碗，去豆去皮，晒干为末， \n俱听用） 大黄（一斤，为末，用好醋入碗熬成膏，次下红花酒、苏木汤、黑豆汁搅匀，又熬成 \n膏，盆内收盛候用。将锅焦焙干为末，同豆皮末俱入之） \n人参 白术 青皮 木瓜（各三钱） 当归 川芎 元胡 苍术 香附（童便炒） 蒲黄 赤 \n茯苓 桃仁泥 熟地（各一两） 牛膝 三棱 山茱萸 五灵脂 地榆 甘草 羌活 陈皮 白 \n芍（各五钱） 良姜（四钱） 乌药（二两半） 木香 乳香 没药（各一钱） \n上为末，用前大黄膏为丸，弹子大，金簿为衣。不拘时，随证择用汤引送下一丸。 \n\\x断产灸法\\x 一传方欲绝产者，灸脐下二寸三分阴动脉中三壮。此当自脐中至骨际折作五寸约之。 \n《千金》\\x断产方\\x \n四物汤（一剂） 芸台子（一撮，即油菜子） 红花 \n水钟半，煎八分，经后空心服则不受胎。 \n\\x断产短剧方\\x 断产堕胎有验。 \n故蚕蜕纸（方一尺） \n上烧为末，空心酒调服，终身不受孕。 \n（丹溪）\\x断子法\\x \n用白面曲一升，无灰酒五升作糊，煮至三升半，滤去滓，分作三服，候经至前一日晚五 \n更及天明各吃一服，经即不（一无不字）行，终身无子矣。 \n（仲景）\\x羊肉汤\\x 治产妇腹中 痛寒痛，血气不足，虚弱甚者，及寒月生产，寒气 \n入于子门，手不可犯，脐下胀满，此产后之寒证也。并治寒疝腹中痛，及胁痛里急者。 \n精羯羊肉（一斤） 当归（三两） 生姜（五两） \n上用水八升，煮取三升，加葱、椒、盐，温服七合，日三服。若寒多者，加生姜成一斤 \n；痛多而呕者，加橘皮二两，白术一两。 \n《良方》\\x羊肉汤\\x 治产妇脾虚，寒邪内乘，以致腹痛，或头眩，脐胁急痛。 \n精羊肉（四两） 当归 川芎（各半两） 生姜（一两） \n上以水十盏，煎至四盏，分四次空心服。 \n《良方》\\x黄雌鸡汤\\x 治产后虚羸腹痛。 \n当归 白术（炒） 熟地黄 黄 （炒） 桂心（各半两） 小黄雌鸡（一只，去头足肠翅，细切） \n上先用水七碗，煮鸡至三碗，每用汁一碗，药四钱煎。日三服。 \n母鸡汤 治产后褥劳，虚汗不止。 \n人参 黄 白术 白茯苓 麻黄根 牡蛎（ ，各三钱） \n上用母鸡一只，去毛杂净，水六、七碗，同药煮至三碗，任意服之。 \n\\x猪腰汤\\x 治产后褥劳，寒热如疟，自汗无力，咳嗽头痛腹痛俱效。 \n猪腰（一对） 当归 白芍药（酒炒，各一两） \n上以药二味，用水三碗，煎至二碗，去滓，将猪腰切如骰子块，同晚米一合，香豉一钱 \n，加葱、椒、盐煮稀粥。空心日服一次，神效。或加人参更妙。 \n四神散 治产后血虚，或瘀血腹痛。 \n当归（二钱） 川芎 芍药（炒，各一钱） 炮姜（五分） \n上水煎服。 \n\\x大岩蜜汤\\x 治产后阳气虚寒，心腹作痛，不食呕吐，四肢厥逆。 \n生地 当归 芍药（炒） 干姜 吴茱萸 桂心 独活 甘草（炒） 小草（各一两） 细辛（半两） \n上每服半两，水煎服。 \n《良方》\\x人参汤\\x 治产后诸虚不足，发热盗汗，内热晡热等证。此即参归汤，亦名团参散。 \n人参 当归（等分） \n上为末，先以猪腰子一枚切片，糯米半合，葱白二茎，入水二钟，煎汁八分，再入药三钱煎服。 \n\\x白茯苓散\\x 治产后褥劳，头目肢体疼痛，寒热如疟。 \n白茯苓（一两） 人参 当归 黄 川芎 白芍药（炒） 熟地 桂心（各半两） 猪腰（一对） \n上以水三盏，入猪腰并姜、枣各三事，煎二盏，去 ，入前药半两，煎一盏服。 \n《良方》\\x七珍散\\x 治产后不语。 \n人参 石菖蒲 生地 川芎（各一两） 细辛（七钱） 防风 朱砂（另研，各半两） \n上为末。每服一钱，薄荷汤调服。 \n《良方》\\x趁痛散\\x 治产后骨节疼痛，发热头重，四肢不举。 \n牛膝（酒炒） 甘草（炒） 薤白（各一两） 当归 白术（炒） 黄 （炒） 桂心 独活（加姜，各半两） \n上每服半两，水煎。 \n\\x补脬饮\\x 治产后伤动脬破，不能小便而淋沥。 \n生黄丝绢（一尺，剪碎） 白牡丹皮根 白芨（各一钱，俱为末） \n用水一碗，同煮至绢烂如饧。空心顿服。服时不得作声，作声则不效。 \n《良方》\\x止汗散\\x \n牡蛎（ 粉，半两） 小麦麸（八两，炒黄为细末） \n上每服三、五钱，用猪肉汁调服。 \n《良方》\\x麻黄根汤\\x 治产后虚汗不止，身热发渴，惊悸不安。 \n麻黄根 人参 黄 （炒） 当归 牡蛎（ 粉） 甘草（炒，等分） \n上每服四、五钱，水煎服。 \n\\x二味参苏饮\\x 治产后瘀血入肺，咳嗽喘急。 \n人参（一两） 苏木（二两） \n上作一剂，水煎服。若既愈，当用六君子以补脾胃。若口鼻黑气起，宜急用此药加附子 \n五钱，亦有得生者。 \n《良方》\\x黄龙汤\\x 治妊妇寒热头疼，嘿嘿不食，胁痛呕痰，及产后经后外感风寒，热入 \n胞宫，寒热如疟等证。 \n按∶此即小柴胡汤之去半夏也。 \n柴胡（二钱） 黄芩（炒） 人参 甘草（各一钱） \n上用水煎服。 \n（陈氏）\\x二母散\\x 治产后热血上攻，留于肺经，咳嗽喘促。 \n知母 贝母 人参 桃仁 杏仁（俱去皮尖） 白茯苓 \n上等分，每服五钱，姜、水煎服。 \n\\x猪蹄汤\\x 治气血不足，乳汁不下。 \n用八物汤加黄 、漏芦、陈皮、木通，先以猪蹄煮汁二碗，煎药服之。或加天花粉。 \n又方∶用猪蹄一副，通草二两，川芎一两，甘草一钱，穿山甲十四片炒。将猪蹄洗切， \n入水六碗，同药煎煮约至三碗，加葱、姜、盐料，取汁饮之。忌冷物。要吃羹汤助其气血， \n乳汁自下。夏月不可失盖，时用葱汤洗乳为佳。 \n《良方》\\x涌泉散\\x 下乳。忌食姜、椒辛辣饮食。 \n王不留行 瞿麦 麦门冬 龙骨（各二钱） \n上用猪蹄汁一碗，酒一杯，煎服。以木梳于乳上梳下。 \n\\x玉露散\\x 治产后乳脉不行，身体壮热，头目昏痛，大便涩滞。 \n人参 白茯苓 当归 炙甘草（各五分） 桔梗 川芎 白芷（各一钱） 芍药（七分） \n上水煎。食后服。如热甚大便秘结，加大黄三、五分炒用。 \n《良方》\\x漏芦汤\\x 治妇人肥盛，脉气壅结，乳少。 \n漏芦（二两） 蛇蜕（一条） 土瓜根 \n上共为末，酒调下二钱 \n\\x栝蒌散\\x 治吹乳肿痛。 \n栝蒌（一个） 乳香（二钱） \n上用酒煎服。外用南星为末，以温汤调涂。 \n（滑氏）\\x补肝散\\x 治肝肾二经气血亏损，胁胀作痛，或胁胀头晕，寒热发热，或遍身作痛 \n，经候不调。 \n熟地 白术（炒，各一两） 枣仁（炒） 独活（各四两） 当归 川芎 黄 （炒） 山药 五味 \n子（炒，杵） 山茱萸肉 木瓜（各半两） \n上 咀。每服五钱，枣、水煎服。 \n《金匮》\\x胶艾汤\\x 治劳伤血气，冲任虚损，月水过多，淋沥不止。 \n阿胶（炒） 川芎 炙甘草（各一两） 艾叶 当归（各两半） 白芍 熟地（各二两） \n上 咀。每服五钱，水煎服。一方加地榆、黄 ，即名安胎散。 \n《集验》\\x加味八珍汤\\x 治妇人思虑过伤，饮食日减，气血两虚，月经不调，夜梦交感， \n或出盗汗，寝成劳损。 \n人参 白术 茯苓 当归 生地（各一钱） 炙甘草 川芎 芍药 软柴胡 黄 （各五分） \n香附（制） 丹皮（各八分） \n水钟半，大枣一枚，煎七分，食前服。 \n《集验》\\x调卫养荣汤\\x 治妇人室女一切月经不调，或先或后，或绝闭不通，憎寒壮热， \n口苦无味，咳嗽躁烦头眩，渐成劳证者。 \n当归 生地 麦冬 沙参 陈皮 白术（各一钱） 牡丹皮 地骨皮（各八分） 柴胡梢 桔梗 \n（各五分） 谷芽（一钱） 甘草（四分） \n上加莲子、姜、枣，水煎服。痰中见血，加侧柏叶；烦躁口干，加炒山栀，倍麦门冬； \n胁下胀疼，加青皮、川芎；胸膈满闷，加黄连姜炒，枳实，去麦冬、地骨皮；夜出盗汗，加 \n黄连、黄 ，去柴胡、桔梗；大便秘结，加桃仁，倍当归；咳嗽不已，加栝蒌仁、阿胶；小 \n水不利，加木通、茯苓。 \n《良方》\\x当归散\\x 治经水妄行不止，及产后气血虚弱，恶露内停，憎寒发热，宜服此去之。 \n当归（酒洗） 川芎 白芍（炒） 白术（炒） 黄芩（炒，各半两） 山茱萸肉（一两半） \n上为末。每服二钱，酒调。日三服。一方无山茱萸。气虚者，去芩，加桂心一两。 \n《良方》\\x丹参散\\x 《良方》云∶丹参一味，其治颇类四物汤，能破宿血，补新血，安生 \n胎，落死胎，止崩中带下，调经，下产后恶血，兼治冷热劳，腰脊痛，骨节烦疼。 \n丹参（酒洗去土，晾干，切） \n上为细末。每服二钱，温酒调下。经脉不调，食前服。冷热劳，不拘时服。 \n\\x玄胡当归散\\x 亦名延胡索散。治血积小腹疼痛，或因气逆月经不行，肚腹作痛。 \n当归 赤芍药 刘寄奴 没药 枳壳（麸炒） 玄胡索（炒） \n上为末。每服一钱，热酒调下。 \n\\x牛膝散\\x 治月水不利，脐腹作痛，或小腹引腰，气攻胸膈。 \n当归（酒浸） 牛膝（酒炒） 赤芍药 桂心 桃仁（去皮尖） 玄胡索（炒） 牡丹皮（各一两） 木香（三钱） \n上为末。每服一钱，温酒调下。或每服五、七钱，水煎服。 \n《良方》\\x交加散\\x 治经脉不调，腹中撮痛，或结聚 瘕，产后中风。又交加散方在和阵。 \n生地（一斤，取汁） 生姜（十二两，取汁） \n上以地黄汁炒姜 ，姜汁炒地黄 ，干为末。每服三钱，温酒调服。加芍药、 \n玄胡、当归、蒲黄、桂心各一两，没药、红花各五钱，尤效。 \n\\x姜黄散\\x 治瘀血凝滞，肚腹刺痛，或腹胀发热等证。 \n姜黄 当归（酒拌，各二钱） 蓬术（醋炒） 红花 桂心 川芎 玄胡索（炒） 丹皮（各五分） \n上水、酒各半煎服。 \n\\x琥珀散\\x 治心膈迷闷，肚腹撮痛，月信不通等疾。 \n乌药（二两） 当归（酒洗） 蓬术（醋制，各一两） \n上为末。每服二钱，温酒调服。 \n\\x温经汤\\x 治寒气客于血室，以至血气凝滞，脐腹作痛，其脉沉紧。 \n人参 牛膝（酒炒） 甘草（炒，各一钱） 当归 川芎 芍药 牡丹皮 蓬术（醋炒） 桂心（各五分） \n上水煎服。 \n《经验》\\x失笑散\\x 治妇人心痛气刺不可忍，及产后儿枕蓄血，恶血上攻疼痛，并治小肠气痛。 \n五灵脂（净者） 蒲黄（等分，俱炒） \n上为末。每服二、三钱，用酒煎，热服。一方∶用好醋一杓熬成膏，再入水一钟，煎至 \n七分，热服。一方∶用醋糊和丸，龙眼大，每服一丸，以童便和水各半钟，煎七分，温服。 \n按∶此方若用以止痛，蒲黄宜减半；若用止血，则宜等分，或灵脂减半亦可。 \n\\x泽兰汤\\x 治劳怯经闭。 \n泽兰叶（二钱） 当归 芍药（炒，各一钱） 甘草（炙，五分） \n用水煎服。 \n\\x当归没药丸\\x 治血瘀作痛，及血风筋挛骨痹，手足麻木疼痛。 \n当归 五灵脂（炒，各一两） 没药（五钱） \n上为末，醋糊丸，桐子大。每服三十丸，姜汤下。 \n\\x醋附丸\\x 治元脏虚冷，月候不调，腹中急痛，赤白带下，浑身寒热，胎气壅滞不固。 \n香附米（半斤，醋煮，焙干为末） \n上以醋糊为丸，桐子大。每服三、四十丸，米饮下。 \n\\x柏子仁丸\\x 治血虚有火，月经耗损，渐至不通，日渐羸瘦而生潮热，慎勿以毒药通之， \n宜柏子仁丸，或前泽兰汤主之。 \n柏子仁（炒研） 牛膝（酒拌） 卷柏（各半两） 泽兰叶 续断（各二两） 熟地黄（三两，酒拌蒸 \n烂，杵膏） \n上为末，入地黄膏加炼蜜丸，桐子大。每服百余丸，空心米饮下。 \n\\x乌贼鱼骨丸\\x 此即《内经》治血枯方。 \n乌贼鱼骨（去甲，四两） 芦茹（一两，即茜根） \n上为末，以雀卵捣丸，小豆大。每服五丸，或十丸，鲍鱼煎汤下，以饭压之。鲍鱼即今 \n之淡干鱼也。 \n\\x增损四物汤\\x 治脾虚不摄，血去不止。 \n人参 当归 芍药（炒） 川芎 干姜（炒，各一两） 甘草（炙，四钱） \n上每服四钱，水煎服。 \n《奇效》\\x四物汤\\x 治肝经虚热，血沸腾而崩，久不止。 \n当归（酒拌） 熟地 白芍 川芎 阿胶（炒） 艾叶（炒） 黄芩（各半两） \n上每服四钱，水煎。 \n《良方》\\x加减四物汤\\x 治妇人血积。 \n当归 川芎 芍药 熟地 蓬术 三棱 肉桂 干漆（炒烟尽，等分） \n上 咀。每服五、七钱，水钟半，煎七分，食远服。 \n\\x四物二连汤\\x 治妇人血虚发热，或口舌生疮，或昼安夜热。 \n当归 川芎 芍药 熟地 胡黄连 宣黄连（各一钱） \n上作一剂，水煎服。 \n\\x人参当归汤\\x 治去血过多，内热短气，头痛闷乱，骨节作痛，或虚烦咽燥。 \n人参 当归 生地 桂心 麦冬 白芍药（各等分） \n上用粳米一合，竹叶十片，水二钟，煎一钟，去米入药五钱，枣二枚，煎服，或总煎之 \n亦可。虚甚者用熟地黄。 \n《良方》\\x一味防风散\\x 治肝经有风，以致血得风而流不归经者。 \n用防风去芦为末。每服一钱，白汤调服。一名独圣散，每服二钱，空心食前，用酒煮， \n白面清饮调下，极效。"}, {"n": 38, "text": "卷三十八\n\n\\x龙骨散\\x 治血崩不止。 \n龙骨（ ） 当归 香附（炒，各一两） 棕毛灰（五钱） \n上为细末。每服四钱，空心米汤调下。忌油腻、鸡、鱼炙爆物。 \n\\x如圣散\\x 治血崩，三服全愈。 \n棕榈子 乌梅肉 干姜（俱烧存性，为末，各等分） \n上每服二钱，空心乌梅汤调服。一方单用棕皮，半烧半生，为末，每空心服二钱亦妙。 \n\\x槐榆散\\x 治血崩及肠风下血。 \n槐花 地榆（等分，炒焦） \n上二味，用酒煎饮之。 \n\\x七灰散\\x 治血崩神效。 \n莲蓬壳 罂粟壳 腌蟹壳 益母草 旱莲草 棕毛叶 藕节（各等分，俱烧存性为末） \n空心醋点汤调下三钱。一秘方用棉花子，以铜锅炒黑为末，黄酒调下二、三钱，三、两 \n次即止，并治崩漏、小产血不止。 \n\\x棕灰散\\x 方在和阵。治大肠下血，及崩漏失血。 \n\\x柏叶散\\x 治元气虚弱，崩中漏血，年久不愈，亦治白带。 \n柏叶（炒） 当归 生地 续断 川芎 龟甲（炙） 禹余粮（各一两半） 阿胶（炒，五钱） 鳖 \n甲（炙，两半） 赤石脂（ ） 牡蛎（ ） 地榆 艾叶（炒） 鹿茸（炙，各五钱） \n上为末。每服二钱，粥饮调下。 \n\\x子芩散\\x 一名黄芩散。治壮热崩中下血，是阳乘阴分，故经血泛溢，宜清其北方。 \n条黄芩不拘多少为细末。） \n上烧秤锤粹酒，食前调下三、四钱。一方有干姜、白芷。一方以木耳、黄芩等 \n分为丸，俱效。 \n《良方》\\x防风黄芩丸\\x 治肝经风热，以致血崩便血尿血等证。 \n条芩（炒黑） 防风（等分） \n上为末，酒糊丸，桐子大。每服三、五十丸，食远，或食前，米饮，或温酒送下。 \n\\x劫劳汤\\x 治劳嗽发热，盗汗体瘦，唾中有血，或成肺痿。此救本也，非劫劳也，能用此 \n者，庶可望生，此外恐非佳剂矣。 \n白芍药（炒，一钱） 人参 黄 （炒） 当归 熟地 甘草（炒） 白茯苓 五味子（杵炒） \n阿胶（炒） 半夏（制，各五分，此上乃其原方，似有不足用者，仍宜加倍） \n上姜、枣、水煎，日三服。乡人杨元鼎女，及笄病此甚危，百药无效，偶遇名医，得此 \n方服三十余剂，遂愈不发。 \n《集验》\\x归神汤\\x 治妇人梦交盗汗，心神恍忽，四肢乏力，饮食少进。 \n人参 白术 白茯苓 归身（各一钱） 枣仁 陈皮（各八分） 圆眼肉（七枚） 甘草 羚羊角 \n琥珀（末，各五分） \n上羚羊、琥珀二味不煎，余药煎熟去 ，入二末和匀。食前服。 \n\\x白芷散\\x 治下元虚弱，赤白带下，或经行不止等证。 \n白芷（一两） 海螵蛸（二枚，烧） 胎发（一团， ） \n上为末。每服二钱，温酒调下。 \n（海藏）\\x白芍药散\\x 治妇人赤白带下，脐腹疼痛，如神。 \n白芍（二两，炒） 干姜（半两，炒） \n上为细末。每服三钱，空心温米汤调下，晚又进一服，十日见效。 \n\\x克应丸\\x 治妇人赤白带下。 \n熟地 赤芍（各二两） 当归（二两） 赤石脂（ ，醋淬） 龙骨 牡蛎（ ，酒淬） 茯苓 丹 \n皮艾叶（制） 川芎（各一两） \n上为末，醋糊丸，桐子大。每服五十丸，空心白汤送下。 \n《良方》\\x滑石散\\x 治热淋。 \n滑石（五分，研） 通草 车前子 葵子（各四分） \n上为末，以浆水调服。 \n\\x芍药散\\x 治妇人血滞腰胁痛。 \n白芍药 玄胡（炒） 肉桂（各一两） 香附米（二两，醋一升，盐半两，同煮干） \n上为细末。每服二钱，不拘时，白汤调下。 \n《良方》\\x通气散\\x 治肾虚腰痛神效。 \n破故纸（酒炒为末） \n上每服二钱，先嚼胡桃肉半个，空心以温酒送下。 \n\\x四制香附丸\\x 调经养血，顺气受孕。 \n香附米（一斤，分四制，酒、醋、童便、米泔各浸一宿，晒干用） 当归（酒洗） 熟地（酒 \n洗） 白芍药（四两） 川芎（各四两） 泽兰叶 白术 陈皮（各三两） 黄柏（酒炒） 甘草（酒炒，各一两） \n上为末，酒糊丸，桐子大。每服七十丸，空心白汤送下。 \n《大典》\\x女金丹\\x 此韩飞霞方也，一名不换金丹。内加熟地黄一两，即名胜金丹。治妇 \n人久虚无子，及产前产后一切病患。此药能安胎催生，妊娠临月服五、七丸，产时减痛。妇 \n人子宫寒冷无孕，如服月余，男女自至。又治半身不遂，带浊血崩，及产后腹痛吐逆，子死 \n腹中，气满烦闷，脐腹作痛，月水不通，中风口噤，痢疾消渴，败血上冲，头疼寒热，血运 \n血泄，见鬼迷闷，产后伤寒，虚烦劳瘦。凡妇人诸疾，不问久近，并宜服之，兼治男子下虚 \n无力等证。 \n人参 白术（炒） 茯苓 炙甘草 当归 川芎 白芍 白薇（酒洗） 丹皮 白芷 本 \n肉桂 玄胡 没药（另研） 赤石脂（另研，上各一两） 香附（醋浸三日，炒香，十五两） \n上共十六味，为末，炼蜜丸，弹子大，以瓷瓶收贮封固。每服一丸，空心温酒化下，食 \n干物压之；服至四十九丸为一剂，以癸水调平受妊为度。妊中三、五日服一丸，产后二、三 \n日服一丸。醋汤下亦妙。 \n\\x琥珀丸\\x 治妇人或老或少，或产前产后百病，及疗三十六种诸病，七疝八瘕，心腹刺痛 \n，卒中瘫痪，半身不遂，八风十二痹，手足酸疼，乳中结核结毒，怀胎惊动，伤犯不安 \n，死胎不下并治。 \n琥珀 朱砂（各另研） 沉香 阿胶（炒珠） 附子（制） 川芎 肉桂 五味子 石斛（各五 \n钱） 牛膝（酒浸） 当归 肉苁蓉（酒洗，晒） 人参 熟地 续断 木香 没药（各一两） \n一方有牛黄、珍珠、乳香、玄胡（各一两，共二十一味）。 \n上炼蜜为丸，弹子大。每服一丸，空心、食前、午后温酒化开服。凡服法或姜汤，或米 \n汤，或酒，或灯草汤，或随证用引，皆可下。若伤寒中风，角弓反张，用麻黄汤随证改汤引 \n送下。孕妇临月，宜一日一服，至产顺利，不觉疼痛。凡妇人服至五服十服之后，日倍饮食 \n，其功言不尽述，服者当自觉也。 \n\\x延年益嗣丹\\x 滋补元气，益精黑发。按∶此方即还元丹也，但制法分两不同，宜参酌用 \n之。方在补阵。 \n人参 天门冬（酒浸，去心） 麦门冬（同上，各三两） 熟地黄（酒蒸，捣） 生地黄（各二两） \n白茯苓（酒浸，晒干） 地骨皮（酒浸，各五两） 何首乌（鲜者，半斤） \n上将何首乌去皮切片，如干者用米泔水浸软拈切，外用砂锅入黑羊肉一斤，黑豆三合， \n量着水，上用甑箅，箅上放首乌煮而蒸之，以肉烂为度。锅盖须密，勿令泄气。取起晒干为 \n末，炼蜜丸，梧子大。每服七、八十丸，空心温酒送下。 \n\\x续嗣降生丹\\x 治妇人五脏虚损，子宫冷惫，不能成孕。并治男子精寒不固，阳事衰弱， \n白浊梦泄，妇人带下寒热，诸虚百损，盗汗短气，无不感应。此方乃温隐居《求嗣保生篇》 \n所载，云东京焦员外三世无嫡嗣，后遇一神僧，问其故。曰∶无嗣者有三∶一、祖宗无德， \n自身无行；二、夫妻年命恐犯禁忌；三、精神不守，妻外家血寒。焦公曰∶治之有道乎？僧曰 \n∶先修德，后修身。三年之后到台山，令行童赐以方药，名续嗣降生丹，根据方服之，后不及 \n二十年，子孙数人皆贵显。此方无怪诞克伐之品，且温且固，凡血海虚寒者，服之必佳。但 \n温力有余，补力不足，倘益以人参、白术、熟地、川芎、炙甘草各一两，则八珍全而温补赞 \n育之功当非浅也，因命名曰加味续嗣降生丹。 \n当归（酒洗） 杜仲（酒炒） 茯神 益智仁 龙骨（ ） 桂心 吴茱萸（制） 干姜（半生 \n半熟） 川椒（去目） 台乌药（各一两） 白芍药（酒炒） 川牛膝（酒浸） 半夏（制） 防风 秦 \n艽石菖蒲（去毛） 北细辛 桔梗（各五钱） 附子（一枚，重一两者，脐下作一窍，入朱砂一钱 \n，面裹煨熟，取出朱砂，留为衣） 牡蛎（大片者，以童便浸四十九日，每五日一换，取出， \n用硫黄一两为末，酒和涂遍，用皮纸糊实，米醋浸湿，外以盐泥浓固之，候干，用炭五斤 \n过为末。每料止用二两，余可收贮再用） \n上为末，以酒煮糯米糊为丸，梧子大，以前朱砂为衣。每服三、五十丸，渐至七、八十 \n丸，空心滚白汤，或盐汤，温酒下。 \n\\x河车种玉丸\\x \n紫河车（一具，只要母气壮盛、浓大新鲜者，但去胞内瘀血，不必挑去鲜红血脉，以米泔 \n水洗净，用布绞干，石臼内生杵如糊，用山药末四、五两收干，捻为薄饼八、九个，于砂锅 \n内焙干，以香如肉脯为妙） 大熟地（酒洗烘干，八两） 枸杞（烘干，五两） 白茯苓（人乳拌晒三 \n次） 归身（酒洗） 人参 菟丝（制） 阿胶（炒珠，各四两） 丹皮（酒洗） 白薇（酒洗，各二两） \n沉香（一两） 桂心 山茱萸 香附米（用酒、醋、水三件各半碗，浸三日，晒干略烘，各三两） \n大川芎（酒浸，切片晒干，二两） \n上炼蜜和丸，桐子大。每服百余丸，空心或酒，或白汤、盐汤任下。如带浊多者，加赤 \n、白石脂各二两，须以清米泔飞过用。服药后忌生萝卜、生藕、葱、蒜、绿豆粉之类。 \n\\x八珍益母丸\\x 治血气两虚，脾胃并弱，饮食少思，四肢无力，月经不调，或腰酸腹 \n胀，或断或续，赤白带下，身作寒热，罔不获效。服一月之后即可受胎；虚甚者，用药一 ，必能受子。 \n人参 白术（土炒） 茯苓 川芎（各一两） 当归（酒洗） 熟地（酒洗，各二两） 炙甘草（五钱） \n芍药（醋炒，一两） 益母草（四两，五六月采取，止用上半截带叶者，不见铁器，晒，杵为末） \n上为末，炼蜜丸，弹子大。空心蜜汤，或酒下一丸。或为小丸亦可。脾胃虚寒多滞者， \n加砂仁一两，姜汁炒；腹中胀闷者，加山楂肉一两，饭上蒸熟；多郁者，加香附一两，酒制 \n。此徐思鹤《医统》方。又一方名八珍益母十全丸，于前方内用益母草八两，外加沉香四钱 \n。思鹤曰∶资益坤元，补养气血，除淋带，壮形体，胎前和气，产后补虚，真妇人之圣剂， \n超古今之神方，有室家者不可不知也。予哂斯世之医，惟集古方香附胜金丹为女人开郁调经 \n之要药，殊不审古今虚实之异。古人气实，故可用香附开导，香附味辛性燥，但能开破而已 \n，多用之大耗气血，虚者愈甚，病者愈甚，而于滋补何有哉？今世十妇九虚，非补不可，再 \n用香附以耗之，寝成怯弱之证，是辨之不早，则危殆而难痊矣。妇人经脉不调，或气血两虚 \n而身体素弱者，宜服此以调养之。经不通者，服一料即通；不调者，一月即调。素不孕者， \n服一月即孕。胎前间用一服，则胎固而安。产后用一服，以童便、酒化开调下，则无壅滞血 \n运之候。多服之补虚活血，凡治产后诸病极稳。若急欲取效，以酒调化服。 \n\\x乌鸡丸\\x 治妇人羸弱，血虚有热，经水不调，崩漏带下，骨蒸不能成胎等疾。 \n乌骨白毛公鸡（一只，重二斤半许者，闭杀之，去毛杂。外用艾叶四两，青蒿四两，切碎 \n，纳一半在鸡肚内。以小酒坛一个，入鸡并所剩蒿艾，用童便和水灌令没鸡二寸许，煮绝干 \n，取出去骨。余俱同捣如薄饼，焙干为细末听用） 南香附（去毛净，一斤，分四分，用米泔、 \n童便、酒、醋各浸一分，春秋一、二日，夏一日，冬四日。取出晒干，略炒） 人参 熟地 \n当归（酒浸洗） 生地 川芎 白芍（各三两） 黄 白术 川牛膝 柴胡 知母 丹皮（各二 \n两） 鳖甲（醋浸炙黄，三两） 白茯苓（二两半） 秦艽（一两半） 黄连（炒） 地骨皮 贝母 玄胡索 \n干姜（炮焦，各一两） \n上俱为末，用酒、醋各半煮糊为丸，桐子大。每服五、六十丸，渐加至百丸，温酒、米 \n饮任下。忌煎炒辛辣等物及苋菜。 \n\\x又乌鸡丸\\x \n熟地 当归 白术 山药 山茱萸 枣肉 柿饼 莲肉（各四两） 黄 （蜜炙，三两） 鹿角 \n胶狗脊 杜仲 枸杞 莲须 香附 阿胶 川芎（各二两） 乌药（一两半） \n上药制净，用乌骨鸡一只，闷杀之，干去毛去杂，连骨椎碎，用酒、醋各半同药煮熟， \n去骨烘干，共为末，即将余汁少入面打糊为丸。任意用引送下。 \n（唐氏）\\x乌鸡丸\\x \n人参 怀生 怀熟 青蒿子（去梗） 香附（四制） 鳖甲（各三两） 白术 枣仁肉 枸杞 \n麦冬 云苓 地骨皮（去骨） 丹皮（去骨） 白芍（各二两） 归身（二两半） 川芎 甘草（各一两） \n上先将诸药备完听用，乃取丝毛乌骨白公鸡一只，约重一斤许者，扑倒，去毛秽头足肠 \n杂不用，将鸡切作四块。先以鳖甲铺铜锅底，次入杂药以免焦腐，渐渐加童便约至斗许，煮 \n至极烂捞起，晒干为末。将鳖甲去裙，并鸡骨俱以原汁醮炙至干，为末，同前药炼蜜为丸， \n桐子大。每空心用清汤送下百余丸。 \n《秘方》\\x乌鸡煎丸\\x 治妇人百病，血气虚劳，赤白带下。 \n人参 官桂 地骨皮（各二两） 茯苓（三两） 黄 （蜜炙） 当归（各六两） 生地 熟地 香附（各四两） \n上将乌骨白鸡一只，男用雌，女用雄，笼住。将黄 末和炒面丸如芡实，喂鸡二、七日 \n，将鸡缚死，干扫去毛，并肠杂令净，捶碎其骨，入前药于腹内缝密，用酒、醋各一瓶煮一 \n宿，取去骨，焙干为末，用前汁打面糊丸，桐子大。每服五、六十丸，空心盐汤下。 \n\\x万病丸\\x 治月经瘀闭，脐腹作痛，及产后 瘕等病。 \n干漆（炒烟出青白为度） 牛膝（酒洗，焙，各一两） \n上为末，生地黄汁一升，用砂锅慢火熬膏丸，桐子大。每服二十丸，空心米饮下。 \n\n\n\n<目录>卷之六十一长集·妇人规古方\\妇人\n\n<篇名>以下通用方\n\n属性：\\x四君子汤\\x 方在补阵。治脾肺气虚诸证。 \n\\x六君子汤\\x 方在补阵。治脾胃虚弱，呕吐吞酸等证。 \n\\x五味异功散\\x 方在补阵。治脾胃虚寒，饮食少思等证。 \n\\x补中益气汤\\x 方在补阵。治劳倦伤脾，外感不解，寒热疟痢，气虚不能摄血等证。 \n\\x四物汤\\x 方在补阵。治一切血虚劳弱之病。 \n\\x八珍汤\\x 方在补阵。治气血两虚，调和阴阳。 \n\\x十全大补汤\\x 方在补阵。治气血俱虚，补救元阳。 \n\\x归脾汤\\x 方在补阵。治心脾虚损。 \n\\x人参理中汤\\x 方在热阵。温中，补脾胃虚寒诸证。 \n\\x逍遥散\\x 方在补阵。治肝脾血虚，郁怒伤肝等证。 \n\\x加味逍遥散\\x 方在补阵。治肝脾血虚发热等证。 \n\\x七味白术散\\x 方在小儿。治虚热作渴。 \n\\x六味地黄丸\\x 方在补阵。壮水制火之剂。 \n\\x八味地黄丸\\x 方在补阵。治命门火衰之剂。 \n（薛氏）\\x四神丸\\x 方在热阵。治脾胃虚寒泄痢。 \n\\x五积散\\x 方在散阵。治感冒寒邪。 \n\\x参苏饮\\x 方在散阵。治四时伤寒感冒。 \n\\x人参败毒散\\x 方在散阵。治四时伤寒瘟疫。 \n\\x当归六黄汤\\x 方在寒阵。治血热阴虚盗汗。 \n\\x柴胡清肝散\\x 方在寒阵。治肝胆风热，疮疡，怒火寒热。 \n\\x栀子清肝散\\x 方在寒阵。治肝胆三焦风热。 \n\\x八正散\\x 方在寒阵。治脏腑秘结，小便赤涩。 \n\\x五苓散\\x 方在和阵。治小便不利。 \n\\x犀角地黄汤\\x 方在寒阵。治心火动血，及斑黄疮疹。 \n\\x导赤散\\x 方在寒阵。治心火及小肠热秘淋涩。 \n\\x桃仁承气汤\\x 方在攻阵。治瘀血小腹作痛，其人如狂。 \n\\x玉烛散\\x 方在攻阵。治血虚有滞，经闭不通。 \n\\x肾着汤\\x 方在热阵。治肾虚身重腰冷。 \n\\x舒筋汤\\x 方在和阵。治产后血滞作痛。 \n\\x交加散\\x 方在和阵。治产后口吐涎沫，不省人事。 \n\\x加味小柴胡汤\\x 方在散阵。治乳母肝火发热。 \n《良方》\\x蜜酥煎\\x 方在补阵。补虚润肺，止咳嗽。 \n\\x柴胡石膏汤\\x 方在散阵。治少阳阳明外感挟火，发热头痛。 \n\\x都梁丸\\x 方在散阵。治胎前产后伤风头痛。 \n\\x瓜子仁汤\\x 方在外科。治产后瘀血、肠痈，腹中 痛。 \n（子和）\\x通经散\\x 方在攻阵。治气逆经闭。 \n\\x二神散\\x 方在寒阵。治吐血，血崩下血。 \n\\x小蓟饮子\\x 方在寒阵。治小焦结热，溲血崩淋。 \n（海藏）\\x愈风汤\\x 方在和阵。治一切失血及产后搐搦。 \n\\x锁精丸\\x 方在固陈。治白浊白带。 \n\\x青蛾丸\\x 方在补阵。治肾虚腰痛。 \n\\x独参汤\\x 方在补阵。治诸气虚脱。 \n\\x夺命散\\x 方在补阵。治阳邪伤气暴脱，烦躁发渴。 \n\n\n\n<目录>卷之六十二长集·小儿则古方\n\n<篇名>小儿\n\n属性：（《秘旨》）\\x补脾汤\\x（一） 治小儿久病，面黄肌瘦，切牙目札，头发稀少，误药所致。 \n人参 白术（各一钱） 白芍药（酒炒） 白茯苓（各八分） 川芎 陈皮（各六分） 炙甘草 \n黄（蜜炙） 当归（各四分） \n上每服二三钱，姜、水煎。 \n\\x调中汤\\x（二） 治伤乳食泻后，脾胃虚哕吐泻。 \n人参 茯苓 干姜（炒） 藿香 白术 甘草（炙） 木香 丁香 香附（炒，去毛） \n砂仁（等分） \n上水煎。食前服。 \n\\x调中丸\\x（三） 治脾胃虚寒吐泻。 \n人参 白术（炒） 甘草（炒，各五钱） 干姜（炮，四钱） \n上为末，蜜丸，绿豆大。每服二三十丸，白汤下。薛按云∶前二方乃本经自病之药， \n即人参理中丸也。若肾水侮土而虚寒者，当加半夏、茯苓、陈皮，或呕吐，更加藿香，泄泻 \n加木香。 \n\\x人参理中丸\\x（四） 治中气虚热。 \n人参 白术（炒） 炙甘草（等分） \n上为末，姜汁糊丸，绿豆大。每服二三十丸，白汤下。 \n（《局方》）\\x观音散\\x（五） 治内伤呕逆吐泻，不进饮食，渐至羸瘦。 \n人参（一两） 神曲（炒） 茯苓 炙甘草 绵黄 白术（炒） 白扁豆（炒） 木香（各一钱） \n石莲肉（去心，钱半） \n上为末。每服一二钱，入藿香三叶、姜、枣，水煎服。 \n\\x助胃膏\\x（六） 治脾胃虚寒，吐泻，饮食不化等证。 \n人参 白术（炒） 茯苓 甘草（炙） 丁香（各五钱） 山药（一两，炒） 砂仁（四十个） \n木香（三钱） 白豆蔻（十四个） 肉豆蔻（面煨，四个） \n一方无木香，名香砂助胃膏。 \n上为末，蜜丸，芡实大。每服十丸，米饮化下。 \n（钱氏）\\x七味白术散\\x（七） 一名人参白术散。治虚热而渴。 \n人参 白术 白茯苓 炙甘草 藿香 木香（各一钱） 干葛（二钱） \n上为末。每服三钱，水煎温服。如饮水多，多服之为妙。按∶此方治小儿虚热而渴，如 \n无气滞吐泻等证，则当减去木香、藿香，以避燥而耗气。 \n\\x白术散\\x（八） 方在和阵三十。治自汗盗汗极效。 \n\\x太和饼\\x（九） \n人参 白术 白茯苓（各五钱） 山药（炒，四钱） 木香 炙甘草（各一钱） 肉果（面煨， \n四个） 白豆蔻（十四个） 砂仁（十四个） 山楂肉（一两） 使君子肉（六十个） \n炼蜜捣和为小饼。量儿大小与服。或再对证加减药味用之。 \n\\x团参散\\x（十） 治心虚血热，自汗盗汗。 \n人参 当归（等分） \n上为末。用雄猪心一个，切三片，每服二钱，以猪心一片煎汤调服，或用水煎服亦可。 \n\\x止汗散\\x（十一） 一名败蒲散。治睡而自汗。 \n故蒲扇（烧存性） \n上为末。每服三钱，温酒调下。 \n\\x调元散\\x（十二） 治小儿变蒸，脾弱不乳，吐乳多啼。 \n人参 白术 陈皮 浓朴（制） 香附（各一钱） 炙甘草 藿香（各五分） \n上每服一二钱，姜、枣煎服。 \n\\x平和饮子\\x（十三） 治小儿变蒸，于三月后，每三日进一服，可免百病，百日内宜服。 \n人参（一钱半） 白茯苓（一钱） 炙甘草（五分） 升麻（二分） \n上咀，水半盏，煎三分。不时服。弱者加白术一钱。 \n\\x调气散\\x（十四） 治变蒸吐泻，不乳多啼，欲发慢惊。 \n人参 陈皮 木香 藿香 香附 炙甘草（各一钱） \n上为末。每服一钱，姜、枣、水煎服。 \n（钱氏）\\x当归散\\x（十五） 治夜啼不乳。 \n人参 当归 白芍药（各二钱半） 炙甘草（钱二分） 桔梗 陈皮（各一钱） \n上每服一二钱，水煎灌之。 \n（《撮要》）\\x当归散\\x（十六） 治变蒸有寒无热。 \n当归（二钱） 人参 炙甘草 木香 官桂（各一钱） \n上每服二三钱，姜、枣、水煎。 \n\\x人参黄连散\\x（十七） 治心经蕴热夜啼。 \n人参（二钱半） 黄连（钱半，炒） 炙甘草（五分） 竹叶（二十片） \n上姜、水煎服。 \n（无择）\\x灯花散\\x（十八） 治心躁夜啼。 \n灯花（二三颗） \n上研细，用灯草煎汤调涂口中，乳汁送下，日三服。一法用灯花涂乳上，令儿吮之。如 \n无灯花，用灯草烧灰，加辰砂少许亦妙。一法用灯花七枚，硼砂一字，辰砂少许，蜜调涂唇上， \n立安。 \n（《宝鉴》）\\x天麻散\\x（十九） 治小儿急慢惊风，发热抽搐，痰涎壅盛，或脾土虚弱， \n肝木乘侮，吐泻不食，嗜卧困倦。 \n半夏（七钱） 天麻（二钱半） 甘草（炙） 白茯苓 白术（各三钱） \n上为末。每服一二钱，姜枣汤调服。 \n（汤氏）\\x异功散\\x（二十） 止渴，消暑，生津，补脾胄。 \n猪苓 泽泻（各三钱） 人参 白术 茯苓（各五钱） 陈皮（二钱半） 朱砂（一钱） \n上为末，蜜丸，芡实大。每服一丸，灯心竹叶汤化下。 \n\\x柴胡散\\x（二一） 治变蒸骨热，心烦啼叫不已。 \n人参 炙甘草 麦冬（各二钱） 龙胆草（酒炒黑） 防风（各一钱） 柴胡（五分） \n上每服二三钱，水煎。 \n\\x柴苓散\\x（二二） 治壮热来去。 \n柴胡 赤茯苓 人参 麦冬 甘草（各半两） 黄芩（一两） \n上每服二三钱，入小麦二十粒，青竹叶三片，水煎服。 \n\\x惺惺散\\x（二三） 治小儿伤寒时气，风热头痛目眵，多睡痰壅，咳嗽喘急，或痘疹已出 \n未出，疑似之间。 \n人参 白术（炒） 茯苓 甘草 北细辛 川芎 桔梗（炒，各等分） \n上为末。每服一钱，入薄荷五叶，水煎服。一方有防风、天花粉。 \n\\x星苏散\\x（二四） 治诸风口噤不语。 \n南星（略炮，切） \n上每服五七分，紫苏五叶，姜四片，水煎入雄猪胆少许。温服。 \n（钱氏）\\x黄龙散\\x（二五） 治发热不退，或往来寒热。 \n柴胡（五钱） 赤芍药（三钱） 黄芩（炒） 甘草（炙，各二钱） \n上每服二三钱，姜、枣、水煎。 \n\\x人参羌活散\\x（二六） 治伤风惊热。 \n人参 羌活 川芎 白茯苓 柴胡 前胡 独活 桔梗 枳壳 地骨皮 天麻（各等分） \n炙甘草（减半） \n上用生姜薄荷水煎。治惊热加蝉蜕。 \n\\x牛黄散\\x（二七） 治温热壮热，或寒热往来。 \n牛黄（研） 甘草（各半两） 柴胡 栀子（酒炒） 龙胆草（酒炒） 黄芩（炒，各二钱半） \n上为末。每服五七分，以金银薄荷汤调下。 \n（钱氏）\\x生犀散\\x（二八） 治心经风热。 \n犀角（镑三钱） 柴胡 葛根 赤芍药 地骨皮（各一两） 甘草（五钱） \n上为末。每服一二钱，水煎。 \n\\x二黄犀角散\\x（二九） 治温热心神不安，火腑秘结。 \n犀角屑 大黄（酒浸蒸） 钩藤钩 栀子仁 甘草 黄芩（等分） \n上为末。每服五七分，热汤调下，量儿加减。 \n\\x柴胡饮子\\x（三十） 解肌热蒸热积热，或汗后余热，脉洪实弦数，大便坚实者。 \n柴胡 人参（各五分） 黄芩 芍药（各七分） 当归（一钱） 甘草（四分） 大黄（八分） \n上每服一二钱，水煎。按∶此方用药颇善，但大便如常者，勿得轻用大黄。 \n\\x地骨皮散\\x（三一） 治虚热壮热。 \n地骨皮 知母 人参 柴胡 茯苓 半夏 甘草（等分） \n上姜、水煎。有惊热，加蝉蜕、天麻、黄芩。 \n\\x天麻定喘饮\\x（三二） 治喘嗽惊风。 \n天麻 防风 羌活 白术 甘草（炒） 人参 桔梗 川芎 半夏曲（等分） \n上每服二三钱，水煎服。 \n\\x补肺散\\x（三三） 一名阿胶散。治肺虚恶心喘急，久患咳嗽有痰。 \n阿胶（两半，炒） 鼠粘子（炒） 马兜铃（各半两） 杏仁（七粒） 糯米（一两） 甘草（三钱） \n上每服二三钱，水煎服。 \n（钱氏）\\x阿胶散\\x（三四） 治小儿肺病，咳嗽喘急，或咳而哽气，喉中有声。 \n阿胶（蛤粉炒，一两） 鼠粘子（炒香，二钱半） 炙甘草（一钱） 马兜铃（半两） 杏仁（七个， \n去皮尖） 糯米（一两） \n上每二三钱，水煎。 \n（丹溪）\\x保和丸\\x（三五） 治饮食酒积停滞胸膈，痞满腹胀。 \n神曲（炒） 陈皮 半夏 茯苓（各一两） 山楂肉（蒸晒，三两） 连翘 萝卜子（炒，各五钱） \n上为末，粥丸，绿豆大。一方尚有炒麦芽一两，黄连五钱。 \n\\x大安丸\\x（三六） 治证同前。即前保和丸加白术二两。 \n（杨氏）\\x消食丸\\x（三七） 治乳食过多，胃气不能消化。 \n砂仁 陈皮 神曲（炒） 麦芽（炒） 三棱 蓬术（各半两） 香附（炒，一两） \n上为末，面糊丸，麻子大。白汤送下，量儿加减。 \n\\x消乳丸\\x（三八） 治呕吐，消乳食。脉沉者，伤食不化也。 \n香附（炒） 砂仁 陈皮 神曲（炒） 炙甘草 麦芽（炒，等分） \n上为末，米糊丸黍米大。每服二十丸，姜汤下。 \n\\x白饼子\\x（三九） 治伤食腹中有癖，呕吐肚疼。先用此药一服，推下食积，然后调治，不 \n可服冷药。 \n滑石 轻粉 半夏（汤浸焙） 南星（各一钱） 巴豆（二十四粒，去皮膜，用水一升煮干， \n研烂） \n上为末，糯米饭丸，绿豆大。捻作饼，每服二三饼，煎葱白汤、紫苏汤下，忌热物，量儿加 \n减。 \n薛曰∶凡用此方及利惊丸、紫霜丸、三味牛黄丸、褊银丸之类，乃斩关夺门，起死回生之 \n重剂也，必审形病俱实，方可施之，巩至失手，命在反掌。经云∶邪之所凑，其气必虚。留而不 \n去，其病乃实，实者病气实，而形气则虚也。东垣先生云∶形病俱实者，当泻不当补；形病俱虚 \n者，当补不当泻。治者审焉。 \n\\x宣风散\\x（四十） 治湿痰、去积滞，通秘结，攻黑陷里实，以代百祥丸、牛李膏。 \n槟榔（二个） 陈皮 甘草（各五钱） 牵牛（四两，半生半炒，取头末一两） \n上为末。每服一钱，量大小增减与服，白汤调下。一方有大黄、木香，连前三味煎成后， \n加牵牛末调服。 \n\\x人参养胃汤\\x（四一） 治外感风寒，内伤生冷，寒热如疟，或呕逆恶心。 \n人参 浓朴（姜制） 苍术（炒） 半夏（制） 草果仁 藿香 茯苓（各五钱） 橘红（二钱半） \n炙甘草（二钱） \n上每服二三钱，姜三片，乌梅一个，水煎。 \n\\x人参安胃散\\x（四二） 治脾胃虚弱，伤热乳食，呕吐泻痢。 \n人参（一钱） 黄 （二钱） 生甘草 炙甘草（各五分） 白芍药（酒炒，七分） 白茯苓（四分） \n陈皮（三分） 黄连（炒，一分） \n上每服二三钱，水煎。 \n\\x生附四君汤\\x（四三） 治吐泻不思乳食，凡虚冷病，宜先与数服以正胃气。 \n人参 白术 茯苓 炙甘草 附子 木香 橘红（等分） \n上为末。每服一二钱，姜、枣、水煎服。 \n\\x酿乳法\\x（四四） 治胃虚吐泻，睡中吐舌摇头，呕乳，额上汗流，惊啼面黄，令儿饥饮。 \n人参 藿香 木香 沉香 陈皮 神曲（炒） 麦芽（炒，各等分） 丁香 \n上每服四五钱，姜十片，紫苏十叶，枣三枚，水煎。每服半盏。令母食后捏去旧乳 \n方服，卧少时却与儿饮。 \n按∶小儿不能饮药者，凡用补泻诸剂皆宜此法。 \n\\x银白散\\x（四五） 治胃虚吐泻。 \n糯米（炒，二两半） 扁豆（蒸，二两） 白术（炒，一两） 炙甘草（三钱） 丁香 藿香（各二钱） \n上为末。紫苏米饮调下。《直指方》加炮白附子、全蝎、木香、石莲子、姜，水煎。 \n\\x朱君散\\x（四六） 治吐泻后而为惊为泻及粪青者。 \n人参 白术 茯苓 炙甘草 钩藤钩 朱砂（各一钱） 麝香（半分） 灯心（一团） \n上为末。每服一钱，白汤调下。 \n\\x二顺散\\x（四七） 治中暑霍乱吐泻，烦闷燥渴，小便赤涩，便血肚疼。 \n白术 炙甘草 茯苓 猪苓 泽泻 干姜（炒） 肉桂 杏仁（去皮尖，炒，各等分） \n上为末。每服五七分，不拘时水调下，或用水煎服。 \n\\x香朴散\\x（四八） 治积冷呕吐。 \n藿香叶 浓朴（姜汁炒） 陈皮（各七钱） 半夏（汤泡七次，一两） 炙甘草（一钱） \n上每服三钱，姜、枣、水煎。泻甚者，加木香、肉豆蔻。 \n\\x沉香散\\x（四九）顺胃气，止呕吐。 \n茯苓（二钱） 沉香 丁香 木香 藿香 浓朴 炙甘草（各一钱） \n上为末。每服一字，米饮汤调服。 \n\\x玉露散\\x（五十）治伤热吐泻。 \n石膏（ ） 寒水石（各五钱） 甘草（一钱半） \n上为末。每服五分，白汤调下。 \n\\x六神散\\x（五一） 治面青啼哭，口出气冷，或泄泻不乳，腹痛曲腰，四肢厥冷。 \n人参 白术（炒） 山药（炒，各五钱） 炙甘草（二钱） 白茯苓 白扁豆（炒，各一两） \n上为末。每服二三钱，姜、枣、水煎。 \n\\x香橘饼\\x（五二） 治伤冷积泻。 \n木香 青皮（各一钱） 陈皮（二钱半） 浓朴 神曲（炒） 麦芽（炒，各半两） \n上为末，蜜和为饼。每服一枚，米饮调下。 \n（钱氏）\\x黄芩汤\\x（五三） 治挟热下痢，头痛胸满大渴，或寒热胁痛，脉洪大而实者。 \n黄芩（一两半） 芍药 甘草（炒，各一两） \n上每服二三钱，姜、水煎。如呕，加半夏二钱。 \n\\x涩肠散\\x（五四） 治小儿久痢，肠头脱出。 \n诃子（炮） 赤石脂 龙骨（各等分） \n上为末，腊茶少许和药掺肠头上，绢帛揉入。 \n\\x破故纸散\\x（五五） 治膀胱虚冷，夜间遗尿，或小水不禁。 \n破故纸（炒） \n上为末。每服一钱，热汤调下。 \n（陈氏）\\x肉豆蔻丸\\x（五六） 治泻痢水谷，或淡黄或白，不能止者。 \n肉豆蔻 诃子肉 白龙骨（各半两） 木香 砂仁（各二钱） 赤石脂 枯白矾（各七钱半） \n上为细末，面糊为丸，黍米大。周岁儿每服三五十丸，三岁儿服百丸，温米饮下。泻甚 \n者，煎木香散或异功散送下，不止，多服。薛按∶前方治阳气虚寒肠滑之涩剂，盖肾主大便， \n若因肾气不固而致前证者，宜用木香散送四神丸；如不应，急煎六君子汤送四神丸补之，盖 \n豆蔻丸涩滞之功多，补益之功少也。 \n\\x宁神汤\\x（五七） 治心虚火盛，热躁惊搐等证。 \n人参 当归身 生地 麦冬（各一钱） 山栀仁 黄连（炒） 炙甘草（各二钱） 石菖蒲（三分） \n辰砂（入二分） \n上加灯心半钱，水一盏，煎七分，调辰砂搅匀。食后温服。 \n\\x当归养心汤\\x（五八） 治心虚惊悸。 \n归身 麦冬 生地（酒洗） 人参 炙甘草 升麻（少用） \n水一钟半，加灯草一团，煎七分。食远服。 \n（钱氏）\\x养心汤\\x（五九） 治心血虚怯，惊痫，或惊悸怔仲，盗汗无寐，发热烦躁。 \n人参 黄 远志 当归 川芎 枣仁 五味子 柏子仁 肉桂 白茯苓 茯神 半夏 \n曲（各三钱） 炙甘草（四钱） \n上每服二三钱，姜、水煎。 \n\\x茯神汤\\x（六十） 治胆气虚寒，头痛目眩，心神恐惧，或者惊痫。 \n人参 黄 （炒） 枣仁（炒） 熟地 白芍（炒） 柏子仁（炒） 五味子（炒） 茯神（各一两） \n桂心 甘草（炒，各五钱） \n上每服二三钱，水煎。 \n\\x清神汤\\x（六一） 治惊痫，心虚血热。 \n犀角（镑屑） 远志（姜汁焙） 白鲜皮 石菖蒲 人参 甘草（等分） \n上为末。每服五七分，麦门冬煎汤调服。 \n（钱氏）\\x酸枣仁汤\\x（六二） 治心肺虚热，烦躁惊啼，痘疹血热血燥等证。 \n枣仁 炙甘草 人参 生地 麦冬 当归身 栀子仁（等分） \n上加灯心，水一盏，煎六分。温服。 \n\\x黑附子汤\\x（六三） 治慢脾风四肢厥冷。 \n附子（炒，去皮，三钱） 木香 人参（各一钱半） 白附子（一钱） 炙甘草（五分） \n上为散。每服三钱，姜五片，水煎。若手足即温，即止后服。 \n\\x钩藤散\\x（六四） 治吐利，脾胃气虚，慢惊生风。 \n\\x钩藤钩\\x人参 天麻 蝎尾（去毒） 防风 蝉壳（各半两） 麻黄 僵蚕（炒） 炙甘草 \n川芎（各二钱半） 麝香（五分） \n上 咀。每服二三钱，水煎服。虚寒加附子一钱。 \n薛按∶慢惊之证属脾胃亏损所致，前方乃辛温散表之药而无调补之功，须审用之。 \n\\x钩藤饮子\\x（六五） 治小儿一切惊风潮搐，目视昏迷。 \n钩藤钩 防风 独活 天竺黄 羌活（各三钱） 麻黄 升麻 甘草 草龙胆（各二钱） \n川芎（三钱） 蝉蜕（五个，去头足） \n上每服二三钱，姜、枣、水煎服。薛立斋曰∶按上方若外感风寒，形证俱实者宜用之。 \n若形气虚而病气实者，宜用惺惺散加钩藤、麻黄；若外邪少而形病俱虚者，宜异功散。 \n（钱氏）\\x钩藤饮\\x（六六） 治小儿脏寒夜啼，阴极发躁。 \n钩藤钩 茯神 茯苓 当归 川芎 木香（各一钱） 甘草（五分） \n上每服二钱，姜、枣、水煎服。《撮要》方有芍药一钱。若心经有热，脸红便赤，去 \n木香，加朱砂末一钱，木通汤下。 \n（薛氏）\\x抑肝散\\x（六七） 治肝经虚热发搐，或发热切牙，或惊悸寒热，或木乘土而 \n呕吐痰涎，腹胀少食，睡不安。 \n软柴胡 甘草（各五分） 川芎（八分） 当归 白术（炒） 茯苓 钩藤钩（各一钱） \n上水煎，子母同服。以蜜丸，名抑青丸。 \n\\x大青膏\\x（六八） 治伤风痰热发搐。 \n天麻 青黛（各一钱） 白附子（煨） 乌蛇（酒浸，取肉，焙） 蝎尾（各五分） 天 \n竺黄 麝香（各一字） \n上为末，生蜜丸，豆大。每用半粒，薄荷汤化下。 \n\\x地黄清肺饮\\x（六九） 治肺热疳蚀穿孔，或生 肉，或鼻外生疮。 \n桑白皮（半两，炒） 紫苏 前胡 赤茯苓 防风 黄芩 当归 天门冬 连翘 桔梗 \n生地 甘草（炙，各二钱） \n每服五七钱，水煎服，次用化 丸。 \n\\x甘草汤\\x（七十） 治撮口。 \n甘草（生用，一钱） \n上水煎，以棉球蘸吮，令出痰涎，却以猪乳点入口中即瘥。 \n（《秘旨》）\\x安神丸\\x（七一） 治心血虚而睡中惊悸，或受惊吓而作。 \n人参 枣仁 茯神 半夏（各一钱） 当归 芍药（炒） 橘红（各七分） 五味子（五粒，杵） \n炙甘草（三分） \n上为末，姜汁糊丸，芡实大。每服一丸，生姜汤下。 \n\\x七味安神丸\\x（七二） 治心经蕴热惊悸。 \n黄连 当归身 麦门冬 白茯苓 甘草（各半两） 朱砂（飞一两） 冰片（二分半） \n上为末，汤浸蒸饼和 猪心血捣丸，黍米大。每服十丸，灯心汤下。 \n\\x十味安神丸\\x（七三） 治惊。 \n人参 茯神 麦门冬 山药（各二钱） 片脑（一分） 龙齿（二钱） 朱砂 甘草 寒水石（各五分） \n金薄（二片） \n上为末，蜜丸，鸡豆大。灯心汤调下。一方有马牙硝。 \n\\x朱砂安神丸\\x（七四） 方在寒阵一四二。 \n清心火，养血安神。 \n（钱氏）\\x安神丸\\x（七五） 方在寒阵一四三。 \n除火邪热渴，清心化痰。 \n\\x安神镇惊丸\\x（七六） 惊退后调理，安心神，养气血，和平预防之剂也。 \n天竺黄（另研） 人参 南星（姜制） 茯神（各五钱） 当归 枣仁（炒） 麦冬 生地 \n芍药（炒，各三钱） 黄连（姜汁炒） 薄荷 木通 山栀（炒） 朱砂（另研） 牛黄（另研） \n龙骨（ ，各二钱） 青黛（一钱，另研） \n上为末，蜜丸，绿豆大。每服三五丸，量儿大小加减，淡姜汤送下。 \n（万氏）\\x龙脑安神丸\\x（七七） 治惊痰，及痘中昏闷谵妄良方。 \n大辰砂（一钱，飞） 牛黄（一分） 龙脑（半分） \n上研细末，取 猪心血、小猪尾尖血，和丸如绿豆大。每服一丸或二三丸，新汲水化下， \n或灯心汤、紫草汤俱可下。 \n\\x镇心丸\\x（七八） 治急惊化痰镇心。 \n朱砂 龙齿 牛黄（各一钱） 铁粉 人参 茯苓 防风 琥珀（各二钱） 全蝎（七枚，焙） \n上为末，蜜丸，桐子大。每服一二丸，薄荷汤送下。 \n\\x金薄镇心丸\\x（七九） 治风壅痰热，心神不宁，惊悸烦渴，唇焦颊赤，夜卧不安，谵 \n语狂妄。 \n金薄（十二帖，为衣） 朱砂（一两，飞） 人参 白茯苓 甘草（各半两） 山药（一两半） \n牙硝（一钱半） 麝香（五分） 片脑（一分） \n上为末，炼蜜丸，每一钱作十丸，以金薄为衣。每服一丸，薄荷汤化下，或含化亦可。 \n\\x辰砂膏\\x（八十） 治眼闭口噤，啼声不出，吮乳不得，口吐白沫。 \n辰砂（二钱） 硼砂 马牙硝（各一钱半） 玄明粉 全蝎 珍珠（各一钱） 麝香（一分） \n上为末。每服一豆许，诸惊，薄荷汤下；潮热，甘草汤下；月内者，用乳汁调涂乳头 \n令吮之。 \n\\x琥珀散\\x（八一） 治急慢惊风，涎潮昏冒，惊搐目瞪，内钓腹痛，或惊痫时发。 \n琥珀 牛黄 胆星（此当倍用） 白附子 天麻 僵蚕（炒，去丝嘴） 代赭石 \n全蝎 蝉蜕 乳香（各一钱） 朱砂（一钱半） \n上为末。每服一二分，白汤调下。 \n（《千金》）\\x龙胆汤\\x（八二） 治月内脐风撮口，四肢惊掣，发热吐乳；及客忤鬼气 \n惊痫，加人参、当归。 \n龙胆草（炒黑） 钩藤钩 柴胡 黄芩（炒） 芍药（炒） 桔梗 茯苓 甘草 大黄（煨，各二 \n钱半） 蜣螂（二枚，去翅足） \n上为末。每服一二钱，水煎，量儿加减。 \n\\x梅花饮\\x（八三） 治五脏积热，喉中有痰，面色赤白，鼻流清涕，气逆喘急，目赤咳嗽， \n或因惊夜啼。 \n硼砂 马牙硝 芒硝 辰砂（各一钱） 人参（二钱） 甘草（五分） 片脑（半分） 麝香（一分） \n上为末。瓷器收贮，每服半匙，麦冬汤调服，或薄荷汤亦可。 \n\\x擦牙通关散\\x（八四） 治风搐关窍不逸，痰塞中脘，留滞百节。 \n南星（二钱） 麝香（一字） 牙皂（二钱，烧存性） 僵蚕（一钱） 赤脚蜈蚣（一条） \n上为末。姜汁蘸药少许擦牙，或调服二三点，涎自出。 \n（陈氏）\\x抱龙丸\\x（八五） 治风痰壅盛，或发热咳嗽，或发惊搐等证。 \n胆星（九制，四两） 天竺黄（一两） 雄黄 朱砂（各五钱） 麝香（五分，另研，或减半亦可） \n上为细末，用大甘草一斤煮极浓汁捣丸，每两作二十丸，阴晾干。用薄荷汤或灯草汤下一 \n二丸。此方加牛黄四钱，即名牛黄抱龙丸。加琥珀，即名琥珀抱龙丸。 \n\\x至圣保命丹\\x（八六） 治胎惊内钓，肚腹紧硬，啼叫不安，乃急惊风，眼目上视，手足抽搐， \n不省人事。 \n全蝎（十四个，去毒） 防风（二钱） 炮南星 白附子 蝉蜕 僵蚕（炒，去丝嘴） \n天麻 朱砂（各一钱） 麝香（五分） 金箔 \n上为末，米糊和，每两作四十丸。每服一丸，白汤化下。有热者，以南星易炮星。 \n此方去天麻，加琥珀捏成锭，以薄荷汤磨服，即名保生锭子，亦名太乙保生丹，治慢惊尚 \n有阳证者。 \n\\x定命丹\\x（八七） 治天钓撮口，通利痰热。 \n全蝎（七枚） 天麻 南星（炮） 白附子（各二钱半） 朱砂 青黛（各一钱半） 轻粉 \n麝香（各五分） 片脑（一字） \n上为末，米糊丸，绿豆大。每服一二丸，荆芥薄荷汤下，可先研半丸吹入鼻中。 \n\\x九还金液丹\\x（八八） 此药有斡旋造化之功，专治男妇痰盛气急，中风不语，口眼歪斜， \n左瘫右痪，牙关紧急，及小儿急惊风，手足抽搐，不省人事，痰多气急等证，功效不可尽迷。 \n胆星（九制者，二两） 朱砂（飞，一两） 生半黄（五钱） 僵蚕（五钱，炒） 牙皂（去皮 \n弦，炒焦，三钱） 冰麝（各五分） \n小麦面炒熟，炼蜜和匀捣丸，茨实大，金薄为衣，黄蜡区收藏。如大人牙关紧急，先 \n以通关散开其窍，随用淡姜汤下一二丸。若治小儿，用薄荷汤化下一丸。 \n\\x胆星天竺丸\\x（八九） 治小儿痰涎上壅，喘嗽不休。 \n胆星（一两） 天竺黄（三钱） 半夏（姜制） 白附子（汤炮，去皮脐，各五钱） 天麻 \n防风（各二钱） 辰砂（一钱，飞） \n上为末，甘草汤为丸，芡实大。每服一丸，空心薄荷汤或淡姜汤下。 \n（陈氏）\\x温白丸\\x（九十） 驱风豁痰定惊。 \n人参 防风 白附子（生用） 真僵蚕（炒） 全蝎（焙，各一钱） 南星（汤泡七次， \n焙） 天麻（各二钱） \n上用末，水糊丸，桐子大。每服三五丸，姜汤下。 \n\\x粉红丸\\x（九一） 治小儿心虚，困卧惊动，痰涎不利，或发热痰嗽等证。 \n天竺黄（五钱） 天南星 朱砂（各一钱半） 冰 胭脂（各一钱） \n上以牛胆汁和丸，芡实大。每服一丸，砂糖汤下。 \n（钱氏）\\x牛黄丸\\x（九二） 治风痫，因汗出风邪乘虚而入，痰涎迷闷，手足搐掣。 \n牛胆南星 全蝎（焙） 蝉蜕（各二钱半） 防风 白附子（生用） 天麻 僵蚕（炒，各一钱半） \n麝香（半字） \n上为末，枣肉和丸，加水银半钱，同研细丸，绿豆大。每服一二丸，荆芥生姜汤下。 \n（《杂着》）\\x牛黄丸\\x（九三） 治小儿惊风，中风五痫天吊客忤，潮热，痰涎壅盛等证。 \n白花蛇（酒浸） 白附子 川乌 全蝎 天麻 薄荷 雄黄（各五钱） 朱砂（二钱） \n牛黄 麝香（各一钱） 冰片（五分） \n上各另研为极细末，和匀，用麻黄煎酒捣丸，芡实大。每服一丸，薄荷汤下。 \n（万氏）\\x牛黄清心丸\\x（九四） 治心热神昏。 \n黄连（生，半两） 黄芩 山栀仁（各三钱） 郁金（二钱） 辰砂（一钱半） 牛黄（二分半） \n上为细末，腊雪调面糊丸，如黍米大。每服七八丸，灯心汤下。 \n\\x三味牛黄丸\\x（九五） 治惊热，消疳积。 \n雄黄（飞） 牵牛（各一钱） 天竺黄（二钱） \n上为末，面糊丸，粟米大。每服五七丸，薄荷水下。 \n\\x凉惊丸\\x（九六） 治惊疳热搐睛赤，潮热痰涎，牙关紧急。 \n龙胆草（炒焦） 防风 青黛（各三钱） 钩藤钩（二钱） 黄连（炒，五钱） 龙脑（一钱） \n牛黄 麝香（各二分） \n上为末，面糊丸，粟米大。每服十丸，煎金银花汤下。 \n\\x利惊丸\\x（九七） 治急惊。 \n天竺黄（二钱） 轻粉 青黛（各一钱） 黑牵牛（炒，五钱） \n一方无天竺黄。 \n上为末，炼蜜丸，豌豆大。每岁一丸，薄荷水化下。 \n（钱氏）\\x抑青丸\\x（九八） 治肝热急惊搐搦。 \n羌活 川芎 当归 防风 龙胆草（等分） \n上为末，炼蜜丸，芡实大。每服一二丸，竹叶汤入砂糖化下。此方加大黄、栀子仁，即 \n名泻青丸。 \n\\x化痰丸\\x（九九） 治惊搐喉内痰响者暂用。 \n胆星 半夏（制） 礞石（制） 枳实（各二两） 麝香（三分） \n上为末，姜汁糊丸，绿豆大，朱砂为衣。姜汤研化，量送。 \n\\x比金丸\\x（百） 治惊痫先用此药。 \n人参 远志（姜制取肉，炒） 白茯苓 南星 川芎 石菖蒲（细密者） 天麻 朱砂 \n青黛 琥珀（各一钱） 麝香（一字） \n上为末，蜜丸，桐子大。每服一二丸，金银薄荷汤下。 \n\\x虎睛丸\\x（百一） 治惊痫邪气入心。 \n虎睛（细研） 远志（姜汁浸） 犀角（镑屑） 石菖蒲 大黄（湿纸包煨） 麦冬（等分） \n蜣螂（去足翅，炒，三枚） \n上为末，米糊丸，梧子大。每服一二丸，竹叶煎汤或金银薄荷汤下。 \n\\x五痫丸\\x（百二） 一名五色丸。治五痫。 \n朱砂 珍珠（各五钱） 雄黄（一两） 水银（二钱半） 黑铅（三两，同水银结成砂） \n上为末，炼蜜丸麻子大。每服三四丸，煎金银薄荷汤下。 \n\\x断痫丹\\x（百三） 治五痫瘥后复发，证候多端，连绵不除者。 \n黄 （蜜炙） 钩藤钩 细辛 炙甘草（各半两） 蛇蜕（二寸，酒炙） 蝉蜕（四个） \n牛黄（一钱，另研） \n上为末，煮枣肉丸，麻子大。煎人参汤下，每服数丸，量儿加减。 \n\\x消风丸\\x（百四） 治风痫先宜此药。 \n胆星（二钱） 羌活 独活 防风 天麻 人参 荆芥 川芎 细辛（各一钱） \n上为末，蜜丸，桐子大。每服二丸，薄荷紫苏汤调化下。 \n\\x妙圣丹\\x（百五） 治食痫，因惊而停食吐乳，寒热，大便酸臭是也。 \n赭石（ ，醋淬，二钱半） 巴霜（三分） 朱砂 雄黄 蝎梢（各一钱） 轻粉 麝香（各一匙） \n杏仁（微炒，二钱） \n上为末，枣肉丸，梧子大。每服一二丸，木贼草煎汤送下。 \n\\x褊银丸\\x（百六） 治癫痫膈热，风涎壅盛，腹胀喘促，实滞者。 \n巴豆 水银（各五钱） 京墨（八钱，火烧醋淬） 黑铅（二钱半，水银煎） 麝香（五分，另研） \n上为末，陈米粥丸，绿豆大。每服二三丸，煎薄荷汤下。 \n（薛氏）\\x紫河车丸\\x（百七） 治癫痫。 \n紫河车（肥大者一具） 人参 当归（二味酌用，为末） \n上将河车生研烂，入二药捣丸，桐子大。每服五七十丸，日进三服，人乳化下。按∶此 \n方凡先天不足，后天亏败者，俱可随宜增用药物，照此制服，无不可也。然河车必用酒炖熟 \n方善，虽薛氏之意用其生气，但生者腥腻，恐不利于胃气。且此物既离本体，尚何生气之有？ \n亦不过取其应求之性味，为血气之资而已。矧人之血气，本皆热物之所养成，故饮食之类，凡 \n生用热用，其补泻有甚相远者，岂熟之即无益，而生之果无碍耶？余故曰热之为宜。 \n\\x大芜荑汤\\x（百八） 治小儿脾疳，发热作渴，少食，大便不调，发黄脱落，面黑，鼻 \n下生疮，能乳嗜土等证。 \n芜荑 山栀（各五分） 当归 白术 茯苓（各四分） 柴胡 麻黄 羌活（各三分） \n防风 黄连 黄柏 炙甘草（各二分） \n上作二剂，水煎服。 \n\\x生熟地黄汤\\x（百九） 治疳眼闭合不开。 \n生地黄 熟地黄（各半两） 川芎 赤茯苓 枳壳 杏仁（去皮） 川黄连 半夏曲 \n天麻 地骨皮 炙甘草（各二钱半） \n上每服二三钱，黑豆十五粒，姜、水煎服。 \n\\x兰香散\\x（百十） 治鼻疳赤烂。 \n兰香叶（二钱，烧灰） 铜青 轻粉（各五分） \n上为末干贴。 \n\\x四味肥儿丸\\x（百十一） 治小儿食积五疳，目生云翳，牙根腐烂，口舌生疮，发热体瘦， \n肚大筋青，发稀成穗，或白秃疮疥，小便澄白等证。 \n芜荑 神曲（炒） 麦芽（炒） 黄连（各等分） \n上为末，猪胆汁丸，黍米大。每服二三十丸，木通煎汤下。 \n\\x六味肥儿丸\\x（百十二） 消疳化虫退热。 \n黄连 陈皮 川楝子（去核，炒） 神曲（炒） 麦 （炒，各一两） 白芜荑（半两） \n上为末，糊丸麻子大。每服一二十丸，空心米饮吞下。 \n薛氏曰∶前方又治脾疳饮食少思，肌肉消瘦，肚大颈钿，发稀成穗，项间结核，发热作渴， \n大便酸臭，嗜食泥土，或口鼻头疮，肚见青筋，吃齿便白。五疳用此丸加干蟾一两尤妙。 \n\\x七味肥儿丸\\x（百十三） 治小儿食积五疳，颈项结核，发稀成穗，发热作渴消瘦等证。 \n黄连（炒） 神曲（炒） 木香（各一两半） 槟榔（二十个） 使君子（酒浸） 麦芽（炒， \n各四两） 肉豆蔻（炮，二两） \n面糊丸，麻子大。每服三五十丸，米饮下，良久，用五味异功散一服以助胃气。 \n\\x芦荟肥儿丸\\x（百十四）治疳热。 \n芦荟 龙胆草（酒洗） 木香 人参 使君子肉 蚵 （酥炙，去头足，即上鳖） \n麦芽（炒，各二钱） 槟榔 黄连（去芦须，酒炒） 白芜荑（各三钱） 胡黄连（五钱） \n上为细末，猪胆汁为丸，黍米大。每服五六十丸，米饮下。 \n\\x大芦荟丸\\x（百十五） 一名九味芦荟丸。治小儿肝脾疳积，发热体瘦热渴，大便不调， \n或瘰 结核，耳内生疮，牙腮蚀烂，目生云翳等证。 \n胡黄连 黄连 芦荟 白芜荑（炒） 白雷丸（破开，赤者不用） 木香 青皮 \n鹤虱草（微炒，各一两） 麝香（一钱，另研） \n上为末，蒸饼糊丸，麻子大。每服一钱，空心白汤送下。立斋曰∶内青皮以龙胆草 \n代之，麝香不用，尤效。 \n\\x加减芦荟丸\\x（百十六） 治证同前，尤治小儿疳积腹胀。 \n芦荟（真者，五钱） 宣黄连（去须） 胡黄连 枳实 青皮（各二钱半） 青黛 木香 山 \n楂肉（各二钱） 麦芽（炒，三钱） 麝香（一分） 干虾蟆（一只，酥炙） \n上为细末，汤浸蒸饼为丸，绿豆大。每服七八分，量儿大小与之。按∶此方加使君子肉三 \n钱，治湿热生虫亦佳。 \n\\x当归龙荟丸\\x（百十七） 方在寒阵一六七。治肝经实火，大便秘结。 \n（《良方》）\\x芦荟丸\\x（百十八） 方在寒阵一六八。治疳癖发热诸证。 \n\\x龙胆丸\\x（百十九）治脑疳脑热疮。 \n龙胆草 升麻 苦楝根皮（焙） 赤茯苓 防风 芦荟 油发灰（各二钱） \n青黛 黄连（各三钱） \n上为末，牡猪胆汁浸米糕丸，麻子大。薄荷汤下，仍以芦荟末敷入鼻内。 \n\\x木香丸\\x（百二十） 治疳痢。 \n黄连（净，三钱） 木香 紫浓朴（制） 夜明砂（纸炒，各二钱） 诃子（肉炒，一钱） \n上为末，饭丸，麻子大。干艾、生姜煎汤，食前下。 \n\\x黄连丸\\x（一二一） 治疳劳。 \n黄连（半两，净牛胆汁浸，晒） 石莲子 栝蒌根 杏仁（去皮尖） 乌梅肉（各二钱） \n上为末，牛胆汁浸糕丸，麻子大。煎乌梅、姜、蜜汤下。 \n\\x胡黄连丸\\x（一二二） 治热疳。 \n胡黄连 黄连（各五钱） 朱砂（二钱） \n上为末，填入猪胆内，以线扎悬挂铫中，淡浆水煮数沸取出，研芦荟、麝香各二钱入之， \n饮和丸，麻子大。 \n每服一二十丸，米饮下。 \n\\x蟾蜍丸\\x（一二三） 治小儿颈项结核，面色痿黄，饮食不甘，腹大发热，名曰无辜 \n疳证。一服虚热退，二服烦渴止，三服泻痢愈。 \n蟾蜍（一二个） 夏月沟渠深土中，取腹大不跳不鸣者是，身多 者佳。 \n上将粪蛆一杓置桶中，以尿浸之，却将蟾蜍跌死，投与蛆食一昼夜，用布袋盛蛆，置急 \n流中一宿取出，瓦上焙干为末，入麝香一字，粳米饭丸，麻子大。每服二三十丸，米饮下， \n其效如神。 \n\\x天麻丸\\x（一二四） 治肝风疳眼。 \n天麻 青黛 黄连 五灵脂 夜明砂（微炒） 川芎 芦荟（各二钱） 龙胆草 防风 \n蝉蜕（去足，各一钱半） 全蝎（二枚，焙） 干蟾头（炙焦，三钱） 麝香（少许） \n上为末，猪胆汁浸米糕丸，麻子大。每服十丸，薄荷汤下。 \n\\x灵脂丸\\x（一二五） 治脾疳、食疳。 \n白豆蔻 麦芽（炒） 五灵脂 砂仁 蓬术（煨） 青皮 橘红 使君子（焙，各二钱） \n虾蟆（炙焦，三钱） \n上为末，米糊丸，麻子大。每服十丸，米汤下。 \n\\x如圣丸\\x（一二六） 治疳热泄泻。 \n白芜荑（炒） 川黄连 胡黄连（各二两半） 使君子肉（一两） 麝香（五分，另研） \n干虾蟆（五个，酒者杵膏） \n上为末，以虾蟆膏杵丸，麻子大。每服一二十丸，煎人参汤下。 \n薛按∶疳之为患，乃肝脾虚热，津液干涸之证。前方乃专于治疳清热之剂，若脾胃虚 \n弱者，当佐以六君子汤调补脾胃，使邪气退，庶可收全功也。 \n\\x褐子丸\\x（一二七） 治疳肿胀。 \n萝卜子（一两，微炒） 陈皮 青皮（炒） 槟榔 五灵脂 蓬术（煨） 黑牵牛（头末，炒） \n赤茯苓 木香（二钱半） \n上为末，面糊丸，绿豆大。每服十五丸，紫苏汤下。 \n\\x消积丸\\x（一二八） 治食积大便酸臭发热。 \n丁香（九个） 砂仁（十二个） 乌梅肉（三个） 巴豆（三粒，去皮心膜） \n上为末，面糊丸，黍米大。每服五七丸，温水下。 \n\\x塌气丸\\x（一二九） 治肚腹虚胀。 \n胡椒（一两） 蝎尾（五钱，去毒） \n上为末，面糊丸，粟米大。每服一二十丸，陈米饮下。 \n\\x紫霜丸\\x（百三十） 治惊积，及变蒸发热不解，或食痫先寒后热，或乳哺失节，宿 \n滞不化，腹痞便结。 \n代赭石（ ，醋 七次） 赤石脂（各一两） 杏仁（五十个） 巴豆（二十枚，去心膜油） \n上先将巴豆、杏仁研成膏，入代赭、石脂研匀，汤浸蒸饼丸，粟米大。每服三五丸，米饮送下。 \n\\x化 丸\\x（一三一） \n黄连（五钱） 蜀椒（去闭口者，炒出汗） 苦楝根白皮（各二钱） \n上为末，用乌梅肥者七个，艾汤浸去核，捣烂和丸。艾汤量儿大小送下。 \n\\x下虫丸\\x（一三二） 诸疳蛔诸虫。 \n苦楝根皮（新白者，酒浸焙） 绿包贯众 鸡心槟榔 桃仁（浸去皮，焙） 芜荑（焙） \n木香（各二钱） 鹤虱（炒，一钱） 轻粉（五分） 干虾蟆（炙焦，三钱） 使君子（五十，取肉煨） \n上为末，面糊丸，麻子大。每服一二十丸，天明清肉汁下。一方内加当归、川连各 \n二钱五分。 \n\\x使君子丸\\x（一三三） 治五疳蛔虫，脾胃不和，心腹膨胀，时复作痛，不食渐瘦。 \n使君子肉（一两） 浓朴（制） 橘红 白芍药 甘草（炒） 川芎（各一钱） \n上为末，蜜丸，皂角子大。每服一丸，陈米饮化下。 \n\\x白玉散\\x（一三四） 治丹瘤。 \n白土（二钱半） 寒水石（五钱） \n上为末，米醋或新水调涂。 \n\n\n\n<目录>卷之六十二长集·小儿则古方\\小儿\n\n<篇名>以下通用方\n\n属性：\\x四君子汤\\x（一三五） 方在补阵一。 \n治脾肺气虚诸证。 \n\\x六君子汤\\x（一三六）方在补阵五。 \n治脾胃虚弱呕吐等证。 \n\\x五味异功散\\x（一三七）方在补阵四。 \n治脾胃虚寒，饮食少思等证。 \n\\x四物汤\\x（一三八）方在补阵八。 \n治一切血虚等证。 \n\\x八珍汤\\x（一三九）方在补阵十九。 \n治气血两虚。 \n\\x十全大补汤\\x（百四十）方在补阵二十。 \n治气血俱虚，大补元气。 \n\\x独参汤\\x（一四一）方在补阵三五。 \n治气虚气脱，挽回元阳。 \n\\x归脾汤\\x（一四二） 方在补阵三二。 \n治心脾虚损。 \n\\x参术汤\\x（一四三） 方在补阵四十。 \n治气虚泄泻呕吐等证。 \n\\x参术膏\\x（一四四）方在补阵三九。 \n治中气虚弱，诸药不应者。 \n\\x参苓散\\x（一四五）方在补阵五三。 \n治睡中出汗。 \n\\x参附汤\\x（一四六） 方在补阵三七。 \n治真阳虚极，喘急呃逆。 \n\\x参苓白术散\\x（一四七）方在补阵五四。 \n治脾胃虚弱，食少吐泻。 \n\\x理中汤\\x（一四八）方在热阵一。 \n治上中二焦虚寒诸证。 \n\\x生脉散\\x（一四九）方在补阵五六。 \n治热伤元气，止渴消烦，定咳嗽喘促。 \n\\x五福饮\\x（百五十）方在新补六。 \n补五脏虚损。 \n\\x五君子煎\\x（一五一）方在新热六。 \n治脾胃虚寒，呕吐泄泻。 \n\\x理阴煎\\x（一五二） 方在新热三。 \n治脾胃虚寒诸证。 \n\\x温胃饮\\x（一五三） 方在新热五。 \n治中寒呕吐吞酸，泄泻少食。 \n\\x养中煎\\x（一五四）方在新热四。 \n治中气虚寒呕泄。 \n\\x参姜饮\\x（一五五）方在新热八。 \n治脾肺胃气虚寒，呕吐咳嗽。 \n\\x六味回阳饮\\x（一五六） 方在新热二。 \n治阴阳将脱等证。 \n\\x六味异功煎\\x（一五七）方在新热七。 \n治脾胃虚寒，吐泻兼滞者。 \n\\x六味丸\\x（一五八）方在补阵百二十。 \n壮水补肾。 \n\\x八味丸\\x（一五九）方在补阵一二一。 \n益火补阳。 \n\\x胃关煎\\x（百六十） 方在新热九。 \n治脾胃虚寒泻痢。 \n\\x佐关煎\\x（一六一）方在新热十。 \n治生冷伤脾泻痢。 \n\\x五德丸\\x（一六二）方在新热十八。 \n治脾肾寒滞，一切泻痢飧泄。 \n\\x二陈汤\\x（一六三） 方在和阵一。 \n和脾消痰。 \n\\x芍药枳术丸\\x（一六四）方在新和十六。 \n健脾消积，止腹痛，除胀满。 \n\\x枳术丸\\x（一六五）方在和阵七九。 \n健脾胃，消食积。 \n\\x大和中饮\\x（一六六） 方在新和七。 \n治饮食留滞。 \n\\x小和中饮\\x（一六七）方在新和八。 \n治胸膈胀满，脾胃不和。 \n\\x四顺清凉饮\\x（一六八）方在攻阵二五 \n治血热壅滞秘结。 \n\\x青州白丸子\\x（一六九）方在和阵百十二。 \n治风痰呕吐，牙关紧急。 \n\\x泻青丸\\x（百七十）方在寒阵一五一。 \n治肝火急惊目赤。 \n\\x扫虫煎\\x（一七一）方在新和十四。 \n治诸虫上攻，胸腹作痛。 \n\n\n\n<目录>卷之六十三长集·痘疹诠古方\n\n<篇名>痘疹\n\n属性：\\x保元汤\\x（一）治痘疮气虚塌陷者。 \n人参（二三钱） 炙甘草（一钱） 肉桂（五七分） 黄 （二三钱，灌脓时酒炒，回浆时蜜炙） \n水一钟半，加糯米一撮，煎服。此药煎熟，或加人乳，好酒各半盏和服更妙，酌宜用之。 \n头额不起，加川芎三五分。面部，加升麻三四分。胸腹，加桔梗三四分。腰膝，加牛膝四分。 \n四肢不起，加桂枝。呕恶，加丁香三四分。元气虚寒，加大附子七八分或一钱。 \n\\x调元汤\\x（二）按∶此即保元汤无肉桂者，名为调元汤，即东垣之黄 汤也。东垣用为小 \n儿治惊之剂，魏桂岩用以治痘多效，因美之名保元汤也。盖小儿元气未充，最易伤残，用此 \n保全，诚幼科王道之妙方。但能因此廓充，则凡气分血分虚寒虚陷等症，皆可随症增减用之， \n无不可奏神效也。 \n\\x内补汤\\x（三）治痘疮中虚等症。 \n人参 黄 当归 白术 川芎 甘草 茯苓 陈皮 浓朴 \n上等分，水煎服。 \n\\x托里散\\x（四）治痘毒元气虚弱，或妄行克伐，不能溃散，用之未成自消，已成自溃，并 \n治痈毒内虚，不能起发。 \n人参 黄 （炒，各二钱） 当归（酒洗） 白术 熟地 芍药（炒） 茯苓（各一钱半） \n炙甘草（五分） \n上每用三五钱，水煎服。《外科枢要》方有陈皮一钱半，无甘草。 \n\\x解毒内托散\\x（五）治痘痈。 \n金银花 黄 当归 赤芍药 防风 甘草节 荆芥 连翘 木通 \n上水煎。入酒少许服。 \n（陈氏）\\x托里消毒散\\x（六）治痘毒瓦斯血虚弱，不能起发腐溃收敛，或发寒热，肌肉不生。 \n人参 黄 （炒） 当归（酒洗） 川芎 芍药（炒） 白术（炒） 茯苓 陈皮（各一钱） \n金银花 连翘 白芷（各七分） 炙甘草（五分） \n上每服三五钱，水煎服。《外科》方无陈皮。 \n\\x参 内托散\\x（七）治痘疮里虚发痒，或不溃脓，或为倒靥，及疮痈脓毒不化，脓溃作痛等证。 \n人参 黄 （蜜炙） 当归 川芎 浓朴（姜制） 防风 桔梗（炒） 白芷 紫草 \n官桂 木香 甘草（等分） \n入糯米一撮，水煎服。色淡白者，去防风、紫草、白芷，多加粘米。一方有芍药。 \n\\x参 四圣散\\x（八） 治痘疮已出，至六七日不起发，不成脓。 \n人参 黄 （炒） 白术（炒） 当归 川芎 芍药（炒） 茯苓（各五分） 紫草 \n防风 木通（各三分） \n上用水煎服。 \n（陈氏）\\x四圣散\\x（九）治痘疮出不快及倒靥因内实者。 \n紫草茸 木通 炙甘草 枳壳（麸炒） 黄 （等分） \n上每服二钱，加糯米一百粒，水煎待米熟。温服。 \n\\x加味四圣散\\x（十） 治痘疮黑陷倒陷。 \n人参 黄 （炙） 川芎 甘草 紫草 木通 木香（等分） 蝉蜕（十个） \n上加糯米百粒，水一盏，煎服。 \n\\x如圣汤\\x（十一）治毒盛不起。 \n芍药 升麻 干葛（各一钱） 甘草 紫草 木通（各三五分） \n水一钟，姜一片，煎七分。温服，不拘时。 \n\\x人参固肌汤\\x（十二） 治痘疮发表太过，致肌肉不密，或痘痂久粘者。 \n人参 黄 当归（酒洗） 甘草 蝉蜕（去土，等分） \n水一钟，入糯米一撮，煎服。 \n\\x人参透肌散\\x（十三） 治痘疮虚而有热，虽出快而不齐，隐于肌肤间者。 \n人参 紫草（如无，红花代之） 当归 芍药 茯苓 甘草 木通 蝉蜕 糯米（等分） \n上每服三钱，水一盏，煎半盏。徐服之。 \n\\x十宣散\\x（十四）一名托里十补散。调气补血，内托疮毒，五日后必用之方也，亦治痈疽。 \n人参 黄 当归（各二钱） 川芎 防风 桔梗 白芷 甘草（炙） 浓朴（各一钱） \n桂心（三分） \n上为细末。每服一钱，或二钱，木香汤下。 \n\\x芎归汤\\x（十五）亦名活血散。大能养营起痘。 \n当归（倍用） 川芎 \n上为细末。每服一钱，红花汤调服。 \n\\x活血散\\x（十六） 治痘疹血虚血热，已出未尽，烦躁不宁，腹痛。 \n白芍药（酒炒） \n上为末。每服一匙，糯米汤调下，或荔枝汤亦可。此汤对四君子汤加归、 ，名参归活血散。 \n\\x当归活血散\\x（十七）治痘色淡白。 \n当归（酒焙） 赤芍（酒炒） 川芎 紫草 红花（各五钱） 木香（二钱） 血竭（一钱） \n上为末。每五岁者服一钱，十岁以上服二钱，酒下。 \n\\x养血化斑汤\\x（十八）治白疹白痘。 \n当归身 人参 生地 红花 蝉蜕（等分） \n水一盏，生姜一片，煎六分。温服，无时。 \n\\x人参胃爱散\\x（十九）治痘疹已发未发，吐泻不止，不思饮食等证。 \n人参 茯苓 甘草 丁香 藿香 紫苏 木瓜 糯米 \n上每服三钱，姜、枣、水煎。 \n\\x二仙散\\x（二十） 治体寒肢冷，腹痛口气冷，阴盛阳衰，呕吐泄泻难发等证。 \n丁香（九粒） 干姜（炒，一钱） \n上为细末。每服五七分，白汤送下，被盖片时，令脾胃温暖，阴返阳回，则痘变润矣， \n量大小加减与之。 \n（陈氏）\\x木香散\\x（二一）又名十一味异功散。治小儿痘疹虚寒多滞者宜此。 \n木香 丁香 大腹皮 人参 桂心 炙甘草 半夏（制） 诃黎勒 赤茯苓 青皮 \n前胡（等分） \n上每服二三钱，姜、水煎。 \n《薛按》曰∶前方治痘疮已出未愈之间，其疮不光泽，不起发，不红活，五七日内泄泻作 \n渴，或肚腹作胀，气促作喘，或身虽热而腹胀，足指冷，或惊悸，或汗出，或寒战切牙，或 \n欲靥不靥，疮不结痂，或靥后腹胀，泄泻作渴，此皆脾胃虚寒，津液衰少，急用此药治之。 \n若误认为实热，用寒凉之剂，及饮蜜水、生冷瓜果之类，必不治。 \n（陈氏）\\x十二味异功散\\x（二二）治元气虚寒，小儿痘疹色白，寒战切牙，泄泻喘嗽等证。 \n人参 丁香 木香 肉豆蔻 陈皮 浓朴（各二钱半） 白术 茯苓 官桂（各二钱） \n当归（三钱半） 制附子 半夏（各钱半） \n上咀。每服二三钱，姜、枣、水煎服。愚按∶陈氏此上二方温性有余，补性不足，用治 \n寒证则可，用治虚证则不及也，用者更当详酌。 \n（陈氏）\\x人参麦门冬散\\x（二三）治痘疮微渴。 \n麦门冬（一两） 人参 炙甘草 白术 陈皮 浓朴（姜制，各五钱） \n上每服三四钱，水一大盏，煎至六分。徐徐温服，量儿增减。 \n薛氏曰∶前方治痘疮热毒瓦斯虚宜用之，若因气虚作渴，宜人参白术散。 \n\\x柴胡麦门冬散\\x（二四） 治痘疮壮热，经日不止，更无他证者。 \n柴胡（二钱半） 龙胆草（一钱） 麦门冬（三钱） 甘草（炙） 人参 玄参（各钱半） \n上 咀。每服三钱，水一大盏，煎至六分。不拘时徐徐温服，量大小加减。 \n按∶此方解表之功居六，清火之功居四，养营退热，此方最宜。 \n\\x升均汤\\x（二五）治痘疮已出不匀，或吐泻发热作渴。 \n升麻 干葛 人参 白术（炒） 芍药（炒） 茯苓 甘草 紫草（如无，红花代之） \n上每服三五钱，姜、水煎。 \n\\x升麻葛根汤\\x（二六）亦名升麻汤。解发痘毒之良方。 \n升麻 葛根 芍药 甘草（等分） \n上 咀。水一盏，煎七分。温服，无时。 \n万氏曰∶古人治痘以升麻葛根汤为主，后世好奇，多立方法，法愈多而治愈难矣。苟能 \n通变，则痘疹诸证皆可增减用之，不特发表解肌而已。今以葛根汤为主治，随证立增损法于后∶ \n初发热，解表加柴胡、羌活、白芷、桔梗、防风；口干渴，内热也，加葛粉、天花粉、麦门冬； \n自利，加条实黄苓；呕吐，加半夏、生姜；腹中痛，加木香、青皮、枳壳、山楂肉；腰痛， \n加独活，北细辛；头痛，加羌活、 本、蔓荆子；惊搐，加木通、生地黄、灯心；小便少， \n加木通、车前、瞿麦；大便秘，加大黄；衄血，加山栀仁、玄参、生地黄；发热三 \n四日，热甚不减，须解其毒，加大力子、连翘、紫草；疮不出，加防风、蝉蜕、荆芥穗、红花子； \n目痛，加 \n龙胆草、密蒙花、柴胡；疮出太稠密，加人参、当归、木香、紫草、大力子、防风、桔梗； \n咽痛，加桔梗、连翘；疮干或带紫，或太赤者，血热也，加当归梢、生地黄、红花、地骨皮、 \n牡丹皮；痘平陷、灰白色，气虚也，加人参、白术、防风、木香、官桂；手足疮不起，脾胃不 \n足也，加人参、黄 、防风、官桂；泄泻者，里虚也，加人参、白术、诃子、白茯苓；疮不着 \n痂者，湿也，加黄 、防风、官桂、白芷。 \n愚谓前方乃胃经发表之剂，万氏增减之法，大意已悉。但此方性味清凉，纯于疏泄，必 \n阳明多实多热者，乃宜用之。然小儿气血体质，大都虚弱平和者十居七八，故凡痘疮初起，乍 \n见发热，用药最贵和平，兼养营气，则庶乎尽善。若预用清凉，未免伤其胃气，全用解散， \n未免虚其表气，二者受伤，变患有不可测矣。故余制柴归饮为治痘之先着，所当酌宜用之。 \n若治麻疹，则多属火证，此方乃所宜也。 \n\\x苏葛汤\\x（二七）初热未见点，发表之剂暂用之，分两宜酌儿大小以为增减。 \n苏叶（二钱） 葛根（二钱） 甘草（一钱） 白芍药（钱半） \n连须葱白三根，生姜三片，水钟半，煎七分。热服。原方有陈皮、砂仁各五分，此 \n惟气滞腹痛者宜用之，否则不必。 \n\\x连翘升麻汤\\x（二八）散毒清火。 \n连翘（一钱） 升麻 葛根 桔梗 甘草（各七分） 白芍药（五分） 薄荷（少许） \n上加淡竹叶，灯草，水一盏半，煎一盏。温服，无时。 \n\\x柴胡橘皮汤\\x（二九） \n柴胡 橘皮 人参 半夏 茯苓 黄芩（等分） \n上加竹茹一团，水一盏，煎七分。温服，不拘时。 \n\\x人参败毒散\\x（三十）方在散阵三六。治时疫斑疹。 \n\\x荆防败毒散\\x（三一）亦名消风败毒散。发散痘疹俱可用，及时气风毒邪热。 \n柴胡 荆芥穗 防风 羌活 独活 前胡 川芎 枳壳 人参 甘草 桔梗 茯苓（等分） \n上切细，加薄荷叶，水一盏，煎七分。去滓，温服。 \n\\x柴葛败毒散\\x（三二）疑似伤寒，以此解散。 \n柴胡 干葛 人参 羌活 防风 荆芥 桔梗 苏叶 甘草 \n上用生姜三片，水煎服。 \n\\x参苏饮\\x（三三） 方在散阵三四。治伤风咳嗽，伤寒痘疹。 \n\\x加减参苏饮\\x（三四） 初热见点解利之药，但表邪未达而元气强壮者，宜暂用之，或 \n前后感冒风寒，俱可暂用。 \n苏叶（一钱） 干葛（钱半） 前胡（八分） 陈皮（七分） 枳壳（六分） 桔梗 甘草（各四分） \n水一钟半，加生姜三片，煎服。 \n\\x麻黄甘草汤\\x（三五）冬月痘毒炽盛，表实者宜用之。 \n麻黄（一二钱） 生甘草（减半） \n水煎服。 \n\\x柴葛桂枝汤\\x（三六）表散痘热。 \n柴胡 干葛 桂枝 防风 甘草 人参 白芍药 \n水一盏，加生姜三片，煎七分。温服。 \n\\x桂枝葛根汤\\x（三七）解散寒邪。 \n桂枝 葛根 升麻 赤芍药 防风 甘草（各一钱） \n上加生姜三片，淡豆豉一钱，水一钟，前七分。温服，无时。 \n\\x十味羌活散\\x（三八）此初热见点解利之剂，若小儿身壮力强者，可用苏葛以行表，其 \n次者宜此和解疏利之药，若 \n虚而宜补者，必当兼顾元气，不得单用此类。 \n羌活 前胡 防风（各一钱） 荆芥 独活（各八分） 细辛 白芷（各三分） 柴胡 \n炙甘草 蝉蜕（各四分） \n水一钟半，加薄荷三叶，煎五分。不拘时服。发搐及热盛不遏者，调入制过朱砂末 \n服之，神效。 \n\\x十三味羌活散\\x（三九）解热散毒，治风壅欲作痘疹者。 \n羌活 独活 防风 桔梗 荆芥 柴胡 前胡 地骨皮 炙甘草 蝉蜕 川芎 天花粉 \n天麻（等分） \n上为细末。每服二三钱，水一盏，入薄荷叶三片，煎四分。温服。 \n\\x羌活汤\\x（四十）解发痘疮，兼治肝热惊狂。 \n羌活 川芎 防风 山栀仁 龙胆草 当归（等分） 甘草（减半） 淡竹叶 薄荷叶 \n水煎。温服，无时。 \n\\x双解散\\x（四一）痘疹表里俱实者，非此不解。 \n防风 川芎 当归 连翘 芍药 薄荷 大黄（各五分） 石膏 桔梗 黄芩（各八分） \n荆芥穗 白术 桂枝（各二分） 滑石（二钱四分） 甘草（二钱） \n水二钟，加生姜三片，煎一钟。温服，无时。此即防风通圣散减去麻黄、芒硝、栀子， \n外加桂枝也。 \n\\x柴胡散子\\x（四二） 治痘疮表里俱实良方。 \n柴胡 防风 当归 人参 白芍药 甘草 黄芩 滑石 大黄（等分） \n上加生姜一片，水煎服。 \n\\x桂枝大黄汤\\x（四三） 治腹痛，大便不通良方。 \n桂枝 白芍（各二钱半） 甘草（五分） 大黄（一钱半） \n上锉细，加生姜一片，水一钟半，煎八分。食前温服。 \n\\x防风芍药甘草汤\\x（四四） 解痘毒，及阳明经痘出不快。 \n防风 芍药 甘草（等分） \n上每服一二钱，水煎服。 \n\\x荆芥防风甘草汤\\x（四五） 解痘毒，及太阳经痘出不快。 \n荆芥 防风 甘草（等分） \n上每服一二钱，水煎。 \n\\x蝉蜕膏\\x（四六） 治痘疮虚陷不起。 \n蝉蜕 当归 川芎 甘草 升麻 防风 荆芥穗（等分） \n加人参 白芍药 \n上为末，炼蜜丸，如芡实大。每服一丸，薄荷汤下。 \n\\x消毒散\\x（四七） 亦名消毒饮。治痘疮六七日间，身壮热，不大便，其脉紧盛者， \n用此药微利之。 \n荆芥穗 炙甘草（各一两） 牛蒡子（四两，杵炒） \n上为粗散。每服三钱，水一盏，煎七分。不拘时徐徐服。 \n\\x四味消毒饮\\x（四八）治痘疮热盛，毒瓦斯壅遏，无问前后皆可服。 \n人参 炙甘草 黄连 牛蒡子（等分） \n上为粗末。每服一钱，加姜一片，水一盏，煎四分，去滓。温服，不拘时。 \n\\x六味消毒饮\\x（四九）解痘毒。 \n牛蒡子 连翘 甘草 绿升麻 紫草 山豆根（等分） \n水一盏，煎七分。温服，不拘时。 \n\\x消毒化斑汤\\x（五十） 消风散毒，清眼目咽喉。 \n升麻 柴胡 桔梗 甘草 连翘 龙胆草 牛蒡子 防风 蝉蜕 密蒙花 \n水一钟半，加淡竹叶十片，煎服。 \n\\x解毒汤\\x（五一）治一切热毒肿痛，或风热瘙痒。 \n黄连 金银花 连翘 \n上水煎服。 \n\\x真人解毒汤\\x（五二） 治痘母。 \n忍冬花（半斤） 甘草节（一两） 木通 防风 荆芥 连翘（各三钱） \n上分作三剂，用水、酒各一钟煎服，以肿消痘出为度。 \n\\x葛根解毒汤\\x（五三） 解痘毒止渴良方。 \n葛根 升麻（减半） 生地黄 麦门冬 天花粉（等分） 甘草（减半） \n上取糯米泔水一盏，煎七分，入茅根自然汁一合服之。 \n\\x实表解毒汤\\x（五四） \n人参 黄 当归梢 生地黄 甘草 白芍药 柴胡 升麻 酒片芩 玄参 地骨皮 \n上入薄荷叶少许，淡竹叶十片，水煎服。 \n\\x溯源解毒汤\\x（五五）解胎毒之良方。 \n当归身 川芎 生地黄 白芍药 人参 生甘草 黄连 连翘 陈皮 木通（等分） \n水一盏，加淡竹叶十片，煎半盏。温服，无时。 \n（陈氏）\\x解毒防风汤\\x（五六）治痘疮毒瓦斯炽盛。 \n防风 黄芩 地骨皮 白芍药（炒） 荆芥 牛蒡子 \n上每服四五钱，水煎服，或为末，白汤调下。外科解毒防风汤方见本门六三。 \n\\x化毒汤\\x（五七） 治痘未出腹痛者。 \n白芍药 炙甘草（各一钱） 木香 青皮 枳壳（各七分） 山楂肉 连翘 肉桂（各五分） \n水一盏，煎七分。温服，不拘时。 \n\\x消风化毒汤\\x（五八） \n防风 黄 桂枝 荆芥穗 升麻 白芍 牛蒡子（等分） 甘草（减半） \n上加薄荷叶七片，水一盏，煎七分。温服，无时。 \n\\x凉血化毒汤\\x（五九）治痘疮初出，头焦黑。 \n归尾 赤芍药 生地黄 木通 连翘 牛蒡子 红花 紫草 桔梗 山豆根 \n上水煎服。或加童便一小盏亦可。 \n\\x犀角化毒丸\\x（六十）治诸积热，及痘疹后余毒生疮，口舌牙龈糜烂等证。 \n犀角屑（镑） 生地黄 当归 防风 荆芥穗（各一两） 牛蒡子（炒杵） 赤芍药 连翘 \n桔梗（各七钱） 薄荷 黄芩（炒） 甘草（各五钱） \n上为末，炼蜜丸，芡实大。每服一丸，薄荷汤下。 \n\\x五福化毒丹\\x（六一）治胎毒，及痘后头面生疮，眼目肿痛。 \n生地黄 天门冬 麦门冬 玄参 熟地黄（各三两） 甘草 甜硝（各二两） 青黛（两半） \n上为末，炼蜜丸，芡实大。每服一丸，白汤或薄荷汤化下。 \n（《外科》）\\x五福化毒丹\\x（六二） 方在外科七六。治一切热毒疮疖。 \n\\x犀角散\\x（六三） 治痘疮、痈毒、时毒热盛，烦躁多渴，小便赤涩，或赤斑。 \n犀角（镑） 甘草（炙，各半两） 防风 黄芩（各一两） \n上为粗末。每服二钱，水一小盏，煎五分。温服，无时。 \n\\x紫草化毒散\\x（六四）解实热毒发痘。 \n紫草 升麻 炙甘草（等分） 糯米（五十粒） \n水煎服。 \n\\x紫草散\\x（六五） 治痘疹黑陷，气血虚弱，疮疹不起。 \n紫草 黄 （炙） 炙甘草 糯米（各钱半） \n上水煎服。 \n\\x紫草饮\\x（六六） 治痘疮黑陷不起。 \n紫草 当归 芍药 甘草 麻黄（等分） \n水一盏，煎。不拘时服。 \n\\x紫草饮子\\x（六七） 治倒陷腹胀，大小便秘。 \n紫草 人参 枳壳 山楂 木通 穿山甲（土拌，炒） 蝉蜕（等分） \n水一盏，煎五分，作三四次温服。 \n\\x紫草快斑汤\\x（六八） 一名紫草汤。治痘疹血气不足，或血热不能起发，色不红活， \n不灌脓等证。 \n紫草 人参 白术 当归 川芎 芍药 茯苓 甘草 木通（等分） 糯米 \n上每服三五钱，水煎。 \n\\x紫草木香汤\\x（六九） 治痘疮里虚，痒塌黑陷闷乱。 \n紫草 木香 人参 白术 茯苓 甘草（炙） 糯米 \n上每服三钱，水煎。 \n\\x紫草木通汤\\x（七十）治痘疹出不快。 \n紫草 人参 茯苓 木通 甘草（减半） 糯米（等分） \n上每服二三钱，水煎服。 \n\\x紫草膏\\x（七一）红紫黑陷者，暂用之。 \n紫草茸 白附子 麻黄（去节，汤泡，去黄沫，晒干用） 甘草（炙，各半两） \n僵蚕（炒） 全蝎（炒，各八个） \n上为细末，用白蜜一两，好酒半盏，先将紫草煎熬成膏，旋入各药丸，皂子大。每服 \n一丸，紫草煎汤化下，就用补药调理。如治惊搐，以金簿为衣，薄荷汤下。"}, {"n": 39, "text": "卷三十九\n\n\\x红棉散\\x（七二） 亦名天麻散。治痘疹身有大热，面赤气粗，无汗而表未散者可 \n服之。此药以麻黄、天麻发表为主，有汗者不可服。盖腠理已开，不可再发汗也。若有汗而 \n热，则当以惺惺散为和解之剂。故仲景之治表证，有宜发汗者，有宜和解者，有宜调和 \n营卫者。若有汗而热者，则和解为宜；虚而热者，则调和营卫为宜，如和中散寒之类是也。 \n麻黄（去节） 天麻 荆芥 炙甘草（各二钱） 全蝎（全者七枚） \n上为末。每服一钱，以水半盏，薄荷叶二片，入酒四五滴，煎二三沸。带热服之，如疹 \n未出，再进一服，次又一服，即伤风寒证，服亦无妨。 \n\\x快斑汤\\x（七三）治起发迟。 \n人参（五分） 当归 防风 木通（各一钱） 甘草（三分） 木香 紫草 蝉蜕（各二分） \n水一盏，煎七分。温服，不拘时。 \n\\x快斑越婢汤\\x（七四） 治痘疮手足不起发。 \n黄 （炙） 白芍药 桂枝 防风炙甘草 \n上加生姜一片，枣一枚，水煎服。 \n\\x快透散\\x（七五）治痘出不快。 \n紫草 蝉蜕 木通 芍药 炙甘草（等分） \n上每服二钱，水煎。 \n王海藏先生云∶身后出不快，足太阳经也，用荆芥甘草防风汤。身前出不快，手阳明 \n经也，用升麻葛根汤。 \n四肢出不快，足阳明经也，用防风芍药甘草汤。此皆解毒升发之药也，不可不知。 \n\\x鼠粘子汤\\x（七六） 治痘稠身热毒盛，服此以防青干黑陷，并治斑疹稠密。 \n牛蒡子（炒） 归身 黄 炙甘草 柴胡 黄芩（酒炒） 连翘 地骨皮 \n上等分，水煎。热退则止服。 \n\\x射干鼠粘子汤\\x（七七）治痘疮壮热，大便坚实，或口舌生疮，咽喉肿痛，皆余毒所致。 \n鼠粘子（四两，炒杵） 甘草（炙） 升麻 射干（各一两） \n上每服三钱，水一大盏，煎六分。徐徐温服。 \n薛氏曰∶前方若痘疹初出，发热 痛，根盘赤盛，或咽喉口舌疼痛，作渴引饮者宜用。 \n若因胃气虚弱发热而致前症者，宜人参麦门冬散。 \n（钱氏）\\x独圣散\\x（七八） 治痘疮倒靥陷伏。 \n用穿山甲取前足嘴上者，烧存性为末。每服四五分，以木香汤入少酒服之，或紫草汤 \n亦可。 \n\\x无价散\\x（七九）治一切痘疮倒陷，焦黑危急之症。 \n人牙 猪牙 狗牙 猫牙 \n上以炭火烧去烟存性，等分为末。每服三分，热酒调下。如痒塌寒战泄泻，煎异功散 \n调下。一方，人牙散∶只用人牙烧去烟存性，为末，酒调服。 \n\\x三酥饼\\x（八十）治初发热用以表汗解毒稀痘，神效。 \n辰砂 择上好明净无砂石者，以绢囊盛之，用麻黄、升麻、紫草、荔枝壳同煮一日夜， \n研细，仍用前汤飞 \n过，晒干，再研极细，用真蟾酥另调作饼子。 \n麻黄去节，汤泡过，晒干为极细末，亦用蟾稣另调作饼。 \n紫草研极细，亦用蟾酥另调作饼。 \n蟾酥于端午日捉蟾取酥，捻前三饼，每饼加麝香少许，微炒。 \n上方如遇时行痘疹，小儿发热之初，每三岁者，将三饼各取半分，热酒化下，盖覆出汗， \n如不能饮酒，用败毒散煎汤化下更好。若痘已出满，顶红紫色，为热毒之盛，宜煎紫草红花汤， \n或化毒汤，将辰砂、紫草二饼调下少许以解之，但痘出之后不可服麻黄饼也。盖辰砂能解毒， \n紫草凉心火，制过亦能发痘解毒，麻黄能发表发痘，蟾酥能驱脏腑中毒瓦斯从毛腠中作臭汗而出， \n此四药诚解毒稀痘之神方也。 \n\\x神应夺命丹\\x（八一）治风邪倒陷及痘毒入里。 \n辰砂（择墙壁镜面者，以白纱囊盛之，用升麻、麻黄、紫草、连翘四味同入砂罐， \n以新汲水、桑柴火煮一昼夜，取出将砂研细，仍将煮砂药汁去滓飞取末，待干听用二钱） \n麻黄（连根节，酒蜜拌炒焦，八分） 蝉蜕（洗净去足，三分） 紫草（酒洗，五分） \n红花子（五分） 穿山甲（酒炒，五分） 真蟾酥（三分） \n上共研细末，用FS 酒杵丸，分作千粒，周岁者半丸，二岁者一丸，服止三丸，热酒化服， \n浓盖取汗汗出痘随出也。择天医生气日修合。此方与三酥饼功同。 \n（万氏）\\x夺命丹\\x（八二） 治倒陷解发痘毒。 \n麻黄（蜜酒炒焦） 升麻（各五钱） 山豆根 红花子 大力子 连翘（各二钱半） \n蝉蜕 紫草 人中黄（各三钱） \n上研细末，酒、蜜和丸，辰砂为衣。薄荷叶煎汤下。 \n（东垣）\\x凉膈散\\x（八三）解痘疹里热良方。 \n黄芩 连翘（为君） 甘草 栀子 薄荷 桔梗 竹叶 \n上水煎服。 \n\\x退火丹\\x（八四）治痘中狂妄，神方。 \n滑石 朱砂（飞，各一钱） 冰片（三厘） \n共为细末。冷水调一分服。得睡，少时神安气宁，痘转红活矣。 \n（陈氏）\\x通关散\\x（八五）通心经，降心火，利小便良方。 \n山栀仁 大黄（炒，各一分） 木通 甘草（炙） 车前子（炒） 赤茯苓 人参 瞿麦 \n滑石（各三分） 扁蓄（炒，五分） \n上用水一盏，灯草十根，煎半盏。温服。 \n\\x玄参地黄汤\\x（八六） 治痘疹衄血。 \n玄参 生地黄 牡丹皮 栀子仁（各钱半） 甘草 升麻（各半钱） 白芍药（一钱） \n蒲黄（炒，五分） \n水一钟，煎七分。温服。愚谓此方宜去升麻以塞上冲之源，勿谓但属阳明即宜用升麻也。 \n（万氏）\\x清肺饮\\x（八七）治肺热喘嗽声哑。 \n麦门冬 桔梗（各二钱） 荆芥穗 天花粉 知母（各一钱） 石菖蒲 诃子仁（各八分） \n上水煎服。此当与清肺汤参用，方在后一四五。 \n\\x导赤通气散\\x（八八）治心虚声不扬者。 \n木通 生地黄 人参 麦门冬 当归身 石菖蒲 甘草 \n上加灯心，水煎服。 \n\\x甘桔清金散\\x（八九）治肺热咽痛，声不清。 \n桔梗（一两） 甘草 连翘（各半两） 诃子皮（三钱） 牛蒡子（炒，七钱） \n上为细末。每服一钱，薄荷叶少许同前服。 \n\\x加味甘桔汤\\x（九十）咽喉肿痛暂用。 \n桔梗（八分） 甘草（钱二分） 牛蒂子 射干（各六分） 防风 玄参（各四分） \n水一钟，煎服，或加生姜一片。热甚者，加黄芩，去防风亦可。 \n\\x大如圣饮子\\x（九一）治疮疹痘毒攻咽嗌，肿痛热渴，或成肿毒不消等证。 \n桔梗 甘草 鼠粘子（炒，各一两） 麦门冬（五钱） \n上每服二钱，水煎。 \n（万氏）\\x橘皮汤\\x（九二）行滞消痰止呕吐。 \n橘皮（半去白，炒，二钱） 半夏（一钱） 白茯苓（钱半） \n上加生姜三片，水一盏，煎七分。温服。 \n\\x匀气散\\x（九三） 行气化滞。 \n木香 青皮（各五钱） 山楂肉（二钱半） \n上为末。每服一钱，甘草汤调服。 \n\\x前胡枳壳汤\\x（九四）治痰实壮热，胸中烦闷，大便坚实，卧则喘急。 \n前胡（一两） 枳壳 赤茯苓 甘草（炙） 大黄（各半两） \n上 咀。每服三五钱，水一大盏，煎至六分。不拘时温服。此方宜量大小加减， \n如身温脉微并泻者，不可服。 \n薛氏曰∶前症苦属肺胃实热，气郁痰滞，大便秘结，小便赤涩，烦渴饮冷，身热脉实者，宜 \n用之以疏通五内，使邪无壅滞，则痘疮轻而易愈也。 \n\\x当归丸\\x（九五） 治便坚三五日不通者。 \n当归（半两） 紫草（三钱） 黄连（钱半，炒） 炙甘草（一钱） 大黄（二钱半） \n上以当归、紫草熬成膏，下三味研为细末，以膏和为丸，如胡椒大。三岁以下儿服十丸， \n七八岁儿二十丸，食前清米饮下，渐加之，以和为度。 \n\\x百祥丸\\x（九六）治痘疮紫黑干陷，热毒便秘里实等症。红芽大戟不拘多少，用浆水煮 \n极软，去骨，日中晒干，复内原汁中煮，汁尽焙干研末，水丸，粟米大。每服一二十丸，研赤 \n芝麻汤下。 \n\\x枣变百祥丸\\x（九七）治同前而稍缓，可代百祥丸。 \n红芽大戟（去骨，一两） 青州枣肉（三十个） \n上用水一碗，同煎至水尽为度，去大戟不用，将枣焙干，可和作剂，或捣烂为丸。从 \n少至多，以木香汤吞服，至利为度。 \n\\x排毒散\\x（九八）治痘毒发痈。 \n大黄 当归梢（各一两） 白芷 沉香 木香（各半两） 穿山甲（七片，土炒焦） \n上为细末。看虚实大小加减，长流水煎沸调服。 \n（钱氏）\\x苦参丸\\x（九九）治痘后溃烂，疮毒疮癞。 \n苦参（一两） 白蒺藜 何首乌 牛蒡子 荆芥穗（各半两） \n上为末，酒调面糊为丸。竹叶汤下。外科苦参丸见本门八八。 \n\\x稀痘方\\x（百） \n用老鼠去皮取肉，水煮熟，量儿大小与食数次，出痘甚稀，未食荤时与食尤效， \n屡试屡验。 \n\\x稀痘酒\\x（百一） 最能散毒稀痘。 \n麻黄（去节，泡） 紫草（各二两） \n上二味，细切，布囊盛之，浸无灰酒一小坛，泥封固，凡遇天行小儿发热时，与半 \n杯或一杯，量儿大小服之，出微汗为佳。 \n\\x三痘汤\\x（百二） 痘发时预服之。 \n大黑豆 赤小豆 绿豆（等分，淘净） \n上用甘草浸水去渣，以甘草水煮豆熟为度，逐日空心任意饮其汁，自然出少。此方冬 \n月煮熟，令儿常食豆尤妙。 \n\\x丝瓜汤\\x（百三） 解疮毒。一方无山楂。 \n丝瓜 升麻 芍药（酒炒） 生甘草 山楂 黑豆 赤小豆 犀角（镑、等分） \n上为粗散。每服三钱，水一大盏，煎至六分。不拘时徐徐温服，量大小加减。 \n\\x辰砂散\\x（百四） 预解痘毒。 \n好辰砂（一钱，飞） 老丝瓜（近蒂三寸，连子烧灰存性。此物发痘疮最好） \n上研末。蜜水调服，多者可少，少者可无，或以紫草甘草汤调服尤佳。 \n\\x保婴丹\\x（百五） 稀痘。 \n缠豆藤（或黄豆，或绿豆梗上缠绕细红藤是也。于八月生气日择取，阴干听用，二两） \n防风 荆芥穗 牛蒡子（炒） 紫草茸（去根，酒浸，一两） 新升麻（盐水炒） \n甘草（去皮，各五钱） 天竺黄（真者三钱） 蟾酥（真者一钱） 牛黄（真者一钱） 赤小豆 \n黑豆 绿豆（各三十粒，略炒勿焦） 好朱砂（用麻黄、紫草、荔枝壳、升麻同煮过，复 \n以此汁飞过，三钱） \n上另用紫草二两，入水二碗，煎膏至少半碗，入沙糖一小钟，将前各药为细末，同紫 \n草膏丸如李核大，即以朱砂为衣。于未痘之先，浓煎甘草汤每磨服一丸，大者二丸；若已 \n发热，用生姜汤磨服，盖被睡而表之， \n多者可少，少者可无，大有神效。一方无紫草茸，仍有经霜老丝瓜一个，连藤蒂五寸烧 \n存性同用。 \n\\x洗肝明目散\\x（百六） 治痘后目疾。 \n当归 羌活 柴胡 密蒙花 川芎 防风 木贼 山栀仁 龙胆草（各等分） \n上为末。每服一钱，淡沙糖水调服。 \n\\x洗肝散\\x（百七） 翳膜遮睛暂用。 \n归尾（钱二分） 防风（八分） 大黄（八分） 羌活 川芎 薄荷（各四分） 栀子（钱半） \n甘草（三分） \n水一钟，姜一片，煎服。热盛便秘加芩、檗。 \n\\x羊肝散\\x（百八） 治痘毒入眼，或无辜疳气入眼。 \n密蒙花（二钱） 青葙子 决明子 车前子（炒，各一钱） \n上为末，用羊肝一大叶，薄批掺上，湿纸裹煨熟。空心食之。 \n\\x蒺藜散\\x（百九） 治痘疮入眼肿痛。 \n白蒺藜 谷精草 防风 羌活 生蛤粉（等分） \n上为细末。每服二钱，温水调服即退。 \n\\x蝉菊散\\x（百十）治痘疹入目，或病后生翳障。 \n蝉蜕（去土净） 白菊花（等分） \n每服一二三钱，水八分，加蜜少许，煎四分。食后温服。 \n\\x秦皮散\\x（百十一）治大人小儿风毒赤眼，痛痒涩皱，眵泪羞明。 \n秦皮 滑石 黄连（等分） \n汤泡热洗，日二三次。 \n\\x通神散\\x（百十二） 治痘疮入眼，生翳膜。 \n白菊花 谷精草 绿豆皮 \n上为末。每服一钱，用柿饼一个，米泔水一盏同煎，候水干。只吃柿饼，每日三五次不 \n拘，至七日效。 \n（钱氏）\\x黄柏膏\\x（百十三） 用此护眼，可免痘毒入目。 \n黄柏（一两） 绿豆末（二两） 生甘草（三两） \n上为细末，以麻油调成膏，用涂耳前、眼角、目下四五遍，若早涂之，痘出必稀，若既 \n患眼，涂之必减。 \n\\x痘疔散\\x（百十四） \n雄黄（一钱） 紫草（三钱） \n上为细末，胭脂汁调、用银簪脚挑破黑痘，入药在内。此下二方皆治痘疔之良方也。 \n\\x四圣丹\\x（百十五）治黑疔。 \n牛黄（钱二分） 儿茶（钱七分） 朱砂（八分） 珍珠（二分） \n上为极细末，以棉胭脂汁或油胭脂调匀。先用银针挑破黑疔，拭去恶血，乃点药疔上。 \n（万氏）\\x四圣散\\x（百十六） 治痘不起发，变黑而痛者，痘疔也。亦名鬼痘。 \n绿豆（四十九粒） 豌豆（四十九粒，各烧存性） 珍珠（一分） 油头发（烧存性，一分） \n上为细末，用胭脂水调，先以簪脚拨开黑痘，以此涂之。 \n\\x神效隔蒜灸法\\x（百十七） 治痘疔毒瓦斯炽盛，使诸痘不能起发，已起发者不能灌脓， \n已灌脓者不能收靥，或大痛，或麻木，痛者灸至不痛，不痛者灸至痛，其毒随火而散。其法用 \n大蒜头切三分浓，安痘疔上，用小艾炷于蒜上灸之，每五壮易蒜再灸，若紫血出后，肿痛不 \n止，尤当用灸，治者审之。愚在京师，尝见治痘疔者，即以线针挑破出毒血，诸痘随即灌脓。 \n若挑破不痛，不出血者难治，若用此法灸之，即知痛，更用针挑破，紫血 \n随出，诸痘随灌，亦有生者。 \n\\x胡荽酒\\x（百十八） 辟秽气，使痘疹出快。 \n用胡荽一把，以好酒二盏，煎一两沸。令乳母每含一两口，喷儿遍身，或喷头面。房 \n中须烧胡荽香以辟除秽气，能使痘疹出快。煎过胡荽悬房门上最妙。或用枣炙之，儿闻枣香， \n尤能开胃气，进饮食，解毒瓦斯。按∶ \n此酒惟未出之前，及初报之时宜用之，若起胀之后，则宜避酒气，亦忌发散，皆不可用也。 \n\\x茵陈熏法\\x（百十九） \n用干茵陈研末，捣枣膏和丸，如鸡子大，晒干，用烈火烧烟熏之。 \n\\x水杨汤\\x（百二十） 治倒陷之良方。 \n水杨，即忍冬藤也。春冬用枝，秋夏用枝叶，生水边，细叶红梗，枝上有圆果，满果 \n有白须散出。切断，用长流水一大釜，煎六七沸，先将三分之一置浴盆内，以手试其适可， \n仍先服煎药，然后浴洗，渐渐添汤，以痘起发光壮为度，不拘次数。洗毕照视，若累累然起处 \n觉晕，晕有系，此浆影也。如浆不满，宜再浴之。 \n若弱者，只浴头面手足亦可。此则不厌多洗，洗后如无起势，乃气血败而津液枯， \n多不可治。 \n\\x秘传茶叶方\\x（一二一） 铺床席用。 \n茶叶要多，楝去粗梗，入水一煮取起，再楝去梗，湿铺于床上，用草纸隔层，令儿睡 \n上一夜，则脓水皆干。 \n\\x猪髓膏\\x（一二二） 治痘疹不靥，及痂靥不落者，涂之即落。 \n猪骨髓 白蜜 \n上二味，以火熬一二沸，退凉，用鸡翎扫上即落。 \n\\x百花膏\\x（一二三） 治痘燥痂皮溅起作痛，或疮痂欲落不落者。 \n蜜不拘多少，略用汤和，时时以鹅翎润痛处，疮痂亦易落，无痕。 \n\\x荞麦散\\x（一二四） 治痘疮溃烂，以此敷之。 \n荞麦一味，磨取细面，痘疮破者，以此敷之；溃烂者，以此遍扑之，绢袋盛扑，或以此衬 \n卧尤佳。 \n\\x胭脂汁\\x（一二五） 治黑痘之良方。 \n先用升麻一味，煎浓汤，去滓，却用棉胭脂浸于汤内揉出红汁，就以本棉蘸汤于疮上拭 \n而涂之。 \n\\x败草散\\x（一二六） 治痘疮挝搔成疮，脓血淋漓，谓之斑烂。用盖屋盖墙烂草，多年 \n者佳，或旷野自烂者尤佳，为末搽掺之。或气血虚，热不愈而遍身患者，须多掺席铺上，令儿 \n坐卧其上，其疮即愈。 \n\\x白龙散\\x（一二七） 治烂痘及抓破者。 \n用干黄牛粪在风露中多久者，火 成灰，取中心白者为末，以薄绢囊盛裹，于疮上扑之。 \n\\x救苦灭瘢散\\x（一二八） 治烂痘以此敷面，如误抓破者，用之敷贴最良。 \n密陀僧 滑石（各二两） 白芷（半两） \n上为细末。湿则干掺之，或用好蜜调敷。 \n\\x灭瘢散\\x（一二九） 治痘后面疮，以此敷之。 \n密陀僧 白附子 白僵蚕 白芷 鹰矢白（等分） \n上研极细末，以水调搽面 ，神效。 \n\\x辟邪丹\\x（百三十） 用烧于房中，能辟一切秽恶邪气。 \n苍术（以黄连代之更妙） \n乳香 降真香 甘松 北细辛 芸香（各等分） \n上为末，水丸，如豆大。每焚一丸熏之，良久又焚一丸，不可太多，只是略有香气，使 \n之不断可也。 \n\\x砭法\\x（一三一） 治丹瘤。 \n用细瓷器击碎取锋 者，以箸一根，劈开头夹定，用线缚住，两指轻捻箸梢，令瓷锋正对 \n毒顶，悬高寸许，另用一箸轻击箸头，令毒血遇刺而出，即可解散。 \n\\x蜞针法\\x（一三二） 治痘痈及丹瘤。 \n用水蛭大者五六根，放肿毒头上吮去恶血，可以消丹瘤，决痈肿。 \n\\x雄黄散\\x（一三三） 治痘后牙龈生疳蚀疮。 \n雄黄（一钱） 铜绿（二钱） \n上为末，干掺之。 \n\\x绵茧散\\x（一三四） 治痘疮余毒，肢体关节生疳蚀疮，脓水不绝。 \n出蛾绵茧（不拘多少） 生白矾（入茧内，以炭火 枯） \n上为细末，干贴疳疮口内。此总治疮毒脓水淋漓，收敛之外剂。 \n\\x搽牙散\\x（一三五） 治痘后余毒攻牙生疳，一日烂进一分，急用此搽之。 \n铜绿 雄黄 五倍子 枯矾 胡黄连 北细辛 乌梅（同褐子包固，火 存性） \n上等分为末搽之。 \n\\x吹口丹\\x（一三六） 治疳。 \n黄连 青黛 儿茶 片脑 \n上等分为末吹之。 \n\\x生肌散\\x（一三七） 痘后痈毒不收口，用之神效。 \n枯矾（三钱） 海螵蛸 赤石脂（ ，各二钱） 龙骨（ ） 黄丹（飞炒） 乳香（出汗） \n没药（出汗，各一钱） 血竭（五分） 轻粉 麝（各二分） \n为细末，掺疮口内，外以太乙膏贴之。 \n\\x马鸣散\\x（一三八） 治走马疳良方。 \n人中白（即尿缸底白 也。以物刮取，新瓦盛之，火 如白盐乃佳，半两） 五倍子（生者一 \n钱，另用一钱同矾 之） 马鸣蜕（即蚕蜕纸也。火烧过，二钱半） 枯白矾（二钱。即用五 \n倍子一钱，入矾于内 枯者） \n上为极细末，先以浓米泔水浸洗疮口，以此敷之。 \n\n\n\n<目录>卷之六十三长集·痘疹诠古方\\痘疹\n\n<篇名>以下麻疹方\n\n属性：\\x升麻汤\\x（一三九） 解散疹毒。 \n升麻（去须） 葛根（去皮，各一钱） 芍药（酒浸，二钱） 炙甘草（一钱） \n水一盏，煎五分。食远稍熟服，量人大小加减。 \n予按∶此方即升麻葛根汤也，麻疹之证多属阳明火毒，凡欲解表散邪，但表实邪盛者最宜 \n用此。然愚谓以柴胡代升麻用之更妙。若血气稍虚而邪有未解者，惟柴归饮为最妥。 \n\\x升麻透斑汤\\x（百四十） 治疹疮初见红点一日至三日。 \n升麻 枳壳（麸炒，各五分） 柴胡（钱半） 桔梗 前胡（各一钱） 干葛 川芎 茯苓（各七分） \n陈皮 半夏 甘草（各四分） \n上加生姜一片水一钟，煎五分，作十余次徐服之。 \n\\x葛根麦门冬散\\x（一四一） 治小儿热毒斑疹，头痛壮热，心神烦闷。 \n葛根（三钱） 麦门冬（四钱） 人参 川升麻 茯苓 甘草（各二钱） 石膏（半两） \n赤芍药（一钱） \n上 咀。每服三钱，水一大盏，煎至六分。不拘时徐徐温服，仍量儿大小增减。 \n薛氏曰∶前方足阳明胃经之药也，外除表邪，内清胃火，兼补元气，若非发热作渴，表 \n里有热者不可用。 \n若表里俱虚而发热作渴者，宜用人参麦门冬散。 \n（万氏）\\x麦门冬汤\\x（一四二） 治表邪内热，咳嗽甚者。此即前方去人参者，但分两稍异耳。 \n麦门冬 葛根（去皮，各一钱） 升麻（去须，四分） 赤芍药（酒炒） 茯苓（各六分） \n炙甘草（四分） 石膏（ ，一钱半） \n上水煎服。 \n（万氏）\\x柴胡四物汤\\x（一四三） 治疹后余热。 \n柴胡 当归身 川芎 生地黄 白芍药 人参 麦门冬 知母 淡竹叶 黄芩 地骨皮 \n上锉细。水一盏，煎七分。不拘时温服。 \n\\x生地黄散\\x（一四四） 治小儿斑疹，身热口干，咳嗽心烦者。 \n生地黄（半两） 麦门冬（七钱） 款冬花 陈皮 杏仁（各三钱） 炙甘草（二钱半） \n上每服三五钱，水一大盏，煎六分。不拘时徐徐温服，量大小加减。 \n\\x清肺汤\\x（一四五） 治斑疹咳嗽甚者，或二母散，或麦门冬汤。 \n桔梗（去芦） 片芩 贝母（各七分） 防风（去芦） 炙甘草（各四分） 知母（七分） \n上水一钟，煎五分，入捣碎苏子五分，再煎温服。 \n\\x清肺消毒汤\\x（一四六） 治疹疮收完，不思饮食，鼻干无涕。 \n防风 枳壳（各五分） 连翘 前胡 黄芩 桔梗（一钱） 荆芥 炙甘草 \n上水一钟，煎至五六分，作十余次徐服之。 \n\\x门冬清肺汤\\x（一四七） 治疹后咳嗽不止。 \n天门冬（去心） 麦门冬（去心） 款冬花 知母 贝母 桔梗 牛蒡子 地骨皮 \n杏仁（去皮尖） 马兜铃 甘草（等分） \n水一钟半，前七分。食后温服。 \n\\x清肺消毒化痰汤\\x（一四八） 治疹后喘嗽，声音不清，不思饮食，眼目不清，唇口干燥。 \n牛蒡子 防风 荆芥穗 贝母（各五分） 连翘 黄芩 前胡 茯苓（各七分） 桔梗 \n枳壳（各一钱） 甘草（三分） \n上水一钟，煎五分，作十余次徐服之。 \n\\x清金降火汤\\x（一四九） 治疹后肺热声哑咳喘。 \n当归 白芍药（酒炒） 生地黄（酒洗） 栝蒌仁 白茯苓 陈皮 贝母（去心） \n甘草 麦门冬 桑白皮 枯芩（酒炒） 山栀（炒） 玄参 杏仁（去皮尖） 苏梗 \n天门冬 黄连（炒） 石膏 \n上等分，加姜一片，水煎服。 \n\\x二母散\\x（百五十） 方在寒阵四九。治肺热咳嗽，及疹后嗽甚者。 \n\\x透斑和中汤\\x（一五一） 治疹疮二三日泄泻。 \n升麻 干葛 猪苓 泽泻 陈皮 半夏 川芎 茯苓（各七分） 前胡 桔梗（各一钱） \n柴胡（钱半） 甘草（三分） \n上加生姜三片，水一钟，煎至五分，作数次徐服之。 \n\\x解毒化滞汤\\x（一五二） 治疹后吃食太早，咬指甲，撕口唇，FS 眼毛，看手，咬人等证。 \n防风 荆芥 枳壳 神曲（炒） 麦芽（炒，各五分） 连翘 黄芩 茯苓 前胡（各七分） \n桔梗（一钱） 山楂 甘草（各三分） \n上水一钟，煎五分，作十余次徐徐服之。 \n\\x大青汤\\x（一五三） 解斑疹大毒良方。 \n生地黄 石膏 玄参 地骨皮 知母 木通 甘草 青黛 荆芥穗（各等分） \n上水一盏，加淡竹叶十二片，煎七分。温服，无时。 \n\\x羚羊角散\\x（一五四）治小儿斑疹后，余毒不解，上攻眼目，羞明云翳，眵泪俱多， \n红赤肿闭。 \n羚羊角（镑） 黄 黄芩 草决明 车前子 升麻 防风 大黄 芒硝（等分） \n水一盏，煎半盏，稍热服。 \n\\x羌菊散\\x（一五五） 治痘疹热毒上攻，眼目生翳并暴赤羞明。 \n羌活 甘菊花 蝉蜕 蛇蜕 防风 谷精草 木贼 甘草 白蒺藜 山栀子 大黄 黄连 \n沙苑蒺藜（等分） \n上为末。每服一钱，清米汤调下。 \n\n\n\n<目录>卷之六十三长集·痘疹诠古方\\痘疹\n\n<篇名>以下通用方\n\n属性：\\x人参理中汤\\x（一五六） 方在热证一。 \n治脾胃虚寒诸证。 \n\\x六物煎\\x（一五七） 方在新因二十。 \n治痘疹血气不足，随证加减用。 \n\\x六气煎\\x（一五八） 方在新因二一。 \n治痘疮气虚，痒 倒陷。 \n\\x九味异功煎\\x（一五九） 方在新因二二。 \n治痘疮虚陷，寒战切牙，虚寒诸证。 \n\\x柴归饮\\x（百六十） 方在新因十五。 \n治痘疮初起，托散妙剂。 \n\\x柴葛煎\\x（一六一） 方在新因十八。 \n治痘疮表里俱热，散毒养阴。 \n\\x疏邪散\\x（一六二） 方在新因十六。 \n治痘疮初起，表邪强实者。 \n\\x五积散\\x（一六三） 方在散阵三九。 \n温散寒邪。 \n\\x四顺清凉饮\\x（一六四） 方在攻阵二五。 \n治血脉壅热，大便秘结。 \n\\x凉血养荣煎\\x（一六五） 方在新因十七。 \n治痘疮血虚血热，地红热渴。 \n\\x搜毒煎\\x（一六六） 方在新因十九。 \n解痘疹热毒，紫黑干枯。 \n\\x犀角地黄汤\\x（一六七） 方在寒阵七九。 \n治痘疹血热诸证。 \n（仲景）\\x黄芩汤\\x（一六八） 方在寒阵百五。 \n治热利。 \n\\x透邪煎\\x（一六九） 方在新因二三。 \n治痘疹初热未出者，宜此苏表达邪。 \n\\x化斑渴\\x（百七十） 方在寒阵三。 \n治阳明热渴，化斑除烦。 \n\\x小柴胡汤\\x（一七一） 方在散阵十九。 \n散肝胆经表邪，往来寒热。 \n\\x益元散\\x（一七二） 方在寒阵百十二。 \n解烦热，止渴，利小水。 \n\\x四苓散\\x（一七三） 方在和阵一八七。 \n利小水，去湿滞。 \n\\x导赤散\\x（一七四） 方在寒阵一二二。 \n降心火及小肠热证。 \n\n\n\n<目录>卷之六十四春集·外科钤古方\n\n<篇名>外科\n\n属性：\\x仙方活命饮\\x（一）治一切疮疡，不成脓者内消，已成脓者即溃，此止痛消毒之圣药也。 \n穿山甲（蛤粉炒黄） 白芷 防风 天花粉 赤芍药 归尾 乳香 没药 贝母 皂刺 \n甘草（各二钱） 金银花 陈皮（各三钱） \n酒一碗，煎数沸。温服。 \n\\x托里消毒散\\x（二）治疮疽元气虚弱，或行攻伐不能溃散，服之未成即消，已成即溃， \n腐肉即去，新肉即生。若腐肉既溃而新肉不能收敛，属气虚者，四君子汤为主；属血虚者， \n四物汤为主；气血俱虚者，十全大补汤为主，并忌寒凉消毒之剂。 \n人参（随证增减） 黄 （盐水拌炒） 当归 川芎 芍药（炒） 白术（炒） 茯苓（各一钱） \n金银花 白芷（各七分） 甘草 连翘（各五分） \n上水煎服。陈氏托里消毒散内多陈皮。方在痘疮。 \n\\x秘方托里散\\x（三）治一切疮毒，始终常服，不致内陷。 \n栝蒌（大者一个，杵） 当归（酒拌） 黄 （盐水炒） 白芍药 甘草（各一两半） \n熟地 天花粉 金银花 皂刺（炒，各一两） \n上每用药五两，以无灰酒五茶钟，入瓷器内，浓纸封口，再用油纸重封，置汤锅内盖煮， \n至药香取出分服，直至疮愈。立斋曰∶此方药品平易，消毒之功甚大，且不动脏腑，不伤血气， \n不问阴阳肿溃，屡用屡效，真仙方也。常治发背脑疽势盛者，更用隔蒜灸之。若脉沉实，大小 \n便秘者，先用疏通而后用此，其功甚捷。若火毒已退，不作脓，或不溃者，更宜托里；溃而不 \n敛，及脓清者，用峻补。 \n\\x神功托里散\\x（四）一名金银花散。治痈疽发背，肠痈乳痈，及一切肿毒，或 痛，憎寒壮热。 \n金银花 黄 当归 甘草（等分） \n上用酒水各一钟，煎至一钟。分病上下，食前食后服之，少顷，再服一剂， 敷息处。不 \n问老少虚实皆可服。若为末，酒调服尢妙。 \n\\x参 托里散\\x（五）治疮疡气血俱虚，不能起发，或腐溃不能收敛，及恶寒发热者。 \n人参（气虚多用之） 黄 （炒） 白术（炒） 当归 熟地 芍药（酒炒） 茯苓 陈皮（各一钱） \n上水煎服。 \n\\x参 内托散\\x（六）方在痘疹七。治痈疽脓毒不化，及溃后作痛。 \n\\x托里养营汤\\x（七）治瘰 流注，及一切痈疽不足之证，不作脓，或不溃，或溃后发热， \n或恶寒，肌肉消瘦，饮食不思，睡卧不宁，盗汗不止。 \n人参 黄 （炙） 当归（酒拌） 川芎 芍药（炒） 白术（炒，各一钱） 熟地（二钱） \n五味子（炒研） 麦冬 甘草（各二分） \n水二钟，姜三片，枣一枚，煎七分。食远服。 \n\\x托里黄 汤\\x（八）治痈疽气虚作渴甚效。 \n黄 （蜜炒，六钱） 甘草 天花粉（各一钱） \n水二钟，煎八分。频服之。加人参一钱亦可。若气血俱虚，脓血大泄而作渴，或兼发 \n热者，宜用托里养营汤。 \n\\x内补黄 汤\\x（九）治痈毒内虚，毒不起化，及溃后诸虚迭见。 \n黄 （炙） 麦冬（各一两） 人参 熟地 茯苓 甘草（炙，各七分） 白芍药 当归 \n川芎 远志 官桂（各五分） \n上每服一两，姜、枣、水煎服。 \n\\x托里当归汤\\x（十）治溃疡气血俱虚，或晡热内热，寒热往来，或妇人诸疮，经候不调， \n小便频数，大便不实等证， \n但疮疡气血虚而发热者，皆宜服之，久服亦收敛疮口。 \n人参 黄 当归 熟地 川芎 芍药（各一钱） 柴胡 甘草（各五分） \n上水煎服。 \n\\x托里健中汤\\x（十二）治疮疡元气素虚，或因凉药伤胃，饮食少思，或作呕泻等证。 \n人参 白术 茯苓（各二钱） 半夏 炮姜（各一钱） 黄 （一钱半） 炙甘草（五分） 肉桂（三分） \n上姜、枣、水煎服。 \n\\x托里温中汤\\x（十二） 治疮疡脓溃，元气虚寒，或因克伐，胃气脱陷，肠鸣腹痛， \n大便溏泄，神思昏愦，此寒变内陷，缓则不治。 \n附子（炮，去皮脐，二钱） 干姜（炒，三钱） 益志 丁香 羌活 沉香 木香 茴香 \n陈皮（各一钱） 炙甘草（二钱） \n上姜、水煎服。 \n\\x托里益中汤\\x（十三） 治中气虚弱，饮食少思，或疮不消散，或溃而不敛。 \n人参 白术 茯苓 炮姜 陈皮 半夏（各一钱） 木香 炙甘草（各五分） \n上姜、枣、水煎服。 \n\\x托里温经汤\\x（十四）治疮疡寒覆皮毛，郁遏经络，不得伸越，热伏营中，聚结赤肿作 \n痛，恶寒发热，或痛引肢体。若头面肿痛 甚，仍宜砭之。 \n麻黄 升麻 防风 干葛 白芷 人参 当归 芍药 甘草 苍术（各一钱） \n上水二钟，煎一钟服。卧暖处，得汗乃散。或加柴胡。 \n\\x托里益黄汤\\x（十五）治脾土虚寒，水反侮土，以致饮食少思，或呕吐泄泻等证。 \n人参 白术 茯苓 陈皮 半夏（各一钱） 炮姜 丁香 炙甘草（各五分） \n上姜、枣水煎服。 \n\\x托里清中汤\\x（十六）治脾胃虚弱，痰气不清，饮食少思等证。 \n人参 白术 茯苓 陈皮（各一钱） 半夏（八分） 桔梗（七分） 甘草（五分） \n上姜、枣、水煎服。 \n\\x托里抑青汤\\x（十七）治肝木侮脾，脾土虚弱，以致饮食少思，或胸膈不利等证。 \n人参 白术 茯苓 半夏 陈皮（各一钱） 芍药 柴胡 甘草（各五分） \n上姜、枣、水煎服。 \n\\x托里营卫汤\\x（十八）治疮疡外无 肿，内便调和，乃邪在经铬也，宜用此药。 \n人参 黄 当归 甘草（炙） 红花 柴胡 连翘 苍术（米泔浸，炒） 羌活 \n防风 黄芩（各一钱） 桂枝（七分） \n上酒、水煎服。 \n\\x托里越鞠汤\\x（十九）治六郁所伤，脾胄虚弱，饮食少思等证。 \n人参 白术（各二钱） 陈皮 半夏（各一钱） 山栀 川芎 香附 苍术（各七分） \n炙甘草（五分） \n上姜、枣、水煎服。 \n\\x定痛托里散\\x（二十）治疮疡血虚疼痛之圣药也。 \n粟壳（去蒂，炒，二钱） 当归（酒拌） 白芍药（炒） 川芎（各一钱半） 乳香 \n没药 肉桂（各一钱） \n上姜、枣、水煎服。 \n\\x内托复煎散\\x（二一） 治疮疡 肿在外，其脉多浮，邪胜必侵于内，宜用此托之。 \n人参 白术（炒） 当归 黄 （盐水炒） 芍药（炒） 茯苓 甘草（炙） 地骨皮 \n肉桂 防己（酒炒） 黄芩（各一钱） 防风（二钱） \n上先以苍术一升，水五升煎，去术入药，再煎至二升。终日饮之。 \n\\x内托羌活汤\\x（二二）治臀痈坚硬肿痛，两尺脉紧无力。 \n羌活 黄柏（各一钱） 防风 当归尾 本 肉桂（各一钱） 连翘 苍术（米泔浸，炒） \n陈皮（各五分） 黄 （盐水炒，一钱半） \n上水、酒各一钟，煎八分。食前服。 \n\\x内塞散\\x（二三） 治阴虚阳邪凑袭患肿，或溃而不敛，或风寒袭于患处，血气不能 \n营运，久不能愈，遂成漏证。 \n附子（童便浸，炮） 肉桂（去皮） 赤小豆 甘草 炙黄 （盐水炒） 当归（酒拌） \n茯苓 白芷 桔梗（炒） 川芎 人参 远志（去骨） 浓朴（制，各一两） 防风（四钱） \n上为末。每服二钱，空心温酒下。或酒糊丸，盐汤下。或炼蜜为丸亦可。 \n\\x冲和汤\\x（二四） 治疮属半阴半阳，似溃非溃，似肿非肿，此因元气虚弱，失于补 \n托所致。 \n人参 陈皮（各二钱） 黄 白术 当归 白芷（各一钱半） 茯苓 川芎 皂角刺（炒） \n乳香 没药 金银花 甘草节（各一钱） \n上水、酒各半煎服。 \n\\x神效酒煎散\\x（二五） 治一切疮疡，能托毒散毒，其效如神。 \n人参 没药（另研） 当归尾（各一两） 甘草（三钱） 栝蒌（一个，半生半炒） \n上以酒三碗，煎二碗，分四服。或以为末，酒糊丸，桐子大。每服五十丸，用酒下。 \n善消毒活血。 \n\\x人参黄 汤\\x（二六）治溃疡饮食少思，无睡发热。 \n人参 白术 苍术 麦冬 陈皮 当归 升麻（各五分） 黄 （一钱） 黄柏（炒，四分） \n上水煎服。 \n\\x黄 人参汤\\x（二七） 治溃疡虚热，无睡少食，或秽气所触作痛。 \n黄 （盐水炒，二钱） 人参 白术 苍术（米泔浸，炒） 当归（酒拌） 麦门冬 \n五味子（炒，敲，各一钱） 甘草（炙） 升麻 神曲（炒） 陈皮（各五分） 黄柏（酒炒，三分） \n水两钟，姜三片，枣一枚，煎服。 \n\\x黄 建中汤\\x（二八） 内托痈疽诸毒。 \n黄 （蜜炙） 肉桂（各三两） 甘草（炙，二两） 白芍药（六两） \n上每服一两，姜、枣、水煎服。 \n\\x参术补脾汤\\x（二九） 治肺疽脾气亏损，久咳吐脓，或中满不食，必服此药，补脾土以 \n生肺金，否则不治。 \n人参 白术（各二钱） 黄 （二钱半） 茯苓 当归 陈皮（各一钱） 麦冬（七分） \n北五味（四分） 桔梗（六分） 炙甘草（五分） \n上姜、枣、水煎服。 \n\\x参 补肺汤\\x（三十）治肺证咳喘短气，或肾水不足，虚火上炎，痰涎壅盛，或吐脓血， \n发热作渴，小便短涩。 \n人参 黄 白术 当归 陈皮 茯苓（各一钱） 山药 山茱萸（各二钱） 五味子 \n炙甘草（各五分） 熟地黄（一钱半） 麦门冬 牡丹皮（各八分） \n上姜、枣、水煎服。 \n\\x益气养营汤\\x（三一）治怀抱抑郁，或气血损伤，四肢颈项等处患肿，不问软硬，赤白 \n肿痛，或日晡发热，或溃而不敛。 \n人参 黄 （盐水炒） 当归 川芎 熟地 芍药（炒） 贝母 香附 茯苓 陈皮（各一钱） \n白术（二钱） 柴胡（六分） 甘草 桔梗（各五分） \n上姜、水煎服。口干加五味子、麦门冬；往来寒热加软柴胡、地骨皮；脓清加人参、黄 ； \n脓多加川芎、当归；脓不止加人参、黄 、当归；肌肉迟生加白蔹、官桂。 \n\\x补阴八珍汤\\x（三二）治瘰 等疮，足三阴虚者。 \n人参 白术 茯苓 甘草 当归 川芎 熟地 芍药 黄柏（酒炒） 知母（酒炒，各七分） \n上水煎服。 \n\\x参术姜附汤\\x（三三） 治疮疡真阳亏损，或误行汗下，或脓血出多，失于补托，以致 \n上气喘急，自汗盗汗，气短头 \n晕泄泻。 \n人参 附子（炮，去皮脐，各一两） 干姜 白术（各五钱） \n上作二剂，水煎服。 \n\\x附子理中汤\\x（三四） 治疮疡脾胃虚寒，或误行攻伐，手足厥冷，饮食不入，或肠鸣 \n腹痛，呕逆吐泻。 \n附子 人参 白茯苓 白芍药（各三钱） 白术（四钱） \n上水煎服。 \n\\x六物附子汤\\x（三五）治四气流注于足太阴经，骨节烦疼，四肢拘急，自汗短气，小便 \n不利，或手足浮肿。 \n附子（制） 防己 桂枝（各四钱） 炙甘草（二钱） 白术 茯苓（各三钱） \n上作二剂，水一钟半，姜三片，煎一钟。食远服。 \n\\x附子八物汤\\x（三六）治疮疡阳气脱陷，呕吐畏寒，泄泻厥逆。 \n附子（炮） 干姜（炮） 芍药（炒） 人参 炙甘草 茯苓（各一钱） 肉桂（一钱） \n白术（二钱） \n上水煎，食远服。 \n\\x回阳汤\\x（三七）治脾肾虚寒，疮属纯阴，或药损元气，不肿痛，不腐溃，或腹痛泄泻， \n呕吐厥逆，及阳气脱陷等证。 \n人参 白术 黄 （各三钱） 干姜（炮） 附子（炮） 甘草（炙） 陈皮 当归（各二钱） \n柴胡 升麻（各五分） \n上酒、水煎服。如不应，倍加姜、附。 \n（薛氏）\\x加减八味丸\\x（三八）治疮疡痊后及将痊，口干渴甚，或舌上生黄，或未患先渴。 \n此皆肾水枯竭，不能上 \n润，以致心火上炎，水火不能相济，故烦躁作渴，小便频数，或白浊阴痿，饮食不多，肌肤渐消， \n或腿肿脚先瘦。服此以降心火，滋肾水，则诸证顿止。及治口舌生疮不绝。 \n熟地（八两，酒蒸捣膏） 山茱萸（酒浸，杵膏） 山药（各四两） 泽泻（蒸，焙） \n白茯苓 牡丹皮（各三两） 桂心（一两） 北五味（四两半，炒） \n上为细末，入二膏加炼蜜少许丸，桐子大。每服六七十丸，五更初、言语前，或空心用盐 \n汤送下。此即陈氏加减八味丸也，方在补阵一二三。 \n\\x加味地黄丸\\x（三九）治肝肾阴虚，疮毒，或耳内痒痛出水，或眼昏，痰气喘嗽， \n或作渴发热，小便赤涩等证。 \n熟地 山药 山茱萸 白茯苓 泽泻 牡丹皮 柴胡 北五味（各为末，等分） \n上将地黄掐碎，酒拌湿蒸烂杵膏，入诸药和匀，加炼蜜为丸，桐子大。每服百丸，空心白 \n汤送下。如不应，用加减八味丸。 \n\\x当归川芎散\\x（四十）治手、足少阳经血虚疮证，或风热耳内痒痛，生疮出水，或头 \n目不情，寒热少食，或妇女经水不调，胸膈不利，胁腹痞痛。 \n当归 川芎 柴胡 白术 芍药（各一钱） 山栀（炒，一钱二分） 牡丹皮 茯苓（各八分） \n蔓荆子 甘草（各五分） \n上水煎服。 \n\\x加味败毒散\\x（四一） 治足二阳经热毒流于脚根， 赤肿痛，寒热如疟，自汗短气，大 \n小便不利，或无汗恶寒，表里邪实者宜之。 \n羌活 独活 前胡 柴胡 桔梗 人参 茯苓 枳壳 甘草 川芎 大黄 苍术（各一钱） \n水二钟，姜三片，煎服。 \n\\x九味羌活汤\\x（四二） 方在散阵四四。治疮疡风热郁遏， 肿作痛，或遍身作痛，或拘急 \n不利，及头痛恶寒脊强，脉浮紧。 \n\\x加味羌活汤\\x（四三） 即前汤加金银花、连翘，用解疮毒。 \n\\x白芷胃风汤\\x（四四） 治手、足阳明经气虚风热，面目麻木，或牙关紧急，眼目 动。 \n白芷 升麻（各二钱半） 葛根 苍术（米泔炒，各八分） 炙甘草 当归（各一钱半） \n草豆蔻 黄柏（炒） 柴胡 本 羌活 麻黄（去节，各四分） 蔓荆子 僵蚕（各三分） \n上水煎服。 \n\\x葛根牛蒡汤\\x（四五）治时毒肿痛，而便利调和者。 \n葛根 管仲 甘草 豆豉 牛蒡子（半生半炒，各二钱） \n上水煎服。 \n\\x犀角地黄汤\\x（四六） 治胃火血热妄行，吐衄或大便下血。 \n犀角（镑为末） 生地 牡丹皮 芍药（各一钱半） 黄芩（炒） 升麻（各一钱） \n上水煎熟，入犀角末服。 \n\\x犀角升麻汤\\x（四七）治时毒或风热，头面 痛，或咽喉不利，或鬓疽 腮等证。 \n犀角（镑） 升麻 防风 羌活（各钱半） 白芷 白附子 黄芩（各一钱） 甘草（六分） \n上水煎服，入犀角末服。 \n\\x玄参升麻汤\\x（四八）治心脾壅热，舌上生疮，或木舌重舌，或连颊两边肿痛，或咽痛发 \n斑并治之。 \n元参 升麻 赤芍药 犀角（镑末） 桔梗（炒） 管仲 黄芩（各一钱） 甘草（五分） \n水二钟，煎八分，入犀角末。食后服。 \n\\x升麻黄连汤\\x（四九）治胃经热毒，腮肿作痛，或发寒热。 \n升麻 川芎 当归（各一钱半） 连翘 黄连 牛蒡子 白芷（各一钱） \n上水煎服。若肿连太阳，加羌活，连耳后，加山栀、柴胡。 \n（《秘传》）\\x连翘汤\\x（五十）治痈疽时毒肿痛 肿。 \n连翘 升麻 朴硝（各一两） 玄参 芍药 白蔹 防风 射干（各三钱） 大黄（一两二钱） \n甘草（炙，五钱） 杏仁（八十个，去皮尖，面炒黄，另研） \n上每服五七钱，水煎服。下恶物后，服内托之类。 \n\\x五香连翘汤\\x（五一） 治脑疽、痈疽、时毒、邪气郁滞不行者。 \n乳香 木香 沉香 丁香 香附 黄 射干 连翘 升麻 木通 独活 桑寄生 \n甘草（各一钱） \n上水煎服。 \n\\x复元遥气散\\x（五二） 治乳痈、便毒肿痛，及一切气滞肿毒，或打扑损伤，闪跌作痛， \n及疝气尤效。 \n木香 舶上茴香（炒） 青皮 陈皮 白芷 甘草 贝母（去心） 穿山甲（炙） \n漏芦（等分） 一方有玄胡索、白牵牛（炒用）无白芷、漏芦。 \n上为末。每服二三钱，温酒调下。 \n\\x当归散\\x（五三） 通经络，行血滞。 \n当归 穿山甲（灰炒） 蒲黄（炒，各半两） 辰砂（一钱） 麝香（少许） \n上为末。每服三钱，热酒调下，如不饮酒，薄荷醋汤亦可。 \n\\x方脉流气饮\\x（五四）治瘰 流注，郁结肿块，或走注疼痛，或心胸痞闷，咽塞不利， \n胁腹膨胀，呕吐不食，上气喘急，咳嗽痰盛，面目四肢浮肿，大小便秘。 \n当归 川芎 芍药（炒） 茯苓 黄 （炙） 炙甘草 紫苏 青皮 乌药 半夏（制） \n桔梗（炒） 枳实（麸炒） 防风 陈皮（各一钱） 木香 大腹皮 枳壳（麸炒） 槟榔（各五分） \n水二钟，姜三片，枣一枚，煎八分。食远服。 \n\\x疮科流气饮\\x（五五） 治流注，及一切恚怒气结肿痛，或胸膈痞闷，或风寒湿毒搏于经 \n铬，致成肿块，肉色不变或漫肿木闷无头。 \n人参 当归（酒拌） 黄 （盐水炒） 芍药 官桂 浓朴（制） 甘草 防风 紫苏 \n枳壳 乌药 桔梗（炒，各七分） 槟榔 木香 川芎 白芷（各五分） \n上水煎服。 \n（陈氏）\\x独圣散\\x（五六） 凡患疮疡，皆因气血凝滞，宜服香剂，盖香能行气通血也。 \n如疮初作，便宜以此入茶饮之。 \n香附子姜汁浸一宿，焙干研末。 \n上无时，以白汤调服二钱。溃后以《局方》小乌沉汤为尤妙。 \n\\x乳香定痛丸\\x（五七） 治疮毒损伤，血凝气滞，壅肿拘挛，筋骨疼痛。 \n乳香 没药（各另研） 羌活 五灵脂 独活（各三钱） 川芎 当归 真绿豆粉 肉桂 \n白芷 白胶香（各半两） \n上为末，炼蜜丸，如弹子大。每服一丸，细嚼薄荷汤或酒送下。手足损痛不能举动，加草 \n乌五钱，盐汤送下。 \n\\x消毒散\\x（五八） 治乳痈吹乳并便毒，如憎寒壮热，或头痛者，宜先服人参败毒一 \n二剂，方可服此药；如无前证，即服此药三二剂；或肿不消，宜服托里散。 \n金银花 青皮 天花粉 柴胡 僵蚕（炒） 贝母 当归（酒拌） 白芷（各二钱） \n水二钟，煎一钟。食远服。如治便毒，加大黄一二钱煨用，空心服。 \n\\x清热消毒散\\x（五九） 治一切痈疽阳证肿痛，发热作渴。 \n黄连（炒） 山栀（炒） 连翘 当归 甘草（各一钱） 川芎 芍药 生地（各一钱半） \n金银花（二钱） \n上水煎服。 \n（东垣）\\x黄连消毒散\\x（六十）治脑疽背疽， 肿疼痛，或麻木。 \n黄连（炒） 羌活（各一分） 黄芩 黄柏 桔梗 本 防己（各五分） 归尾 连翘 \n防风 独活 知母（炒） 生地（各四分） 人参 甘草（各三分） 黄 苏木 陈皮 泽泻（各二分） \n上水煎服。 \n\\x连翘消毒散\\x（六一） 治痈疽实热诸证。亦名清凉饮。亦即《局方》凉膈散。 \n连翘（一两） 栀子 大黄 薄荷 黄芩（各五钱） 甘草（一两半） 朴硝（二钱半） \n上每服一两，水煎温服。 \n\\x加味解毒汤\\x（六二） 治痈疽实热，大痛不止。 \n黄 （盐水炒） 黄连（炒） 黄芩（炒） 黄柏（炒） 连翘 当归（酒拌，各七分） \n甘草（炙） 白芍药 栀子（炒，各一钱） \n水二钟，煎服，痛即止。 \n\\x解毒防风汤\\x（六三） 治斑疹或痒或痛。 \n防风（一钱） 黄 芍药 地骨皮 枳壳（炒） 荆芥（各二钱） \n水煎。徐徐服。 \n（陈氏）\\x解毒防风汤\\x（六四）方在痘疹五六。治痘疹毒瓦斯炽盛。 \n\\x散肿溃坚汤\\x（六五）治瘰 坚硬，气血无亏，宜用之。 \n柴胡 黄芩（各四分） 白芍药（炒） 升麻 连翘 黄柏（酒炒） 蓬术 三棱（酒拌微炒） \n干葛 归尾（各三分） 知母（酒炒） 龙胆草（酒炒） 天花粉 桔梗 昆布（各五分） \n炙甘草（二分） \n上水煎服。 \n\\x栝蒌托里散\\x（六六） 治疮疡毒盛者，未成则易消，已成则易溃，既溃则生肌。 \n黄栝蒌（一个，杵碎） 忍冬藤 乳香（各一两） 苏木（五钱） 没药（三钱） 甘草（二钱） \n上用酒三碗，煎二碗。空心、日午、临睡分三服。或以此为末，酒糊丸，弹子大， \n朱砂为衣。细嚼用当归 \n酒送下，治打扑损伤尤妙。 \n\\x万金散\\x（六七）一名内托散。治痈疽已溃未溃者，有消毒破血之功。 \n栝蒌（一个，杵碎） 没药（一钱，研） 大甘草节（二钱） \n上用酒二碗，煎一碗，去 ，后入没药服。 \n\\x制甘草汤\\x（六八）治悬痈不拘肿溃，亦治痈疽。 \n用大甘草一两，切三寸长，用涧水一碗浸透，以慢火炙干，仍投前水浸透，再炙至水干 \n为度，却锉钿，用无灰酒二钟煎七分。空心服。尝有人患此已破，服两剂疮即合。一、国 \n老膏方∶用大甘草二斤，以河水浸取浆汁，去 ，用银石器熬成膏，瓷罐收贮。每服一二匙， \n酒调服，或水亦可，尤解丹药之毒。一方治痈疽，用生甘草为末，酒调服二钱，连进数服 \n自消。 \n\\x梅花饮子\\x（六九）痈疽初起，服之可防毒瓦斯内攻。 \n川芎 干葛 天花粉 黄 乌梅 甘草 苏木（各一两） 忍冬藤（四两） \n上作四剂，水煎服。 \n\\x牛胶饮\\x（七十）治痈疽使毒不内攻，不传恶证，有益无损。 \n牛皮胶（广中明者，四两） \n上用酒一碗，重汤煮化，加酒服至醉，不能饮者加白汤。 \n\\x明胶饮子\\x（七一）治一切痈疽疖毒。 \n明广胶（蛤粉炒珠） 粉甘草（各一两） 橘红（五钱） \n上作二剂，水煎服。 \n\\x护心散\\x（七二） 解金石砒硫发疽之毒。 \n绿豆末（一两） 明乳香（半两，研细） \n上以生甘草煎汤调。时时与呷，务使药气常在膈间。 \n\\x清心内固金粉散\\x（七三） 一名金花散。解毒清心，流行气血，散滞清火，凡 肿热痛， \n饮食如常者，大宜用之。 \n绿豆（四两，研末） 朱砂（另研） 人参 甘草 白茯苓（各三钱） 朴硝（另研） \n白豆蔻（各五分） 麝香（另研） 雄黄（各一钱） 冰片（五分） \n上为末。每服一二钱，蜜汤调下。 \n\\x蜡矾丸\\x（九四） 一名黄矾丸。治金石发疽，一切痈疽，托里止疼痛，护脏，神妙，不 \n问老少皆可服之。 \n黄蜡 一两，黄色佳者，溶开，离火入矾末。一方止用七钱。 \n白矾一两，明亮净者，研末。 \n上二味和匀，众手急丸，桐子大。每服二三十丸，渐加至四五十丸，熟水或盐汤送下， \n日进二三服，服至三四两之上，愈见其功矣。如服金石发疽，别用白矾末一两，作三五服， \n温酒调下尤效。有人遍身生疮，状如蛇头，名曰蛇头疮，尤宜服之。治蛇蝎毒虫咬伤，熔化热 \n涂伤处，痛止毒出，仍服两许。此方不惟止痛生肌而已，其护膜止泻，消毒化脓，及内痈排脓 \n托里之功甚大。 \n\\x千金化毒丸\\x（七五）治诸恶毒。 \n用白矾三钱糊丸。以葱头七茎煎汤送下，则肿痛俱退。再用仙方活命饮二剂以去其余毒。 \n此本方原用矾末，以葱汤调服，因汤难服，故易为丸。一方主治疮疽，不问肿溃，先用此药 \n二三服，后用消毒药，甚效。常治萏荛之人，用此即退，不用托里药亦愈。若金石毒药发疽者 \n尤效，盖矾能解金石之毒也。一方用矾末五钱，朱砂五分，热酒下亦效。此药托里固内止泻， \n解毒排脓，不动脏腑，不伤气血，有益无损，其药易得，其功甚大，偏僻之处不可不知此方。 \n或虫尤所伤，溶化热涂患处，更以热酒调末服，皆效。 \n\\x五福化毒丹\\x（七六） 治咽喉牙口疮毒肿痛，并小儿一切热毒疮疖，惊惕烦躁，口舌 \n生疮，夜卧不宁等证。 \n玄参 桔梗（各二两半） 茯苓（三两半） 人参 牙硝 青黛（各一两） 甘草（七钱半） \n麝香（少许） 金箔（二十片） \n上为末，炼蜜丸，芡实大。每服一丸，薄荷汤化下。若痘毒上攻，口齿生疮，以生地 \n黄汁化服，及用鸡翎扫敷患处。 \n\\x夺命丹\\x（七七）治疔疮发背等证，或麻木，或呕吐，重者昏愦。此药服之，不起 \n者即起，不痛者即痛，痛甚者即止，昏愦者即苏，呕吐者即解，未成者即消，已成者即溃， \n有夺命之功，乃恶证中之至宝也。 \n蟾酥（酒化） 轻粉 麝香（各五分） 枯矾 寒水石（ ） 铜绿 乳香 没药（各一钱） \n朱砂（三钱） 蜗牛（二十个，另研，无亦可） \n上为末，用蜗牛或酒糊捣丸，绿豆大。每服二三丸。温酒、葱汤下。或用葱白三四寸， \n病者自嚼烂吐于手心，包药在内，用热酒和葱送下，如人行五七里，汗出为效。重者再服 \n一二丸，或外用一丸入疮孔内，以膏药贴之。 \n\\x飞龙夺命丹\\x（七八） 治一切疔疮毒疮，出汗则愈，神效。 \n干蟾酥（二钱，乳化） 没药 硼砂 寒水石（ ） 雄黄（各三钱） 乳香 朱砂 \n血竭（嚼成饼者真） 枯矾（各一钱） 轻粉 冰片（各五分） 蜈蚣（一条去头，酒浸焙干） \n蜗牛（四十九个，研为膏，或无亦可） \n上各研为细末，取蜗牛、蟾酥研匀，入诸末熟杵丸，绿豆大，朱砂为衣。每服四五丸， \n嚼葱白一口，吐在手心，将药包葱内，用温酒吞下，须臾汗出，或少吐泻，毒即解。 \n立斋曰∶前回生丹乃 悍攻毒之剂也，盖无经不至，无气不动者。后夺命丹尚缓。若食 \n一切禽畜毒物，及疮脉浮紧细数，毒蓄在内，并恶毒证，凡宜汗吐者，当用前丹有神效。 \n若老弱之人，或疮毒稍轻者，宜用后丹，或更以隔蒜灸之为良。 \n\\x回生丹\\x（七九）李颐颜先生口授，非泛常之药，万宝之秘，专治一切疔毒，并有神效。 \n金脚信 明 砂 明乳香 半夏 上红丹（各五分） 巴豆肉（不去油） 明雄黄 大南星 \n南硼砂（各一钱） 大斑蝥（十五个，去头足翅） \n上为细末，旋取蟾酥和丸，麻子大，朱砂为衣。每服十五丸，好酒下，看疮生上下，食 \n前后服，能饮者至醉为佳。凡肿毒失治，毒瓦斯入腹，用此药能起死回生，服药后吐泻俱作乃苏。 \n\\x通气散\\x（八十）治时毒肿甚，咽喉不利，取嚏以泄其毒。 \n玄参（一钱半） 牙皂 川芎（各一钱） 藜芦（五分，一方无此） 羊踯躅花（二钱半） \n上为末，用纸捻蘸少许入鼻内，取嚏为度。按∶此方止用皂角、川芎、北细辛三味 \n即可，亦不必藜芦踯躅之毒品也。总不若通关散为妙，方在因阵九十八。 \n\\x栀子仁汤\\x（八一）方在寒阵十九。治发热狂躁，咽喉肿痛。 \n\\x六味栀子仁汤\\x（八二） 治时毒肿痛，大便秘结，脉沉数。 \n山栀（炒） 枳壳 大黄（煨） 升麻 牛蒡子（炒） 郁金（等分） \n上水煎服。或为细末，每服三钱，蜜水调下。 \n\\x清肝益营汤\\x（八三） 治肝、胆、小肠经风热血燥，筋挛结核，或耳项胸乳胁肋作痛，并 \n一切肝火之证。 \n山栀 当归 木瓜（不犯铁） 茯苓（各一钱） 柴胡 芍药（炒） 川芎（各七分） \n龙胆草（八分） 白术（二钱） 熟地（一钱半） 炙甘草（五分） \n上姜、水煎服。 \n\\x清心汤\\x（八四） 治疮疡肿痛，发热饮冷，脉沉实，睡语不宁。上方即防风通圣散，每 \n料加黄连五钱，每剂用一两，水煎服。方在攻阵十六。 \n\\x济阴汤\\x（八五）治疡毒纯阳，肿痛发热。 \n连翘（二钱） 山栀（炒） 黄芩（炒） 黄连（炒） 甘草（各一钱） 芍药（一钱半） 牡丹皮（一钱二分） \n金银花（三钱） \n水煎服。大便若秘，量加大黄。 \n\\x地骨皮散\\x（八六） 治疮疡气虚内热，烦渴不宁。 \n人参 黄 生地黄 地骨皮 柴胡（各一钱半） 白茯苓 石膏（ ） 知母（各一钱） \n水、姜、煎服。 \n\\x一味苦参丸\\x（八七）治一切痈疽毒疮， 肿作痛，或烦躁。 \n苦参不拘多少为末。 \n上用水糊丸，桐子大。每服二三钱，温酒下。 \n（陈氏）\\x苦参丸\\x（八八）治遍身瘙痒，癣疥疮疡。 \n苦参（四两） 玄参 黄连 大黄 独活 枳壳 防风（各二两） 黄芩 栀子 菊花（各一两） \n上为末，炼蜜丸，桐子大。食后茶酒任下三四十丸，日三服。 \n\\x五利大黄汤\\x（八九）治时毒 肿赤痛，烦渴便秘，脉实而数。 \n大黄（煨） 黄芩 升麻（各二钱） 芒硝 栀子（各一钱半） \n水一钟半，煎六分。空心热服。 \n\\x清凉饮\\x（九十） 治痈疡热毒炽盛，大便秘结。此即前连翘消毒散。 \n连翘（一两） 大黄 山栀子 薄叶 黄芩（各五钱） 甘草（一两半） 朴硝（二钱半） \n上每服一两，水煎服。 \n\\x宣毒散\\x（九一）治一切痈毒，其功不可尽述。 \n大黄（煨） 白芷（各五钱） \n水二钟，煎一钟。食前服。 \n立斋曰∶此方乃宣通攻毒之剂，若脉沉实，便秘者，毒在脏也，宜服之，其功甚大。若 \n脏腑调和，脉不实者不可用。《医林集要》方用大黄一斤，白芷六两，为末，每服三钱， \n热酒调下，更用茶清调搽患处，名曰万金散。盖因其功而珍之也。或用水跌为丸，以便于服亦 \n可。吴江申佥宪兄患背疽坚硬，脉沉实，乃毒在内，用一服，大小便下污物，再服而消。 \n恐患者忽此二药，故以此尝验者告之。 \n\\x拔毒散\\x（九二） 治一切痈疽肿毒，其功不可尽述。 \n乳香 没药 当归 穿山甲（炮） 木鳖子 连翘（各一钱） 甘草（炙，五分） 栝蒌仁（八分） \n牙皂（炒） 贝母（各七分） 忍冬藤（二钱） 大黄（生熟各一钱半） \n上水、酒各一钟，煎一钟。食前服。此方攻毒止痛化脓之良剂也，屡用屡验。若脓成或已溃 \n者，大黄可不用，恐泄其真气，则脓者难溃，溃者难敛也。亦有脓虽溃，脉仍洪数，或沉实， \n喜冷者，火邪尚在，又所宜用。 \n\\x内疏黄连汤\\x（九三） 治疮疡发热而呕，大便秘结，脉洪而实。 \n黄连 芍药 当归 槟榔 木香 黄芩 栀子 薄荷 桔梗 甘草（各一钱） 连翘 \n大黄（各一钱半） \n姜、水煎，仍量虚实治之。 \n\\x桃仁汤\\x（九四）逐瘀血。 \n桃仁 苏木（各一两） 生地黄（五钱） 虻虫（去足翅，炒） 水蛭（炒，各三十个） \n上每服三钱，水一盏，煎六分。空心服。 \n\\x漏芦汤\\x（九五） 治脑疽、痈疽毒盛实者。 \n漏芦 黄 甘草 连翘 沉香（各五钱） 大黄（一两，微炒） \n上每服四五钱，姜、枣、水煎服。 \n\\x千金漏芦汤\\x（九六） 治痈疽发背，丹疹时行热毒，赤肿 痛。 \n漏芦 黄芩 白蔹 连翘 枳壳（麸炒） 升麻 粉草 麻黄（去节） 大黄（湿纸裹煨） \n朴硝（各一两） \n上每服五六钱，姜、水煎，去 。空心服。下恶物为妙。 \n\\x漏芦升麻汤\\x（九七）治时毒头面红肿，咽嗌堵塞，水药不下，若脏腑素有积热，发 \n为肿毒疙瘩，一切红肿恶毒。 \n漏芦（二钱） 升麻（一钱半） 黄芩（酒洗） 生甘草 玄参 牛蒡子（炒研） 苦梗 \n连翘（各一钱） 蓝叶（如无，用青黛） 大黄（酒浸，量轻重用之） \n水煎服。大利之结者，加芒硝。 \n\\x润肠丸\\x（九八）治脾胃伏火，大肠干燥，或风热血结，宜用此丸通之。若结在直肠， \n宜用猪胆汁导之。盖肾主五液，开窍于二阴，若津液滋润，则大便通调，若津液不足，脾气 \n亏损，必当培补，乃忌此药。 \n桃仁（去皮尖） 麻子仁（各一两） 羌活 归尾 大黄（煨） 皂刺 秦艽（各五钱） \n上各另研为末，炼蜜或猪胆汁丸桐子大。每服三四十丸，白汤下。若用猪胆汁导而粪 \n不结燥者，须急补元气。 \n\\x没药丸\\x（九九）善逐滞血。 \n当归（一两） 桂心 芍药（各半两） 桃仁（去皮尖，研） 没药（各三钱） 虻虫（去足翅） \n水蛭（炒，各三十个） \n上为末，醋糊丸，桐子大。每服三五丸，空心醋汤下。 \n\\x当归丸\\x（百）行血，利水，通大便。 \n当归（半两） 大黄 桂心（各三钱） 赤芍药 葶苈（各二钱） 人参 甘遂（面裹煨，半钱） \n炼蜜丸，如弹子大。空心米饮化下一丸。 \n\\x破棺丹\\x（百一）治疮疡热极汗多，大渴便秘，谵语发狂。 \n大黄（二两半，半生半熟） 芒硝 甘草（各二两） \n上为末，炼蜜丸，弹子大。每服一丸，童便、酒化下，白汤亦可。 \n\\x忍冬酒\\x（百二） 解诸痈毒。 \n忍冬藤（鲜者四五两，若干者，止用一两，捣） 大甘草节（一两，生用） \n二味入砂锅内，以水二钟，煎至一钟，再入无灰酒一钟，又煎数沸，去 ，分三服，病 \n重者昼夜两剂，至大小便通利为度，另用忍冬藤研烂，入酒少许罨患处。 \n\\x金银花酒\\x（百三） 治一切痈疽发背，疔疮喉痹等证。 \n用金银花藤叶捣烂，取汁半钟，和热酒半钟温服，甚者不过三五服，可保无虞。 \n\\x槐花酒\\x（百四） 治痈疡热毒最妙。 \n用槐花四五两炒微黄，乘热入酒二钟，煎十余滚，去 热服，未成者二三服，已成者一二 \n服，但察其有热毒未清者皆可用。槐花治湿热之功最为神速，惟胃寒者不宜服。大抵肿毒非 \n用蒜炙及槐花酒先去其势，虽用托里诸药，其效未必甚速。 \n\\x蒲公英酒\\x（百五）治乳痈吹乳，不问已成未成皆可用。 \n用蒲公英一握，捣烂，入酒半钟，取酒温服， 贴患处，甚者不过三五服即愈。 \n\\x远志酒\\x（百六） 能托散诸毒，治女人乳痈尤效。 \n远志（不拘多少，用米泔浸洗，捶去心） \n上为末。每服三钱，用好酒一钟调，迟少顷，澄清饮之，以滓敷患处。 \n\\x牛膝酒\\x（百七）治杨梅风毒，腰痛。 \n牛膝 川芎 羌活 五加皮 杜仲 甘草 地骨皮 薏仁（各一两） 生地黄（十两） \n海桐皮（二两） \n上 咀，用帛裹入无灰酒浸二七日，夏月三五月。每服一杯，日三五次。 \n\\x消瘿酒\\x（百八） \n昆布（三钱） 海藻（五钱） 沉香 雄黄（各一钱，研末） 海螵蛸（二钱） \n上为咀，用好酒一升汤煮。任意每服一二钟，或浸十余日亦可饮。 \n\\x桑枝煎\\x（百九）大治口渴。 \n取嫩桑枝细切一升炒，以水三升，煎一升。日服三五剂，更多尤妙。《抱朴子》云∶疗风 \n痹干燥，臂痛香港脚，四肢拘挛，上气眩晕。久服补肺消食，利小便，轻身，耳目聪明，令人光 \n泽，其功不能尽述。 \n\\x神仙截法\\x（百十）治痈疽发背、一切恶疮，预服则毒瓦斯不入内。 \n真麻油 一斤，银器内熬十数沸，候冷。 \n上用酒两碗，入油五盏。通口热服，一日用尽，缓则数日服之。吴安世云∶吾家三世用之， \n无有不效。又闻猎者云∶凡中药箭，急饮麻油，药毒即消，屡用甚 。按∶上方凡大便秘 \n结而毒蓄于内者，最宜用之以疏通其毒。若阴毒及大便不实者，乃非所宜。 \n\\x砭法\\x（百十一）治丹毒疔疮红丝走散，或时毒瘀血壅盛。用细瓷器击碎，取有锋 者一 \n块，以箸一根，劈开头尖夹之，用线缚定，两手指轻撮筋尾，令瓷 正对患处，约悬寸许， \n再另用箸一根频击箸头，令毒血遇刺皆出，毒自减退。若毒瓦斯入腹膨胀者难治。 \n\\x刺少商穴\\x（百十二） 治咽喉急痛。 \n穴在手大指内侧去瓜甲角如韭叶，刺入二分许，以手自臂勒至刺处，出血即消。若重而脓 \n成者，必须针患处，否则难治。 \n\\x洪丞相蜞针法\\x（百十三） 凡痈疡势 毒盛，血凝不散者，宜用此法以杀其势。 \n治痈初作，先以笔管一个，入大蚂蝗一条，以管口对疮头使蜞吮，恶血得去其毒即散。 \n如疮大，须换三四条。若吮正穴，蜞必死矣，屡试屡效。若血不止，以藕节上泥涂之即止。若 \n疮头未明，以井边泥涂上，先干 \n处即是。 \n\\x骑竹马灸法\\x（百十四）治一切疮疡，无有不愈。 \n其法令病患以手肘凭几而坐，男左女右，将手臂竖起要直，乃用竹篾一条，自臂腕中 \n曲处横纹间量起，贴肉直上至中指尖尽处截断为则，不量指甲。另用竹扛一条，令病患脱衣 \n正身骑定，前后用两人扛起，令病者脚不着地，仍使人扶定，勿令伛偻，却将前量臂篾从竹扛 \n上尾 骨坐处，直贴脊背量至蔑尽处记之，此取中之处，非灸穴也。又用薄篾量男左女右手 \n中指节两横绞处，截为同身寸法，将此寸蔑即安前脊中点记处，两边各开一寸，尽处即是 \n灸穴，各灸五七壮。疽发于左则灸右，疽发于右则灸左，两边俱甚则左右皆灸。盖此穴乃心脉 \n所过之处，凡痈疽皆心火之留滞，灸此则心火流通而毒自散矣，有起死回生之功，屡试屡验。 \n\\x神仙隔蒜灸法\\x（百十五）治一切痈疽疮毒大痛，或不痛，或麻木，及治痘疔毒瓦斯炽盛， \n使诸痘不能起发，已起发者不能灌脓，已灌脓者不能收靥等证。如痛者灸至不痛，不痛者灸 \n至痛，其毒随火而散，此攻散郁毒从治之法也，大有回生之功。其法用大蒜头去皮切三分浓， \n按疮头上，用艾炷于蒜上灸之，五壮换蒜复灸，或三十壮，或一二百壮，愈多愈妙。未成者 \n即消，已成者亦杀其大势，不能为害。如疮大用蒜捣烂摊患处，将艾铺上烧之，蒜败再换。 \n或阴毒紫白色，不起发，不痛，不作脓者，尤宜多灸，仍服托里之剂。如灸后仍不痛，或不 \n作脓，不起发者不治，此气血虚极也。 \n\\x附子饼\\x（百十六）治溃疡气血俱虚，不能收敛，或风寒袭之，以致血气不能营运，皆令 \n不敛。用炮附子去皮脐研末，以唾津和为饼，置疮口上，将艾炷于饼上灸之，每日灸数壮， \n但令微热，勿令痛，如饼干，再用唾津调和，务以疮口活润为度。 \n\\x豆豉饼\\x（百十七） 治疮疡肿毒硬而不溃，及溃而不敛，并一切顽疮恶疮。用江西 \n豆豉饼为末，唾津和作饼子，如钱 \n大，浓如三文钱，置患处，以艾炷于饼上灸之，干则再易。如灸背疮，用漱口水调饼覆患处， \n以艾铺饼上灸之。如未成者即消，已成者亦杀其大毒。如有不效，必气血虚败也。 \n\\x木香饼\\x（百十八）治一切气滞结肿或痛，或闪肭，及风寒所伤作痛，并效。 \n木香（五钱） 生地黄（一两） \n上以木香为末，生地黄杵膏和匀，量患处大小作饼，置肿处，以热熨斗熨之。 \n\\x香附饼\\x（百十九）治瘰 流注肿块，或风寒袭于经络，结肿或痛。 \n用香附为末，酒和量疮毒大小作饼，覆患处，以热熨斗熨之。未成者内消，已成者自溃。 \n若风寒湿毒，宜用姜汁作饼。 \n\\x神效桑枝灸\\x（百二十）治发背不起，或瘀肉不溃，此阳气虚弱。用桑枝燃着，吹熄其焰， \n用火灸患处片时，日三五次，以助肿溃。若腐肉已去，新肉生迟，宜灸四畔。其阴疮瘰 ，流注 \n疮，恶疮久不愈者，亦宜用之。大抵此法，未溃则解热毒，止疼痛，消瘀肿，已溃则补阳气， \n散余毒，生肌肉。若阳证肿痛，甚或重如负石，初起用此法，出毒水即内消；其日久者用之， \n虽溃亦浅，且无苦楚。惜患者不知有此，治者亦不肯用此也。 \n\\x神效葱熨法\\x（一二一）治流注结核，骨痈鹤膝，肢体肿块，或痛或不痛。或风寒袭于 \n经铬，流注肢体，筋挛骨痛。或跌扑损伤，止痛散血消肿之良法。或先用隔蒜灸法而余肿未消， \n最宜用熨，以助气血而行壅滞，其功甚大。用葱头钿切，杵烂炒热敷患处，冷即易之，再或热 \n熨数次，肿痛即止，其效如神。或用葱煎汤，熏洗伤处亦妙。或用葱一大把，束其数节，切为 \n薄饼置患处，用热物熨之，或铺艾灸之亦可，必易饼多熨为妙。 \n\\x神仙熏照方\\x（一二二） \n雄黄 朱砂 血竭（真者） 没药（各一钱） 麝（二分） \n上五味，研细末，用棉纸卷为粗捻，约长尺许，每捻中入药三分裹定，以真麻油润透， \n点灼疮上。须离疮 \n半寸许，自红晕外圈周遭徐徐照之，以渐将捻收入疮口上，所谓?外而内也。更须将捻猛 \n向外提，以引毒瓦斯，此是手法。此药气从火头上出，内透疮中，则毒随气散，自不内侵脏腑。初 \n用三条，渐加至五七条，疮势渐消，可渐减之，熏罢随用后敷药。 \n广陵李杜云∶背疮所患，惟内攻与外溃耳。证属火毒，酝酿斯成，不能外散，势必内攻， \n不能中出，势必旁溃。医者往往以凉药围解，多罹此二患。又阴疮不起发者，止有隔蒜灸一法， \n然亦未见凿凿取效。此方初用药捻熏照，以火引火，毒瓦斯外散，后用药敷围，追脓止痛，毒从 \n孔窍及疮顶中出，可免旁溃矣。阴疮一照，即起红晕，状如蒸饼，变为阳证，可保无虞，此 \n其奇中大略也。照法日每一次，初次用捻三根或四根，次日用四根或五根，再次渐至六七根 \n止，大率看疮轻重，酌捻多寡。重者不过六七日，腐肉尽化为脓，从疮口中陆续涌出，新肉如 \n石榴子累累而生，此时不必再照。围药终始如一，随疮势大小，渐渐收入。照围后不可听 \n医用膏药贴盖，以致毒瓦斯怫郁，止剖葱叶量疮口贴之。凡照时先须用猪蹄煎汤，澄清洗去围药。 \n如法熏照，待疮势大愈，肉生将满，始可用生肌散，或护以太乙膏，平复后膏药犹不可离，此 \n其始末细微也。内服者，大要不出十宣散、护心散等方，最忌寒凉，恐伤胃气。此疮由恼 \n怒郁结浓味所致，受病以年计，愈久则愈甚也。调摄之法，非惩忿窒欲，清散托里，治以前方， \n即卢扁复生有望而走耳。又前方初止治背疽，其后一切肿毒无不牧功，盖法无定则，医贵变通， \n神而明之，存乎其人耳。余不佞善病，故留心方术，然未经累验，不轻授人。此一方初验于 \n化南，再验于陈大参景山，及范中翰舍初，其他证亦曾用以推展，皆应手取效，辄赘其详于此。 \n其传则道人孙氏，今大播广陵，余先慈赖以保安者廿年云。 \n池阳来阳伯云∶王孝廉良甫为余言，广陵人有善神灯照者，疗渠发背神良，已求得其 \n禁方矣，余识之。已西岁余客广陵，偶 肿比于股，招所谓善疗者照之，不脓得愈。又馆友 \n胡含素患发背，大如覆盂，神懵 \n懵愦矣，延疡医至，束手，待肉腐糜方可用膏，徐长肌肉。问其术曰至此，问其候曰百日。 \n果如其说，则含素将成乌有矣。遂急同弟辈求得前方刻本，按法治之。一日痛止，二三日神清， \n如脱桎梏，释重负，肉肿如盂者日缩而小，并未尝腐糜也。不月余脓尽，爽然起矣。奇矣哉！ \n不表而汗，不针而溃，不灸而陷举，不补而实，不下而毒尽，凡医人之针刺不必用也。至理 \n归于易简，大道本在目前，所谓不可不思议者也。古今道术入妙者皆如此类，兹重刻之，故为 \n此叙。 \n曲梁聂云翰云∶戊戌春暮，余病疽京邸，疽据背中，前与心对，初发微若黍粒，搔之痛痒 \n关心，寒热交作，甫十日大若升，再十日大若斗，食逆便结，匝月目不一瞬，医方所载诸死候业已十犯八九， \n两绝复苏，自分无生，手条后事。偶从杨楚璞得李肖衡所传异人指授仙方，如法熏敷，越二日 \n毒渐解，乃有起色，不易方而竟就痊，距初发浃廿旬。归家出以试人，经仅逾月，重亦不出百日， \n靡不起者，盖余所感毒极重，势极大，又治极迟，即二三内外科名家皆束手失色，以为从所未 \n闻未见，及试人则取验更捷，盖感有轻重，治有迟早也。顾念非此异方，不能起余必死异证， \n非余起死回生，不能白此方之神异，余以此方活，安忍天下人以此证危。因虑此方莫获广沛于 \n天下，又虑天下忽视此方而不加笃信，或乱于耻功不已出之医口，疑似转盼间，致误大事而悔 \n无及也，因赘数语以为此方之引。 \n咸林王维英云∶丙午端阳日，余左臂患疽，其大如拳，用骑竹马法，灸之百十壮， 起如 \n铜钱，四围肿觉退。笋中蓄此仙方，命制药料，欲俟破后熏之，不识其初亦可熏也。客有备言 \n可熏者，因于当日即熏十条，疮顶高收，四围色自，夜间毒肉从边化为稠脓，徐徐内溃，粘 \n同胶鳔。每日如法熏照洗贴，五六日，中尖毒肉脱落一条，共有十三孔，疮外一指许旁串三孔， \n且痛且痒，即极力照之，初出黄水，次出稠脓，后流清浆，瞬息口牧，并未再串。其原载敷药， \n长安中若不产 、五龙二草，止用金银花三色敷之。干则觉痛， \n即去之不敷，并未用生肌散，惟护以太乙膏，月余尽痊。当此疮将愈，左臂又患一疽，正对 \n无二，即照捻十条，敷以麸炒醋调文蛤膏，一日数更。次日五条，三日顶破脓出，不痛不痒，其 \n毒尽散。同时有患别疮者，余付此药熏之，随熏即散，并未成形。乃知是方也，真仙方哉！ \n真仙方哉！持此疗疮，天下无疮矣余恐世人但知疮破后可照，不识照初发者尤易散；又恐因敷 \n药不全，并弃前方，不识敷药不用亦可也，故备述终始，以神此方之用。 \n\\x洗药神效散\\x（一二三） 洗阴湿诸疮。 \n蛇床子（二两） 朴硝（一两） \n上每用一两，水一一碗，煎数沸，洗疮拭干，掺生肌药。 \n\\x雄黄解毒散\\x（一二四） 治一切痈肿溃烂。毒势甚者，先用此药二三次，以后用猪蹄汤。 \n雄黄（一两） 白矾（四两） 寒水石（ ，一两半） \n上俱为末，用滚汤二三碗，乘热入药末一两洗患处，以太乙膏或神异膏贴之。 \n\\x猪蹄汤\\x（一二五） 治一切痈疽杖疮溃烂，去恶肉，润疮口，止痛。 \n白芷 黄芩 当归 赤芍药 独活 生甘草 露蜂房（连子者佳，各五钱） \n用猪蹄一只，水四五碗，煮熟去油 ，取清汤，入前药一两许，煎十数沸，去 温洗， \n恶肉随洗而下，随用膏药贴之。按∶此汤不必用黄芩，或以白矾易之更佳。 \n\\x集香散\\x（一二六） 洗痈疽溃烂。 \n白芷 藿香 茅香 香附 防风（各三钱） 木香 甘草（各钱） \n上用水三碗，煎数沸，去 ，淋洗患处。 \n立斋曰∶此乃馨香之剂也，血气闻香则行，得臭则逆也，凡疮毒将尽未尽宜用之。 \n若有瘀肉，宜先用雄黄解毒散解之，后用此方，洗后须即用膏药贴护，勿使风入肌肉易生， \n直至收口为度。最忌用生肌之药 \n\\x敷药方\\x（一二七） \n车前草 草 金银花 五爪龙草 \n上四味，鲜草，一处捣烂，加多年陈米粉，即常用糨衣者，初起时仍加飞盐少许，共调 \n为稠糊敷疮上，中留一顶拔脓出。若冬时无鲜者，用干叶为末，陈醋调敷亦可。或五龙草一 \n时难得，即单用四味亦能奏功，不必拘执也。阳伯曰∶疮毒初起毒盛者，须内服败毒药数剂； \n其有气血薄弱者，亦须用托里药数剂，则万全之计耳。 \n\\x《秘传》围药铁井栏\\x（一二八）敷一切恶毒，即收敛消肿，神效。 \n牛粪灰（晒干烧灰，用新瓷罐盛之，干处加倍用） 铁线草 草乌 文蛤 白芨 \n白蔹 贝母心 陈小粉（炒极黄色，各等分） \n上为末，用高醋熬热调药如糊敷疮，四围中留钱孔以出毒瓦斯，干则易之。疮势恶甚者， \n用飞龙夺命丹等药，出汗，无不效。 \n\\x大黄揭毒散\\x（一二九）敷热壅肿毒。 \n大黄（一两半） 白芨（一两） 朴硝（二两） \n上为末，井水调搽，干则润之。 \n\\x草乌揭毒散\\x（百三十）治一切痈疽肿毒。 \n草乌 贝母 天花粉 南星 芙蓉叶（等分） \n上为末，用醋调搽四围，中留头出毒，如干，用醋润之。 \n\\x抑阴散\\x（一三一）治疮疡元气虚寒， 肿不消，或不溃敛，或筋挛骨痛，一切冷证。 \n草乌（二两） 南星（煨） 赤芍药（炒） 白芷（各一两） 肉桂（五钱） \n上为末，葱汤调涂，热酒亦可。 \n\\x抑阳散\\x（一三二）一名洪宝丹。治疮属纯阳，肿痛发热。 \n天花粉（三两） 姜黄 白芷 赤芍药（各一两） \n上为末，茶汤调搽患处。 \n\\x阴阳散\\x（一三三）治疮属半阴半阳。 \n紫荆皮（炒，五两） 独活（去节，炒，一两） 赤芍药（炒） 白芷 石菖蒲（各二两） \n上为末，葱酒调搽。 \n\\x神功散\\x（一三四） 诸发背痈疽，及诸疮，不问肿溃皆效。 \n黄柏（炒） 草乌（炒，各一两） \n上为末，用漱口水调入香油少许搽患处，如干，仍用水润之。 \n\\x清凉救苦散\\x（一三五） 治大头瘟肿甚者，以此药敷之。 \n芙蓉叶 霜桑叶 白蔹 白芨 大黄 黄连 黄柏 白芷 雄黄 芒硝 山茨茹 赤小豆 \n南星 金线重楼 \n上等分为末，蜜水调敷肿处，以翎频扫之。 \n\\x二黄膏\\x（一三六） 敷一切肿毒，热浮在外，或时气热壅者。 \n黄柏 大黄（各等分） \n上为末，用醋调敷，如干，用水润之。 \n\\x回阳玉龙膏\\x（一三七）治阴疽发背，寒邪流注，风湿冷痹，诸香港脚冷痛无红赤者，及跌 \n扑所伤为敷凉药，或人元气虚寒，肿不消散，或不溃敛，及痈肿坚硬，肉色不变，久而不溃， \n溃而不敛，或鼓椎风筋挛骨痛，一切阴寒冷证第一药也。 \n草乌 肉桂（各五钱） 姜黄（炒） 南星（煨） 白芷 赤芍药（炒，各一两） \n上为末，葱汤或热酒调涂。 \n\\x冲和膏\\x（一三八）治一切疮肿，不甚 热，积日不消。 \n紫荆皮（炒，五两） 独活（去节，炒，三两） 赤芍药（炒，二两） 白芷 菖蒲（各一两） \n上为末，葱头煎汤调搽。 \n\\x麦饭石膏\\x（一三九）治疮疽初起，先以麦饭石膏涂之，俟疮根渐收，即敷神异膏敛之。 \n但麦饭石膏难于修合，用神异膏亦效。 \n白麦饭石（炭火 ，醋淬数次，研极细二两。据《本草》所载，凡石如饭团，粒粒粘结 \n成块者即是，皆可用也） 鹿角（生取带脑骨者，断之，用炭火烧烟尽，研极细四两） \n上用米醋调和，入砂器煎，以竹片不住手搅熬成膏。先用猪蹄汤洗患处，以鹅翎拂涂四围， \n干则以醋润之，若腐烂者，用布帛摊贴之。李氏曰∶麦饭石膏治发背痈疽神妙，惜世罕知。 \n有患痈不溃而危者，全用此膏，一夕顿溃。凡疽得脓，其毒始解，或有不溃者，须用此膏， \n故录之俾精择修合，以取十全之功也。尝见世间医者，每有妙方，秘而不传，或更改以惑人， \n诚可恶也。余思西华麦饭石膏守死不传，其立心私刻，君子鄙之矣。 \n\\x黑末子\\x（百四十）治疖毒。 \n用羊角连内骨烧存性，为末。酒调三钱，分上下服之，疮可散。立斋曰∶此方未尝用， \n盖秘方也。尝治面上或身卒得赤斑，或痒或瘭毒，此而不治，亦乃杀人。以 羊角烧存性，研 \n为极细末，以鸡子清调涂之，甚效。本草亦云然。 \n\\x乳香定痛散\\x（一四一）治疮疡溃烂，疼痛不可忍，诸药不效者。 \n乳香 没药（各二钱） 寒水石（ ） 滑石（各四钱） 冰片（一分） \n为细末，搽敷患处，痛即止。此方乳、没性温，佐以寒剂制之，故寒热之痛皆妙。 \n\\x乌金膏\\x（一四一）治发背中央肉死，涂之即腐；未死，涂之即生。若初起肿痛，用点数 \n处，则解毒顿消，若瘀肉腐黑，涂之即溃。若恶疮顽疮，元气无亏，久不收敛者，内有毒根， \n以纸捻醮 其内。有等发背因元气虚弱，或因克伐，元气亏损，毒瓦斯散漫，中黯外赤，不腐"}, {"n": 40, "text": "卷四十\n\n不溃，须服大补之剂，中涂三四寸许，至五六日间，赤黯之界自有裂纹如刀划之状，中央渐溃 \n渐脱，内用纯阳之药以接其元气，庶能收敛。若妄用刀针。去肉出血，则阳随阴散，元 \n气愈伤，或涂凉药则毒瓦斯不解，气血愈虚，非徒无益，适以害之矣。其方用巴豆去壳炒黑， \n研为膏，点肿处，或涂瘀肉上，则自消化，或加乳香少许亦可。如涂疮内，或加香油少许调稀 \n可用。若余毒不敛者，以此 之，不致成痛。 \n\\x透骨丹\\x（一四三） 此溃脓药，外科不可缺。 \n蟾酥 硼砂 轻粉 巴豆（各五钱） 蜗牛（二个） 麝香（一分） \n上先将巴豆研如泥，次入蜗牛、麝香再研，后入各药研极细，以小瓷瓶收藏。每用少许 \n以乳汁化开，先用铁轻轻拨破毒头，挑药米粒许纳于疮口，外用清凉膏贴之。 \n\\x针头散\\x（一四四）治一切顽疮，内有脓管瘀肉，或瘰 结核不化，疮口不合，宜此药追 \n蚀腐之。 \n赤石脂（五钱） 轻粉 麝香（各五分） 乳香 白丁香（各三钱） 生砒 黄丹（各一钱） \n蜈蚣（一条，炙干） \n上为末，搽瘀肉上，其肉自化。若疮口小或痔疮，用糯米糊和作细条，阴干 入，外以 \n膏药贴之。凡疮口久不合者，内有脓管，必须用此腐之，内服托里之药。 \n\\x代针膏\\x（一四五）治疮疡脓熟不溃。 \n乳香（二分） 白丁香（真者是） 巴豆（炒焦） 碱（各五分） \n上为末，热水调点疮头上，常以碱水润之，勿令其干。 \n\\x替针丸\\x（一四六）治脓成不溃者。 \n白丁香 砂（另研） 真没药 乳香（各一匙） \n糯米四十粒，先以矿灰拳大一块，置瓷碗内，量入井水，待热气将息，以米排入灰中， \n良久候米如水 \n晶状，取出用之，如米未就，再用灰制。 \n上各另为末，然后和匀收贮。用时以饭丸麦粒大，每用一粒，水湿粘疮头上，其脓自出。 \n凡疮疡血气壮实，脓成不溃者，宜用此药以泄其毒，则肌肉易生，疮口易敛。若气血亏损者， \n须用甘温之剂以培根本，否则不惟不溃，且难收敛。若附骨疽及紧要之地，当及时针砭出之 \n为善。 \n\\x三合散\\x（一四七） 治痈疽不肯作脓。 \n新巴豆肉 明砒 斑蝥（等分） \n上为细末， 疮内，恶肉自化。 \n立斋曰∶此方药性太毒，果有恶毒之证，宜用腐之，取其以毒攻毒也。若以阳气虚，不能 \n腐化成脓者，宜用大补之剂，及桑木灸之。丹溪云∶气血壮实，脓自涌出。大抵疮之溃敛迟速， \n总由血气之盛衰使然也。 \n\\x藜芦膏\\x（一四八）治一切疮疽 肉突出，不问大小长短，用藜芦一味为末，以生猪脂 \n和研如膏涂患处，周日易之。 \n\\x生肌散\\x（一四九）治疮口不合。 \n木香 轻粉（各二钱） 黄丹 枯矾（各五钱） \n上为细末，用猪胆汁拌匀晒干，再研细，掺患处。 \n立斋曰∶此方乃解毒去腐搜脓之剂，非竟自生肌药也，盖毒尽则肉自生。常见患者往往 \n用龙骨、血竭之类以求生肌，殊不知余毒未尽，肌肉何以得生，及增腐烂耳。若此方诚有见也。 \n\\x收口掺药\\x（百五十） \n李氏云∶龙游有患背疽者，大溃，五脏仅隔膜耳，自谓必死。用鲫鱼去肠，实以羯羊粪， \n烘燥为末，干掺之，疮口自收。此出洪氏方，屡用有效，故附于此。须候脓少欲生肌肉时用之。 \n\\x桔梗汤\\x（一五一）治咳嗽吐脓，痰中有血，胸膈两胁作痛，烦闷作渴，或出臭浊，已 \n成肺痈证。 \n桔梗（炒） 贝母 当归（酒浸） 栝蒌仁 枳壳（麸炒） 薏仁 桑白皮（炒） 百合（蒸， \n各一钱五分） 五味子（炒） 知母（炒） 地骨皮 甜葶苈（炒） 甘草节 防己 黄 杏仁（各五分） \n水二钟，煎服。 \n（《济生》）\\x桔梗汤\\x（一五二） 治肺痈咳嗽脓血，咽干多渴，大小便赤涩。 \n方如前，但少五味、葶苈、知母、地骨皮四味。 \n用水二钟，姜五片，煎八分。食远服。大便秘者，加大黄。 \n\\x人参五味子汤\\x（一五三） 治气血劳伤，咳脓咯血，寒热往来，夜出盗汗，羸瘦困乏， \n一切虚损肺痿之证并治。 \n人参 五味子（炒，捣） 熟地黄 当归（酒炒） 白术（炒） 白茯苓 炙甘草 陈皮 \n桔梗（炒） 前胡（各一钱） 黄 （炙） 地骨皮 桑白皮（炒） 枳壳（炒） 柴胡（各七分） \n水一钟半，生姜三片，煎八分。食后服。 \n\\x四顺散\\x（一五四）治肺痈吐脓，五心烦热，壅闷咳嗽。 \n贝母（去心） 紫苑（去苗） 桔梗（炒，各一钱半） 甘草（七分） \n水一钟半，煎七分，食远服。如咳嗽，加杏仁。亦可为末，白汤调服。 \n\\x合欢饮\\x（一五五）治肺痈久不敛口。 \n用合欢皮白蔹二味同煎服。合欢皮即槿树皮也，亦名夜合。 \n\\x紫菀茸汤\\x（一五六）治饮食过度，或煎爆伤肺，咳嗽咽干，吐痰唾血喘急，胁痛不得 \n安卧，肺痿等证。 \n紫菀茸（去苗） 桑叶（经霜者） 款冬花 百合（蒸焙） 杏仁（去皮尖） 阿胶（蛤 \n粉炒） 贝母（去心） 半夏（制） 蒲黄（炒，各一钱） 人参 犀角（镑末） \n甘草（炙，各五分） \n水一钟半，生姜三片，煎七分，入犀角末。食后服。 \n\\x升麻汤\\x（一五七）治肺痈胸乳间皆痛，吐脓腥臭。 \n川升麻 桔梗（炒） 薏苡仁 地榆 黄芩（炒） 赤芍药（炒） 牡丹皮 生甘草（各一钱） \n水二钟，煎八分。食远服。 \n\\x如金解毒散\\x（一五八） 治肺痈。 \n桔梗（一钱） 甘草（一钱半） 黄连（炒） 黄芩（炒） 黄柏（炒） 山栀（炒，各七分） \n水二钟，煎八分。徐徐陆续饮之，不可急服。按∶此方乃降火解毒之剂也，凡发热烦渴， \n脉洪大者，用之即效。若脉数，咳痰腥臭，或唾脓瘀者，宜用桔梗汤。 \n\\x如圣柘黄丸\\x（一五九）治肺痈咳而腥臭，或唾脓瘀，不问脓之成否并效。肺家之病虽有方， \n惟此方功效甚捷，不可忽之。 \n柘黄（一两，为末） 百齿霜（即梳垢，二钱） \n用糊为丸，如桐子大。每服三五十丸，米饮下。柘黄，乃柘树所生者，其色黄，状 \n如灵芝，江南最多，北方鲜有。 \n\\x葶苈散\\x（百六十） 治过食煎 ，或饮酒过度，致肺壅喘不能卧，及肺痈浊唾腥臭。 \n甜葶苈 桔梗（炒） 栝蒌仁 川升麻 薏苡仁 桑白皮（炒） 葛根（各一钱） \n甘草（炙，五分） \n水一钟半，生姜三片，煎八分。食后服。 \n\\x知母茯苓汤\\x（一六一）治肺痿喘嗽不已，往来寒热，自汗。 \n知母（炒） 茯苓 炙甘草 人参 白术 五味子（炒，捣） 麦门冬 半夏（制） \n薄荷 桔梗 柴胡 款年花（各一钱） 阿胶（蛤粉炒） 黄芩（炒，各二钱） \n川芎（五分） \n水二钟，姜三片，煎一钟。食远服。 \n\\x四味排脓散\\x（一六二） 治肺痈吐脓，五心烦热，壅闷咳嗽。 \n嫩黄 （盐水炒） 白芷 五味子（研，炒） 人参（等分） \n上为细末。每服三钱，食后蜜汤调下。 \n\\x八味排脓散\\x（一六三） 治肠痈少腹胀痛，里急后重，脉滑数，或时时下脓。 \n黄 （炒） 当归（酒拌） 金银花 穿山甲（蛤粉炒） 白芷 防风 连翘 栝蒌（各三钱） \n水二钟，煎八分，食前服；或为末，每服三钱，食后蜜汤调下。如脓将尽，去穿山甲、 \n连翘，倍当归，加川芎。 \n\\x薏苡仁汤\\x（一六四） 一名瓜子仁汤。治肠痈腹中 痛，或胀满不食，小便短涩。妇 \n人产后多有此证，纵非痈，服之尤效。 \n薏苡仁（炒，五钱） 栝蒌仁（三钱） 牡丹皮 桃仁（去皮尖，各二钱） \n上水煎。空心服。 \n\\x牡丹皮散\\x（一六五） 治肠痈腹濡而痛，时时下脓。 \n牡丹皮 人参 黄 （炒） 白茯苓 天麻 白芷 桃仁（去皮尖） 薏苡仁 当归 川芎（各一钱） \n官桂 甘草（各五分） 木香（三分） \n上水煎服。 \n\\x梅仁汤\\x（一六六） 治肠痈壅痛，大便秘涩。 \n梅仁（九个，去皮尖） 大黄（炒） 牡丹皮 芒硝 犀角（镑，各一钱） 冬瓜仁（三钱，研） \n上水煎，入犀角末服。 \n\\x大黄汤\\x（一六七） 一名牡丹皮汤。专治肠痈小腹坚肿而热，按之则痛，肉色如故，或 \n赤微肿，小便频数，汗出憎寒，其脉沉紧，脓未成者，急服之。 \n牡丹皮 栝蒌仁（各三钱） 桃仁（去皮尖） 大黄（煨） 芒硝（各二钱） \n水二钟，煎一钟。食前服。本方去栝楼，即名大黄牡丹汤，立斋曰∶此方乃行血破血之剂也，如 \n发热自汗 \n恶寒，小腹作痛，小便如淋，脉未数者有效。丹溪曰∶小腹肿痞，按之痛，小便如淋，或自 \n调，发热身无汗，复恶寒，其脉迟紧者，脓未成，宜下之，当有血，此结热所成也，故《金匮》 \n用大黄利之，即此方也。若无前证，恐不宜用。其有脉滑数，腹内胀痛，或时时后重，而 \n脓已下，宜用八味排脓散、蜡矾丸，及托里之药。 \n\\x射干汤\\x（一六八）治胃脘痈吐脓血。 \n射干（去毛） 山栀仁 赤茯苓 升麻（各一钱） 白术（五分） 赤芍药（一钱半） \n上水煎服。 \n\\x槐花散\\x（一六九）治肠风脏毒下血。 \n槐花（炒） 熟地黄 青皮 白术（炒） 荆芥穗 当归身（酒拌） 升麻（各一钱） 川芎（四分） \n上为末。每服三钱，空心米饮调下。水煎服亦可。 \n\\x除湿和血汤\\x（百七十） 方在和阵二一九。治阳明虚陷，湿热便血腹痛。 \n\\x夏枯草汤\\x（一七一）治瘰 马刀，已溃未溃，或日久漏者。 \n夏枯草（六两） \n水二钟，煎七分，去 。食远服。此生血治瘰 之圣药，虚甚者，当煎浓膏服，并涂患处， \n多服益善，兼十全大补汤加香附、贝母、远志尤善。 \n\\x必效膏\\x（一七二） 治瘰 气血尚无亏损， 核不愈，内服此药，外以针头散腐之。 \n若气血虚者，先服益气养营汤数剂，后服此药。服后 毒尽下，再服煎汤数剂。 \n南硼砂（二钱半） 轻粉（一钱） 麝香（五分） 巴豆（五个，去膜） 白槟榔（一个） \n斑蝥（四十个，去头翅，同糯米炒） \n上同为极细末，取鸡子二个，去黄用清调药，仍入壳内，以湿纸数重糊口，入饭甑蒸熟， \n取出曝干研末。虚者每服半钱，实者一钱，用炒生姜酒、或滚汤于五更调服。如觉小腹痛， \n用益元散一服，其毒俱从小便出。胎妇勿饵。疮毒去后，多服益气养营汤，疮口自合。 \n此药斑蝥、巴豆似为峻利，然巴豆能解斑蝥之毒，用者 \n勿畏。予于京师遇一富商，项有 痕一片颇大，询其由，彼云因怒而致，困苦二年，百 \n法不应，忽有方士与药一服即退，二三再服顿退，四服而平，旬日而痊，以重礼求之，乃是 \n必效散，因修合济入，无有不效。丹溪亦云，必效与神效栝蒌散相兼服之，自有神效，常以 \n二剂兼补剂用之，甚效，故录之。但此药虽云峻利，然 毒之深者，非此不能解，故宜用之。 \n惟血气虚者不可用，恐其有误也。又一道人治此证，用鸡子七个，每个入斑蝥一枚，饭上 \n蒸熟，每日空心食一个，求者甚多。考之各书瘰 门及《本草》亦有之，然气血虚者 \n恐不能治也。 \n\\x射干连翘散\\x（一七三） 治寒热瘰 。 \n射干 连翘 玄参 赤芍药 木香 升麻 前胡 栀子仁 当归 甘草（各一钱） 大黄（二钱） \n水煎。食后服。 \n\\x如神散\\x（一七四）治瘰 已溃，瘀肉不去，疮口不合。 \n松香末（一两） 白矾（三钱） \n为末。麻油调搽，干掺亦可。 \n\\x遇仙无比丸\\x（一七五） 治瘰 未成脓，其人气体如常，宜服此丸。形气觉虚者，宜先 \n服益气养营汤，待血气少充，方服此丸，核消后，仍服前汤。如溃后有瘀肉者，宜用针头散， \n更不敛，亦宜服此丸，敛后再服前汤。 \n白术（炒） 槟榔 防风 黑丑（半生半炒取头末） 密陀僧 郁李仁（炮，去皮） \n斑蝥（去足翅，用糯米同炒，去米不用） 甘草（各五钱） \n为细末，水糊丸，梧子大。每服二十丸，早晚煎甘草槟榔汤下。服至月许，觉腹中微痛， \n自小便中取下 毒如鱼目状，已破者自合，未脓者自消。 \n（《肘后》）\\x治瘿方\\x（一七六） \n凡项下卒结囊欲成瘿者，用海藻一斤，洗去咸，浸酒饮之，不可间断，须要时时饮二 \n三杯，有酒气方妙。 \n\\x神效开结散\\x（一七七） 消瘿块甚效。 \n橘红（四两） 沉香 木香（各二钱） 珍珠（四十九粒，入砂罐内，以盐泥封因， 赤取出， \n去火毒用） 猪靥肉子（四十九枚，用豚猪生项间如枣子者） \n上为末。每服一钱，临卧酒调徐徐咽下。患小者三五服，大者一剂可愈。切忌酸咸油腻滞 \n气之物。须用除日于静室修合。 \n\\x生地黄丸\\x（一七八） 治师足、寡妇、室女，乍寒乍热而患疮疡，及颈间结核，肝脉弦 \n长而出鱼际，外无寒邪，内多郁火者，宜此治之。 \n生地（一两，酒拌杵膏） 秦艽 黄芩 硬柴胡（各半两） 赤芍药（一两） \n上为末，入地黄膏加炼蜜为丸，桐子大。每服三五十丸，乌梅汤日进二服。 \n（《外台》）\\x昆布丸\\x（一七九） 治项下结囊欲成瘿者。 \n昆布（酒洗） 海藻（酒洗，各等分） \n上为末，炼蜜丸，弹子大。含化咽之。 \n（《济生》）\\x玉壶散\\x（百八十）治三种毒瘿。 \n海藻 海带 昆布 雷丸（各一两） 广术 青盐（各半两） \n上为细末，老米饮为丸，桐子大。不拘时噙化四五丸。 \n\\x神效栝蒌散\\x（一八一）治乳痈及一切痈疽，初起肿痛即消，脓成即溃，脓出即愈。治痈 \n之方甚多，独此方神效，瘰 疮毒尤效。凡一切痈疽余毒皆宜用之。 \n栝蒌（一个，烂研） 当归（酒洗） 生粉草（各半两） 乳香 没药（各一钱） \n上用酒煎服，良久再服，如不能饮，以酒水各半煎之。如数剂不效，宜以补气血之药 \n兼服之。若肝经血虚，结核不消，佐以四物、柴胡、升麻、白术、茯苓。若肝脾气血虚弱， \n佐以四君、芎、归、柴胡、升麻。若忧 \n郁伤脾，气血亏损，佐以归脾汤。 \n\\x海藻散坚丸\\x（一八二）治肝经瘿瘤。 \n海藻 昆布 龙胆草（酒拌炒焦。各二两） 小麦（醋煮炒干，四两） \n上为末，炼蜜丸，桐子大。每服二三十丸，临卧白汤送下，或噙化咽之尤好。凡患瘰 ， \n服调治之药未应，宜佐以此上二方。一方有柴胡二两。 \n\\x连翘饮子\\x（一八三） 治乳内结核。服数剂如不消宜兼服八珍汤。初起有表证者， \n宜先解散。 \n连翘 川芎 栝蒌仁（研） 皂刺（炒） 橘叶 青皮 甘草节 桃仁（各一钱半） \n上水煎。食远服。 \n\\x清肝解郁汤\\x（一八四）治肝经血虚风热，或郁火伤血，乳内结核，或为肿溃不愈，凡 \n肝胆经血气不和之病，皆宜用此药。 \n人参 熟地黄 芍药（炒） 茯苓 山栀（炒） 贝母（各一钱） 柴胡 牡丹皮 川芎 \n陈皮（各五分） 当归 白术（各一钱半） 甘草（五分） \n上水煎服。 \n\\x羌活白芷散\\x（一八五）治风热血燥，手掌皱裂，或头面生疮，或遍身肿块，或脓水淋漓。 \n羌活 白芷 荆芥 软柴胡 蔓荆子 防风 甘草 牙皂 黄芩（酒炒） 黄连（酒炒， \n各一钱） \n上水煎服。 \n\\x胡麻散\\x（一八六） 治风热瘾疹瘙痒。 \n胡麻子（一两二钱） 苦参 荆芥穗 何首乌（各八钱） 威灵仙 防风 石菖蒲 牛蒡子（炒） \n甘菊花 蔓荆子 白蒺藜（炒） 炙甘草（各六钱） \n上为末。每服二钱，食后薄荷汤调服，茶清亦可。 \n\\x四生散\\x（一八七） 治 腿疮淫不愈，或眼目昏花，名肾脏风，并治风癣疥癞， \n血风疮证。 \n黄 独活 白附子（真者） 白蒺藜（等分） \n上为末。每服二钱，用猪腰子一枚，批开入药，湿纸包裹煨熟，空心连腰子细嚼，盐汤送下。 \n\\x槟苏散\\x（一八八） 治风湿流注，脚胫酸痛，或呕吐不食。 \n槟榔 木瓜 陈皮 炙甘草（各一钱） 香附 紫苏（各五分） \n水一钟半，生姜三片，葱白三茎，煎一钟。空心服。 \n\\x升麻和气饮\\x（一八九） 治风癣疮疥热结，大便不通。 \n当归 陈皮（各一钱半） 枳壳（麸炒） 芍药（酒炒） 半夏（制） 桔梗（炒） 白芷 \n苍术（米泔浸，炒） 干葛 白茯苓 甘草（炙，各一钱） 干姜（炒） 大黄（各五分） 升麻（三分） \n上水煎服。 \n\\x当归饮\\x（百九十） 治风湿血热，瘾疹痒痛，脓水淋漓，疮疥发热等证。 \n当归 川芎 生地黄 白芍药 白蒺藜（炒） 黄 何首乌（不见铁。各钱半） 防风 \n荆芥 甘草（各一钱） \n上水煎服。 \n\\x羌活当归散\\x（一九一） 治风毒血热，头面生疮，或赤肿，或成块，或瘾疹瘙痒， \n脓水淋漓。 \n羌活 当归 川芎 升麻 防风 白芷 荆芥 鼠粘子（蒸） 黄连（酒炒） 黄芩（酒炒） \n连翘 甘草 \n上用酒拌晒干。酒煎服。 \n\\x一扫散\\x（一九二） 治癣疥。 \n防风 荆芥 苦参 地骨皮 薄荷（等分） 甘草（减半） \n上为末。蜜水调服三钱，不过三五服可净。或炼蜜丸，桐子大。每服五七十丸，食远茶清 \n送下。 \n\\x乌金散\\x（一九三） 敷肾囊破烂、下疳等证。 \n麸炭 紫苏叶 \n上等分为末。香油调搽，用紫苏叶包裹之。 \n\\x蛇床子散\\x（一九四） 治一切风癣疥癞瘙痒，脓水淋漓。 \n蛇床子 独活 苦参 防风 荆芥（各三钱） 枯矾 铜绿（各一两，二味另为末） \n上为末。麻油调搽。 \n\\x金黄散\\x（一九五） 敷天泡湿热等疮。 \n滑石 粉甘草（此当半用为是） \n上等分为末。搽敷。此方或加绿豆末，以治湿热肥疮更妙。当以此方加枯矾少半，用治 \n肥疮大效。 \n\\x白粉散\\x（一九六）治诸疳疮。 \n海螵蛸（三分） 白芨（一分） 轻粉（一分） \n上为末。先用浆水洗拭，干敷。 \n\\x滑石散\\x（一九七）治小儿天泡疮。 \n好滑石 黄柏 \n上共为末敷之。仍内服荆防败毒散，或金银花散。热甚者，宜服大连翘饮。一方名 \n碧玉散，以青靛调前二味如泥，用皂刺挑破泡水，次敷药，神效。 \n（《秘方》）\\x仙遗粮汤\\x（一九八）治一切杨梅疮，不拘始终虚实，皆可取效。 \n土茯苓 即名仙遗根。用鲜者二两，洗净，以木石臼捶碎。 \n用水三碗，煎两碗，去 ，入后药煎服。 \n当归 生地 防风 木通 薏仁（各八分） 金银花 黄连 连翘（各一钱） 白术 白鲜皮（各 \n七分） 皂刺（六分） 甘草（四分） \n加灯心二十根，用遗粮汤二碗，煎一碗。食远服。 \n\\x土萆 汤\\x（一九九）治杨梅疮及瘰 、咽喉恶疮，痈漏溃烂，筋骨拘挛疼痛皆妙。 \n用土萆 即土茯苓二三两，以水三钟，煎二钟，不拘时徐徐服之。若患久，或服 \n攻击之剂，致伤脾胃气血等证，以此一味为主，外加对证之药，无不神效。 \n\\x五加皮饮\\x（二百） 治杨梅绵花疮百发百中，亦可煮酒以治结毒。 \n当归 木瓜 生地黄 熟地黄 羌活 薏仁（各一钱） 防风 荆芥 赤芍 苦参 \n大枫藤（各七分） 五加皮（二钱） 甘草 僵蚕（各五分） \n上每服入土茯苓四两，猪肉四两，用水二大碗，煎一碗。食前温服，渣再煎，连肉食之。 \n忌生冷、鱼腥沙气牛肉茶酒醋。所用土茯苓忌铁器。若治风毒，口服此药外，以此药煎膏，或 \n丹收，或粉收贴之。 \n\\x换肌消毒散\\x（二百一） 一名萆 汤。治时疮不拘初起溃烂。 \n土茯苓（五钱或一二两） 当归 白芷 皂刺 薏仁（各一钱半） 木瓜（不犯铁器） \n白鲜皮 木通 金银花（各一钱） 甘草（五分） \n上水煎服。甚者，土茯苓用至四五两更妙。 \n\\x蠲痹消毒散\\x（二百二）治时疮肢节筋挛。 \n姜黄 土茯苓 独活（各五钱） 白术 当归（各钱半） 芍药（一钱） 白芷（五分） \n上水煎服。 \n\\x七贴方\\x（二百三） 治杨梅绵花疮。 \n防风 忍冬 皂刺 蝉蜕（去头足） 连翘 白鲜皮 五加皮 荆芥 穿山甲（炒，各一钱） \n生地 木瓜（去心，忌铁） 僵蚕（炒，各一钱半） 皂子（七个） 薏仁（三钱） 土茯苓（四两） \n上用水四碗，煎二碗。食远分二次服之。忌牛羊茶酒醋房事。 \n\\x茯苓膏\\x（二百四）治杨梅疮，并治风毒。 \n当归 白蒺藜 羌活 生地 熟地 甘草（去皮） 连翘 木通（各三钱） 土茯苓（半斤） \n上为粗末，用水五六碗，熬将半，用绢滤去滓，再熬成膏，晾冷。每服一大酒钟，日三服。轻 \n者五六料，重者十料，全愈。熬药须用砂锅。忌房事鸡鱼牛肉椒醋等发物。 \n\\x五宝丹\\x（二百五）治九种杨梅结毒，并及儿女者。 \n琥珀（透明血色者，用甘草水煮过，三分半） 珍珠（炒过，三分半。一方用豆腐包蒸。） \n朱砂（透明者，三分半） 钟乳石（用木香、甘草各一钱同煮干，用三分半） 飞罗面（炒 \n过，三分半） 冰片（半分，临时加） \n上俱为极细末，瓷罐收贮听用。服法∶每日用土茯苓成块者一斤，洗净，用石敲碎，先 \n入水二升，煮取汁四碗，收瓷器内，将前 再入水四五碗，煮汁二碗，并入前汁内为一日 \n之用。若病在上者，加木香二钱；病在下者，加牛膝一两，与土茯苓同煎。病者不得另饮茶 \n汤，但将土茯苓汤时时饮之。若饮汤半钟，加五宝丹二厘，饮一钟，加四厘，体浓者，加 \n六七厘，一日内服尽此汤为度。在上饱服，在下饥服。忌茶酒并一切发风动气之物。其毒贴 \n清凉膏，或加掺药收口。若旧有轻粉等毒，服药后当尽发出，无则不发也。大忌房事。 \n轻者十服，重者二七服全愈。 \n（《医统》）\\x杨梅痈汤方\\x（二百六）不问年深者并效。 \n土茯苓（五两） 金银花（一两） 皂刺 花椒 牛蒡 郁金 当归（各五分） 黑铅（三两熔 \n化，入水银五钱，乘热擂为粉，分五分，听临后另入煎药用） \n上咀，分作五帖。用水二钟，入葱一根，煎至一钟，去 ，再入铅粉一分，煎至八分。 \n食远服。 \n上铅粉煎后，仍可取起，盖杨梅痈漏多因服轻粉积毒而成，此以水银、花椒、黑铅，仍 \n收引轻粉之毒从类而出也。此药每以五帖为一料，初服一帖，要取微汁。取汗法先以金银 \n花一两，或忍冬藤叶尤妙，防风、荆 \n芥、花椒各半两，煎汤二斗，于不透风处先熏后洗，自然汗出。即患二三十年者，只用此四料， \n四汗之，无不全愈，忌牛肉烧酒，真妙方也。世人珍秘不传，徐春甫得之，用以治人，一一 \n获效，故详载之以济人也。 \n\\x会脓散\\x（二百七） 治恶毒便毒初起之妙方也。 \n白芷 僵蚕（炒） 穿山甲（煨，各二钱） 大黄（四钱） 乳香 没药（各一钱） \n上为末，以当归四钱，用酒、水各一钟，煎一钟，去 ，量人强弱，或全用，或一半 \n调服之。此药若嫌太多，则 咀为饮，大黄生加，煎服之尤妙。 \n\\x牡蛎散\\x（二百八） 治便毒，亦名血疝。 \n当归（酒拌） 甘草节 滑石（ ，各一钱半） 牡蛎（二钱） 大黄（三钱） \n木鳖子（五个，杵。非有大热者此味不可用，当去之，亦不必用） \n水二钟，煎一钟，露一宿。五更顿服，冬月火温服。无论已未溃，脓血俱从大便出。 \n此方乃咸寒导滞之剂，若久旷房室，大小便秘，发热 痛，或交感时强固精气，以致交错壅滞， \n而结为肿痛便秘者，最宜用之。若劳倦虚弱之人，不甚 痛，大小便无热秘者，不宜轻用。 \n\\x牛黄双解散\\x（二百九）治便痈内蕴热毒，外挟风邪，或交感强忍精气，以致淫精交错， \n壅结肿痛或大小便秘，先用此药通解，更用调补之剂。 \n肉桂 大黄（炒） 芍药 牵牛（杵炒） 泽泻 桃仁（去皮尖，炒、各二钱半） \n炙甘草 干姜（各一钱） \n上分二剂，水煎。空心食前服。 \n\\x内托羌活汤\\x（二百十）治臀痈肿痛，两尺脉紧，按之无力者 \n羌活 黄柏（各二钱） 黄 （盐水炒） 防风 当归尾 本 肉桂 连翘（各一钱） 炙甘草 \n苍术 陈皮（各半钱） \n上水、酒煎服。 \n\\x加味泻肝汤\\x（二一一）治肝经湿热不利，阴囊肿痛，或溃烂皮脱，睾丸悬挂，或便毒及 \n下疳肿痛，或溃烂，皆治之。 \n龙瞻草（酒炒） 当归梢 车前子（炒） 生地黄 芍药（炒） 泽泻 黄连（炒） 黄柏（酒炒） \n知母（酒炒） 防风（各一钱） 甘草梢（五分） \n水二钟，煎八分。食前服。外敷乌金散。 \n\\x加味托里散\\x（二一二）治悬痈不消不溃。 \n人参 黄 （盐水炒） 当归 川芎 麦门冬 芍药（炒） 黄柏（酒炒） 知母（酒炒） \n金银花 制甘草 柴胡（各一钱） \n水二钟，煎八分。食前服。 \n\\x加味十全大补汤\\x（二一三）治悬痈溃而不敛，或发热饮食少思。 \n人参 黄 （盐水炒） 白术（炒） 熟地黄 当归 川芎 芍药（炒） 茯苓（各一钱） \n甘草（炙） 肉桂 五味子（捣，炒） 麦门冬（各五分） \n水二钟，煎一钟。食前服。茎肿，加青皮。小便赤，加酒炒黄柏、知母。小便涩，加车 \n前子、山栀子俱炒用。 \n\\x五味当归散\\x（二一四） 治妇人阴中突出一物，长五六寸，名阴挺。 \n当归 黄芩（各二两） 牡蛎（ ，一两半） 皮（炙，一两） 赤芍药（五钱） \n上为末。每服二钱，食前温酒调下，滚汤亦可。如不应，须以补中益气汤倍加柴胡、升 \n麻兼服之。又方∶ \n用当归、穿山甲炒、蒲黄炒各半两，辰砂一钱，麝香少许，俱为末。每服三钱，酒调下， \n尤效。 \n\\x妇人阴疮\\x（二一五） 治妇人阴户生疮作痒。 \n杏仁（炒） 雄黄 白矾（各五钱） 麝香（二分） \n上为末。敷入患处。 \n\\x 肿汤\\x（二一六）治妇人阴户生疮，或痒痛，或脓水淋漓。 \n甘草 干漆（各三钱） 生地黄 当归 黄芩 川芎（各二钱） 鳖甲（五钱，炙） \n上用水数碗，煎数沸，去 。当洗患处。 \n\\x白芷升麻汤\\x（二一七）治妇人阴内脓水淋漓，或痒或痛。 \n白芷 升麻 黄连 木通 当归 川芎 白术 茯苓 \n上水煎服。更用 肿汤浴洗之。 \n\\x痔漏肠红方\\x（二一八）其效无比。 \n黄连（去芦毛净一两，好酒浸一宿，捞起阴干为末） 百草霜（用草茅烧者，松柴者不用， \n一两，研细） 乌梅肉（一两，蒸软，即用前浸黄连酒蒸烂） \n上以三味同捣一处为丸，桐子大，如太干，仍如前酒捣丸之。每空心用酒送下四五十丸， \n三日见效，十日全愈。 \n\\x地榆散\\x（二一九）治血痔。 \n上用地榆为细末。每服二钱匕，食前米饮调下，日三服。 \n\\x臭樗皮散\\x（二百二十） 治痔漏下血，及脓不止。 \n臭樗皮（微炒） 酸石榴皮 黄连（去须） 地榆 阿胶（炒珠，各一两） \n艾叶（三钱，微炒） \n上为细末。每服二钱，食前粥饮调下。 \n\\x秦艽防风汤\\x（二二一） 治痔漏结燥，大便作痛。 \n秦艽 防风 当归（酒拌） 白术 黄柏 陈皮 柴胡 大黄（煨） 泽泻（各一钱） \n桃仁（去皮尖） 红花 升麻 甘草（各五分） \n上水煎。空心服。 \n\\x猪脏丸\\x（二二一） 治大便痔漏下血。 \n猪大脏（一条，控干，以槐花炒为末，填入脏内，两头札定，瓦器内米醋煮烂） \n上捣和，再加糕糊为丸，桐子大。每服五七十丸，食前米饮或当归酒下。此方用黄连、 \n猪脏二味，亦名猪脏丸，尤效。一方、先用海螵蛸炙黄，去壳为末，以木贼草煎汤调下， \n三日即效，或后服黄连猪脏丸。 \n\\x痔疮方\\x（二二三） \n雄黄（五分） 五灵脂（烧断烟） 五倍子（炒过，各一钱） 没药（三钱半，明者） \n白矾（半生半熟，三钱） \n上为极细末，用纸托贴疮口上。 \n\\x三品锭子\\x（二二四） \n上品去十八种痔。 \n白明矾（二两） 白砒（一两零五分） 乳香 没药（各三钱半） 牛黄（三钱） \n中品 去五漏，及翻花瘤、气核。 \n白明矾（二两） 白砒（一两三钱） 乳香 没药（各三钱半） 牛黄（二钱） \n下品治瘰 ，气核，疔疮，发背，脑疽诸恶证。 \n白明矾（二两） 白砒（一两半） 乳香 没药（各二钱半） 牛黄（三分） \n上将砒末入紫泥罐内，次用矾末盖之，以炭火 令烟尽取出，并各药俱研极细末， \n用糯米糊和为挺子，状如线香，阴干。 疮内三四次，年深者五六次，其根自腐。如疮露在外， \n更用蜜水调搽，干上亦可。尝有一老媪，用此治瘰 ，索重价始肯为治。其方法乃是中品锭子， \n疮内，以膏药贴之，其根自腐，未尽再用，去尽更搽生肌药，数日即愈，人多异之。凡见其 \n治气血不虚者果验，惟气血虚者，虽溃去亦不能愈。盖此与必效散相为表里，皆攻毒去邪之药也。 \n\\x羊胆膏\\x（二二五） 治痔漏、下疳疮。 \n腊月取羊胆一枚，入片脑末一分，置风处挂干。用时以凉水化开，颊敷患处，内服槐 \n子酒，或加味泻肝汤。 \n若得熊胆更佳。如眼痛者，点之尤效。 \n\\x水银枣子膏\\x（二二六）治虫痔痒不止。 \n水银（一两） 枣肉（二两） \n上和研水银不见星，捻如枣核状。薄绵裹，纳肛门中，明日虫出。若痛，加韶粉三分丸 \n纳之。 \n\\x熊胆膏\\x（二二七） 治痔痛极效。 \n熊胆（五分） 冰片（一分） \n上研细。用井花水调，鸡翎扫痔上。 \n\\x蜗牛膏\\x（二二八） 敷痔痛极效。 \n蜗牛（一枚，负壳有角者） 冰片 麝香（各少许） \n上同研烂，以瓷器盛，次早取汁敷痔上。 \n\\x芫花线\\x（二二九） 系痔漏瘤核。 \n用芫花一握，洗净，入木臼捣烂，加少水绞汁，于石器中熳火煎成膏，将丝线于膏 \n内度过，晾干。以线系痔，当微痛，候痔干落，以纸捻蘸膏纳窍内去根，当永除根也。一方 \n只捣汁浸线一夜用，不得使水。 \n\\x枯痔水澄膏\\x（二百三十） 治痔护肉。 \n郁金 白芨（各一两） 一方加黄连。 \n上二味为细末。如患内痔，候登厕时翻出在外，用温汤洗净，侧卧于床，其痔即出。 \n用蜜水调药得中，以篦篾涂谷道四边好肉上，留痔在外，以纸盖药上良久，然后用后枯药搽 \n痔上，仍用笔醮温水于纸上润之，勿令药干及四散。 \n好白矾（四两） 生信石（二钱半） 朱砂（一钱，研极细） \n上各研为细末；先将砒入紫泥罐底，次将矾末盖之，用火 令烟尽，其砒尽从烟去， \n止借砒气于矾内耳；将矾为极细末，看痔头大小，置矾末于掌中，乃入朱砂少许。以唾调稀， \n用蓖篾涂痔上周遍，一日三上，看痔头颜色焦黑为效。至夜有黄水出，切勿他疑，水尽为妙。 \n至中夜，上药一遍，来夜依然上药三次，有小痛 \n不妨。换药时以碗盛温汤，用笔轻洗去旧药，更上新药，仍用护肉药，间用荆芥汤洗之。三 \n两日之后，黄水出将尽，可于药中堵朱砂，减白矾，则药力即缓？三两日即可增减，渐渐取之， \n庶不惊人。全在看色增减，敷药浓薄，方是合法。此药只是借砒信之气，又有朱砂能以解之。 \n一方士将此二方在京治人多效，致富。一富商以百金求得之，录于予，予虽未用，传人无不 \n言效。但枯药则赵宜真炼师已刊于《青囊杂纂》，如神。 \n《千金方》则未见刊传。大抵今人言能取痔者，皆此方也。其有气血虚或挟内邪者，还当 \n兼治其内，庶不有失。 \n\\x如神千金方\\x治痔无有不效。 \n好信石（黄明者三钱打如豆粒） 明白矾（一两，为末） 好黄丹（飞砂，五钱） 蝎梢（七个，洗净， \n瓦上焙干为末） 草乌（光实者，去皮生研，五钱） \n上用紫泥罐先将炭火 红放冷拭净，先下明矾烧令沸；次下信入矾内拌匀，文武火 ， \n候沸再搅匀，次看罐通红烟起为度，将罐掇下，待冷取研为末，方入黄丹、草乌、蝎梢三味， \n再同研极细，以瓷罐收贮。如欲敷药，先煎甘草汤或葱椒汤洗净患处，然后用生麻油调前药， \n以鹅毛扫药痔上，每日敷药三次，必去黄水如胶汁，则痔头渐消。其年远者，不出十日可取尽， \n日近者俱化为黄水。连根去净，更搽生肌之药。凡五痔皆可去之。此乃临安曹五方，为高宗取 \n痔得效，后封曹官至察使。 \n\\x《秘传》正骨丹\\x（二三二） 治跌打损伤，骨折血瘀，而伤之重者，用此可续筋骨。 \n降真香 乳香 没药 苏木 松节 自然铜（醋 七次） 川乌（炮） 真血竭（各一两） \n地龙（去土，酒浸烘干） 生龙骨（各一钱） 土狗（十个，浸油内死，烘干） \n上十二味，共重八两八钱，同为末。每服五钱，随病上下酒调服。觉药自顶门而至遍身， \n搜至病所，则飒飒有声，而筋骨渐愈，病患自知之。服药后仍服人参、白术、黄 、当归、 \n川芎、肉桂、甘草、白芷、浓朴以调补元气。 \n（《本事》）\\x接骨方\\x 治打折损伤。 \n接骨木（半两） 乳香（半两） 当归 赤芍药 川芎 自然铜（炒，醋粹，各一两） \n上为末，用黄蜡四两，溶化入前药搅匀，众手丸，龙眼大。如打伤筋骨及闪痛不堪忍者， \n用一丸，热酒浸开，乘热饮之，痛即上。 \n\\x没药降圣丹\\x（二三四） 治趺打损伤，接续筋骨。 \n当归（酒炒） 白芍药 川芎 生地黄 苏木 川乌头（炮，去脐） 骨碎补（炙） \n乳香（另研） 没药（另研） 自然铜（火 ，醋淬十次，为末，各一两） \n上为末，生姜汁共蜜和丸，每一两作四丸。每服一丸，用水酒各半盏，煎至八分，空心 \n热服。立斋曰∶脾主肉，肝主筋。若肝脾气血亏损，或血虚有热而不愈者，当求其本而治之。 \n\\x十味没药丸\\x（二三五） 治打扑损伤，筋骨疼痛，或气逆血晕，或瘀血内停，肚腹作 \n痛，或胸胀闷。 \n没药 乳香 川芎 川椒 当归 芍药 红花 桃仁 血竭（各一两） 自然铜（四钱，火 七次， \n醋淬） \n上为末，同黄蜡四两溶化，入前末，速搅匀，众手丸，弹子大。每服一丸，酒化下。立斋曰∶ \n按接骨散、没药丸，惟元气无亏者宜用，若肾气素怯或高年虚弱者，必用地黄丸，或补中益气 \n汤以固根本为善。 \n\\x花蕊石散\\x（二三六） 治打扑损伤，腹中瘀血，胀痛欲死，服之血化为水，其功不能尽述。 \n硫黄（明者四两） 花蕊石（一两） \n上为末，和匀，先用纸筋和盐泥固剂瓦罐一个，候干入药，再用泥封口，安在砖上，虚书 \n八卦方位，用炭三十斤 之，候罐冷取出。每服一钱，童便调下。立斋曰∶前方若被伤已甚， \n元气亏损，内有瘀血，不胜疏导者，用前药一服，其血内化，又不动脏腑，甚妙，甚妙。 \n\\x黑丸子\\x（二三七） 一名和血定痛散。治跌打损伤，筋骨疼痛，或瘀血壅肿，或外感 \n风寒，肢体作痛，或手足缓弱， \n行步不前。若流注膝风初结，服之自消；若溃后气虚发热，与补药兼服自敛。 \n百草霜 白芍药（各一两） 川乌（炮） 南星（各三钱） 赤小豆（两半） 白蔹（一两六钱） \n白芨 骨碎补 当归（各八钱） 牛膝（六钱） \n上各另为末，酒糊丸，桐子大。每服三四十丸，盐汤、温酒任下，孕妇忌服。 \n\\x封口药\\x（二三八）凡损伤皮肉破裂者，以此封之。 \n牡蛎（ ） 赤石脂（生研） 红丹（上好者。等分） \n上为细末，香油调涂疮口。若欲消肿散血合口，加血竭干掺之。 \n\\x当归导滞散\\x（二三九）治跌扑瘀血在内，胸腹胀满，或大便不通，或喘咳吐血。 \n大黄 当归（等分） \n上为末。每服三钱，温酒下。阳气虚者，须加肉桂。 \n\\x复元活血汤\\x（二百四十）治跌打损伤，瘀血流于胁下作痛，或小腹作痛，或痞闷，及 \n便毒初起肿痛。 \n柴胡（一钱半） 天花粉 穿川甲（炒，各一钱） 当归（酒拌） 大黄（酒炒，各一钱） \n红花 甘草（各七分） 桃仁（二十个，去皮尖研） \n上水一钟半，加酒半钟，煎八分。食前服之，以利为度。 \n\\x金疮方\\x（二四一） \n凡金疮出血不止，用牛胆、锻石掺之即止。其方以腊月牛胆入风化锻石，悬当风候干用。 \n一方∶单用三七捣烂敷之，神效。又方∶金疮出血不止，以五倍子生为末，干贴之；如不止而血 \n热者，宜用犀角地黄汤之类。 \n大凡金疮出血不止，若素本怯弱者，当补其气；若阴虚或有热者，当补其血；若因怒者，当 \n平肝；若烦热作渴昏溃者，当补脾气；若筋挛搐搦者，当养肝血，不应，用地黄丸以滋肾水。 \n\\x金疮降真散\\x（二四二） \n降真香（用节佳） 松香 文蛤 \n三味等分为末。无论诸伤血出断折，掺破处夹缚定，神效。 \n\\x金疮灰蛋散\\x（二四三） 治金疮出血不止，及久年恶疮。 \n锻石（细研） 鸡蛋清（以和灰，成饼为度） \n上将灰蛋饼子 过，候冷研钿。遇金疮掺之；若多年恶疮，以姜汁调敷。一方单以锻石掺 \n伤处裹定，亦血止而愈。 \n\\x龙骨散\\x（二四四）治金疮。 \n龙骨 赤石脂 五 子 黄丹 海螵蛸（各等分） \n上各研，入麝香少许，共研匀掺上，如干，先以盐水洗，挹干掺之。 \n\\x桃花散\\x（二四五）治金疮，并一切恶疮。 \n黄丹 软石膏（ 过，等分） \n和研匀如桃花色。掺伤处，甚妙。 \n\\x刀伤跌打经验方\\x（二四六） \n凡刀伤磕损跌扑肿痛，或出血，用葱白细切杵烂，炒热敷患处，葱冷再易，神效。一方以三 \n七捣烂罨之，神效。 \n立斋曰∶《医学纲目》称前方有神效，余尝以治前证，青肿不散，死肉不溃，佐以健脾胃 \n之药，其功尤捷，此内外所以合一也。 \n\\x损伤敷夹法\\x（二四七） \n凡损伤骨折者，先须整骨使正，随用川乌、草乌等分为末，以生姜汁调贴之，夹定，然后 \n服药，无有不效。 \n\\x罨跌闪肿痛\\x（二四八） \n用生姜、葱白同捣烂，和面炒热罨之。如热服而痛者，用栀子加面炒热罨之。 \n\\x洗损伤方\\x（二四九）凡伤重者，用此淋洗，然后敷药。 \n荆芥 土当归 生葱（切断，一方用生姜） \n上同煎汤，温洗。或止用葱一味煎洗亦可。 \n\\x箭旋竹木刺方\\x（二百五十） \n《百一》方治竹刺在肉，以蛴螬虫研敷立效。 \n《衍义》方治竹木刺入肉，嚼牛膝根罨之即出。 \n《肘后》方治箭镞入骨，以巴豆肉微炒，同蜣螂研匀涂伤处，俟痒极，拔出之。 \n孙真人治箭镞针刺，杵蝼敷涂患处自出。 \n\\x罨跌打夹棍伤\\x（二五一） \n生姜 陈酒糟（各一斤） \n同捣烂，炒热。罨伤处。 \n\\x治拶伤\\x（二五二） \n凡拶伤手指者，用皂矾二两，水四五碗，砂锅内熬滚，将手熏洗良久，即血活疼止，不致 \n溃烂。熬水忌铜铁器。其洗手水过夜即臭恶不可闻。 \n\\x杖疮四方\\x（二五三） \n用川大黄一两，加上好冰片二分，另研，俱为末，和匀，凉水调如糊，摊杖处，实时 \n止痛，一日后换膏药贴之。 \n又方∶加甘草一两。 \n又方∶摊药 \n大黄 白芷 生半夏（各七钱） \n上为末。以鲜姜汁调敷，干即再敷，以黑处血红为度，即换贴膏药，神效。 \n又方∶ \n生半夏 松香（各一两） \n上研一处，蜜水调成膏贴之。勿令见风。如干再换一个，即愈。 \n\\x诸骨诸物鲠\\x（二五四） \n一、治诸骨鲠，用苎麻根杵烂丸，弹子大，将所鲠物煎汤化下。 \n一、治鱼骨鲠，用细茶、五倍子等分为末，吹入咽喉立愈。 \n一、治稻芒、糠谷鲠喉，将鹅吊一足取涎，徐徐咽之即消。 \n一、治吞钉铁、金银铜钱等物，但多食肥羊脂及诸般肥肉等味，必随大便而下。 \n一、治吞铁或针，用饧糖半斤，浓煎艾汁调和服之。 \n一、治吞发绕喉不出者，取自己乱发烧灰，白汤调服一钱。 \n\\x破伤风敷药\\x（二五五）治打扑损伤伤风肿痛者。 \n南星 半夏 地龙（等分） \n上为末。用生姜、薄荷汁调搽患处。 \n\\x 酒\\x（二五六）治破伤风外邪初入，或风入于脏者，神效。凡头面身体因破损伤风者， \n顷刻发胀，迟则不救。速用 草一二两，酒、水各半煎服，被盖暖卧，少顷即可消散。能饮 \n者，纯用酒煎尤妙。 \n\\x防风汤\\x（二五七）治破伤风表证未传入里，急服此。 \n防风 羌活 独活 川芎（等分） \n上每服五钱，水煎调蜈蚣散服。方在后二六四。 \n\\x白术防风汤\\x（二五八）治破伤风服表药过多自汗者。 \n白术 黄 （各一两） 防风（二两） \n上每服五七钱，水煎服。脏腑已和而自汗出者可服此药。若脏腑秘，小便赤而自汗者， \n急以后大芎黄汤下之。 \n\\x羌活汤\\x（二五九） 治破伤风在半里半表间，宜和解之，急服此汤，稍缓则邪入于里， \n不可用矣。 \n羌活 麻黄 菊花 川芎 防风 细辛 前胡 蔓荆子 黄芩 石膏 白茯苓 枳壳 \n甘草（各一钱） 薄荷 白芷（各五分） \n上每服五钱，姜、水煎。日二三服。 \n\\x羌活防风汤\\x（二百六十） 治破伤风初传在表，脉浮紧。 \n羌活 防风 本 当归 芍药 甘草（各四钱） 地榆 细辛（各二钱） \n上 咀。每服五七钱，水一钟半，煎八分。热服。量紧慢加减用之。热盛，加黄连、黄芩各二钱。 \n大便秘，加大黄二钱。自汗，加防风、白术各五分。 \n\\x大芎黄汤\\x（二六一） 治破伤风邪传于里，舌强口噤，项背反张，筋惕搐搦，痰涎壅 \n盛，宜疏导者，急服之。 \n川芎 羌活 黄芩 大黄（各一两） \n上每服五七钱，水煎服。 \n（《本事》）\\x玉真散\\x（二六二） 一名定风散。亦名夺命丹。治打扑金刃破伤风重者， \n牙关紧急，腰背反张，并蛇犬所伤。 \n天南星（汤泡七次，如急用，以湿纸裹煨） 防风（等分） \n上为末。每服二钱，温酒调服；若牙关紧急，腰背反张者，每服三钱，用童便调服。 \n虽内有瘀血亦愈，至于昏死心腹尚温者，速进二服，亦可保全。若破伤风疮口及疯犬咬伤， \n须用漱口水或热童便洗净，随用生南星为末掺之，或以水调涂之，出水为妙。 \n\\x养血当归地黄汤\\x（二六三） 治破伤风气血俱虚，发热头痛，服此以养气血，祛风邪， \n不拘新旧并可治之。 \n当归（酒拌） 熟地（各二钱） 芍药 川芎 本 防风 白芷 北细辛（各一钱） \n水二钟，煎一钟。食远服，甚者加酒助之。 \n\\x虾蚣散\\x（二六四） \n蜈蚣（一对，炙） 鳔胶（三钱， ） \n上为末。用防风、白术煎汤调下。 \n\\x破伤风灸法\\x（二六五）治跌打损伤，或虫兽伤破皮肤，以致风邪入内，牙关紧急，腰 \n背反张，或遍体麻木，甚者不知人事。急用蒜捣烂涂伤处，将艾壮于蒜上灸之，多灸为善，仍 \n用膏药护贴，内服玉真散。如毒蛇疯犬咬伤，先刺患处去毒血，如前法治之。 \n（海藏）\\x愈风丹\\x（二六六） 治疠病手足麻木，眉毛脱落，遍身生疮，及癞风瘾疹， \n皮肤瘙痒，搔破成疮，并皆治之。 \n皂角（一斤，锉寸许，无灰酒浸一宿，以水一碗挪成汁，去渣，用砂罐文武火熬热） 苦参（一 \n斤，取末四两） 乌梢蛇 白花蛇 土花蛇（各一条，去肠阴干，酒浸，取净肉晒干为末） \n上为末，入前二味和丸，桐子大。每服六七十丸，空心煎通圣散送下，干物压之， \n日三服，间日浴之，汗出为度。 \n\\x二圣散\\x（二六七）疏风和血，去疠毒。。 \n皂鱼刺（烧存性，为末） 大黄（半两） \n上用大黄半两煎汤调下皂刺末二钱。早服桦皮散，午以升麻汤下泻青丸，晚服二圣散。 \n（《局方》）\\x桦皮散\\x（二六八） 治肺壅风毒，遍身瘾疹瘙痒。 \n桦皮 枳壳（去穣，各四两，俱烧存性） 荆芥穗（一两） 炙甘草（半两） 杏仁（二两， \n去皮尖，用水一碗煮令减半，取出晾干为研） \n上共为末，瓷器收贮。每服二钱，食后温酒调服。 \n\\x升麻汤\\x（二六九）治诸风热癞，肌肉极热，身如虫行，或唇反绽裂。 \n升麻（三分） 人参 茯神 防风 羌活 犀角（镑） 羚羊角（镑，各一钱） 肉桂（五分） \n水二钟，姜三片，入竹沥少许，煎八分。不拘时服。或用下泻青丸。 \n（《宝鉴》）\\x醉仙丹\\x（二百七十）治疠风遍身麻木。 \n胡麻子（炒） 牛蒡子（炒） 枸杞子 蔓荆子（炒，各一两） 白蒺藜 苦参 天花粉 \n防风（各半两） \n上为细末，每一两五钱，入轻粉二钱拌匀。每服一钱，茶清调，晨午各一服，至五 \n七日，于牙缝中出臭涎，令人如醉，或下脓血，病根乃去，仍量人轻重虚实以用之。病重者， \n须先以再造散下之，候元气将复，方用此药。忌一切盐醋炙 浓味，止可食淡粥时菜，及诸蛇 \n肉以淡酒蒸熟食之亦可，以助药力。 \n（子活）\\x浮萍散\\x（二七一）治风癣疥癞。 \n浮萍（四钱） 荆芥 川芎 麻黄（去节） 当归 赤芍药 甘草（各二钱） \n水二钟，葱二茎，豆豉一撮，煎服，汗出为度。 \n（《宝鉴》）\\x换肌散\\x（二七二）治疠风久不愈，或眉毛脱落，鼻梁崩坏，其效如神。 \n白花蛇 黑花蛇（各三两，酒浸） 地龙（去土） 当归 川芎 赤芍药 天门冬（去心） \n甘草 何首乌（不犯铁） 沙参 胡麻子（炒） 天麻 紫参 苦参 白蒺藜（炒） \n细辛 白芷 蔓荆子 威灵仙 荆芥穗 菊花 木贼草 不灰木 石菖蒲 定风草（即草乌茎） \n草乌（炮，去皮脐） 苍术 木鳖（各一两） \n上各另为末，和匀。每服四五钱，食后温酒调服，加饮数杯尤妙。 \n\\x通天再造散\\x（二七三） 治大风实热内壅，宜此攻之。 \n郁金（半两） 大黄（炮） 皂刺（炒，各一两） 白丑（头末，半生半炒，六钱） \n上为细末。每服五钱，日未出时，面东以无灰酒调下，晚利下黑头小虫，病轻者只利臭 \n秽之物。忌荤腥浓 \n味半年，犯则再作不可救。此药服三五次即愈。 \n\\x白花蛇丸\\x（二七四）治疠风。丹阳荆上舍得疠疾，一僧治而愈，以数百金求方，秘不肯传， \n馆客袁生窥知藏衲衣领中，因醉之而窃录焉，用者多效。 \n白花蛇（一条，去头尾，连骨生用） 乌梢蛇（一条，去头尾，生用） 蝉蜕（去土） \n防风（去苗） 金银花（去叶） 枸杞子 槐花 苦参 生地（各二两） 全蝎（醋浸一日， \n去盐味） 黄芩 黄连 栀子 黄柏 乌药 牛膝 川芎 牛蒡子 何首乌（不犯铁） 连 \n翘天花粉 白蒺藜 威灵仙 荆芥穗 细辛 蔓荆子 金毛狗脊 胡麻子（炒，各一两） \n漏芦（半斤，洗净去苗取四两） \n上为末，米糊丸，桐子大。每服五六十丸，茶清送下，空心午前临卧各一服。 \n\\x白花蛇膏\\x（二七五）治诸风癞疾，遍身生疮。 \n白花蛇（肉四两，酒浸） 天麻（七钱） 荆芥 薄荷叶（各三钱） \n上为细末，用好酒二升，蜜四两，以银瓷器熬成膏。每温服一酒杯，日三次，煎饼压下， \n于暖处发汗效。 \n\\x防风天麻丸\\x（二七六） 治疠风癞病。此方应是仙传，一年中常疗数人，初服药有 \n呕吐者，不可疑，服而得愈，其效如神。 \n防风（去芦） 天麻 升麻 白附子（炮） 定风草 细辛（去苗） 川芎 人参（去芦） \n丹参（去芦） 苦参 玄参（去芦） 紫参（去芦） 蔓荆子 威灵仙 穿山甲（炒） 何首 \n乌（另捣，各二两） 蜈蚣（二条） \n上为细末，同何首乌末拌匀；外用胡麻一斤，淘净晒干炒香熟，另研为细末，乃入前药末 \n二两，又拌匀，炼蜜和为十丸。每服一丸，细嚼，温浆水送下，不拘时候，日三服。宜食 \n淡白粥一百二十日，大忌房劳，并将息慎口。 \n\\x行药方\\x（二七七）治疠毒。 \n大黄 白牵牛 槟榔（各一两） 甘草（三两） 轻粉（五钱） \n上共为细末。每服二钱，用白蜜三匙，姜汁二匙，五更时调服。病势重者，七月行一次； \n稍轻者，半月一次；轻者，一月一次，或二十日一次，以三五遍为度。 \n\\x皂角散\\x（二七八）治大风。 \n皂角刺（烧存性，一钱） 大黄（一钱） 轻粉（五分） \n上为末。空心酒调服，取下恶物。服药数日，齿缝出血甚臭。 \n\\x雷丸散\\x（二七九）取大风虫。 \n雷丸 贯仲（二味先另研） 阿魏（各二钱） 麝香（一分） 水银 硫黄 雄黄（各二钱半， \n用乳钵入醋少许，研令水银尽为度） \n上为细末。每服一钱，天明温酒送下。 \n\\x黑虎丹\\x（二百八十）治大风诸癞恶疮，毒虫内蚀，形骸变坏。 \n天灵盖（三两） 人中白 桃仁（炮，去皮尖，各二两） 老皂刺（烧存性） 穿山甲（炒，各 \n半两） 轻粉（二钱） 麝香（五分） 干虾蟆（二个，去头足，烧存性） \n上为末，炼蜜丸，桐子大。每服三十丸，月首五更米饮连口服，取虫尽即愈。杀劳虫通用。 \n\\x苦参酒\\x（二八一）治癞风，及疮疹疥癣最多者。 \n苦参（五斤，切片） \n上以好酒三斗浸三十日。量饮一合，日服不绝，觉痹即瘥。 \n\\x硫黄酒\\x（二八二） 杀疠风诸虫。 \n明硫黄（研极细） \n上用酒浸。空心饮清汁。明日添硫黄，再研入酒如前饮之。 \n\\x七珍汤\\x（二八三） 浴洗大风。 \n青 艾叶 忍冬藤 苍耳子 桑条 槐条 柳条（三条，俱捶碎用） \n上煎水一桶，入炒盐半斤。间日一洗浴，密室中以草席围之，洗出汗为妙，不过十次愈。 \n\\x乌头汤\\x（二八四）治大风疮癞。 \n草乌 麻黄根 艾叶 地骨皮 朴硝（各一两） \n上为粗末，用水一桶，椒一合，葱三十根同煎汤，入醋一钟。于密室中自用手巾围搭 \n四肢，候汤可浴，令汗透，务使面上如珠，徐起或坐或卧，片时汗干着衣，避风五日，再浴， \n如此三五次，每浴后更服换肌丹等药。 \n\\x敷 方\\x（二八五） \n雄黄 硫黄 白矾 草乌 蛇床子（烧存性，等分） \n上为末，用香油或浓蜜水调敷患处。 \n（《直指》）\\x洗疠方\\x（二八六） 浴洗大风疮。 \n苦参 荆芥 防风 白芷 羌活 独活 本（各一两） 洛阳花（四两，火酒喷过一宿） \n上作三次，煎水。洗令出汗。 \n\\x梅花白癞\\x（二八七） \n用香油二碗，入鸡蛋黄三枚熬将焦，去 ，熬油至一碗许。 \n外用雄黄（一钱） 白矾（三分） 花椒（五分） 上共为细末，入油内再熬熟，收贮候用。 \n每用猪毛汤热洗疮垢，搽油三五次即愈。愚按∶此方于蛋焦去 之后，入水银五钱，微火渐热 \n之，然后再加朱砂细末二钱，并雄黄、白矾等于搅熬匀熟收用必妙。 \n\\x腊梨疮\\x（二八八） \n用杏仁百枚炒为炭，入葱白、蜂蜜共捣烂。先用花椒煎汤洗净，然后用此药搽之，新旧 \n疮皆可用，但勿见风方好。 \n\\x 疮二方\\x（二八九） \n大枫子仁 木鳖仁 蛇床子（各半两） 水银（三钱，研散于内） \n上先以刀刮去疮痂，花椒汤洗净，外用麻油熬成珠，调药敷之，八日即愈。 \n又方∶用猪骨髓和轻粉捣烂罨之，过夜即愈。 \n\\x头面黄水肥疮\\x（二百九十）治小儿头面患疮，浓汁作痒，痂浓者名曰粘疮，当用此方， \n或止用矾、丹二味亦可。若作痒出水，水到即溃者，名曰黄水疮，当用后一方。 \n松香 枯矾 官粉 飞丹 \n上等分为末，麻油调敷，或加香烟垢更效，于香炉盖上刮取用之。一方∶用绿豆、松香等分为末， \n麻油调敷极效，或内服荆防败毒散等药。又方∶用益元散加枯矾少半，以麻油调敷，大妙， \n大妙。 \n\\x诸癣疥顽疮\\x（二九一） \n油核桃 大枫子 樟脑 水银 \n上四色研匀擦之，此治有虫者大效。一、凡无虫而忽尔生疮肿痛，或湿烂者，但以地沥青搽 \n之即可愈。 \n\\x白虎丹\\x（二九二） \n发则头面四肢眼目俱肿，而惟额上指尖两耳不肿及不见赤色者，方 \n是其证。 \n先将马桶洗净，用沸汤倾入，盖少顷，倾出盆内浴之，数次即退。再用车前草、九里香、 \n马蹄香、枸杞苗即雁棱菜同捣烂，和麻油遍身自上而下擦之。大忌鸡鱼生冷炙 日色火光灯 \n烟汤气，极须谨慎。 \n又方∶用生香附末冷茶调服一二钱即愈。 \n又方∶擂绿豆水去渣饮一二碗妙。 \n\\x紫白癜风歌\\x（二九三） \n紫癜白瘕一般风，附子硫黄最有功，姜汁调匀茄蒂擦，若经三度永无踪。 \n又歌∶ \n紫癜白癜两般风，水银轻粉最成功，捣取生姜自然汁，只须一擦便无踪。 \n又方∶治紫白癜汗斑等风。 \n雄黄 硫黄 黄丹 密陀僧 南星 \n上为末。先用葱擦患处，次用姜蘸药末擦之，擦后渐黑，次日再擦，黑散则愈矣。 \n又四神散∶ \n雄黄 雌黄 硫黄 明矾 \n各等分，先浴令通身微汗，以姜蘸擦之，再以热汤淋洗，当日色淡，五月除根。 \n\\x汗斑四方\\x（二九四） \n大黄（二钱） 枯矾 椒红（各五分） \n上用猪脂、沙糖同捣烂，俟浴起以细麻布包擦至痛而止，数日即愈。或止用硫黄少入麻 \n油研如糊，浴用麻布蘸擦数次即愈。 \n又方∶ \n密陀僧 硫黄（各三钱） 轻粉（二钱） 雄黄（一钱） 人言（五分） \n上为末，姜汁调。用茄蒂蘸擦，三日内不沐妙。 \n又方∶ \n雌黄 雄黄（各一钱） 硫黄（五分） 麝（半分） \n浴后姜蘸擦，二三日勿洗。 \n又方∶ \n硫黄一两，用醋煮半白，海螵蛸三个共为末。浴后以生姜蘸擦患处，须避风少时， \n数度即愈。 \n\\x漆疮方\\x（二九五） \n用香油调铁锈涂之。胃气实者，内服黄连解毒汤，胃气弱者，以漆毒侵犯中气致虚， \n多有作呕不能饮食者，宜用六君加砂仁、藿香、酒炒芍药之类。又解漆毒法见因阵二三五。 \n\\x手足甲疽\\x（二九六） \n凡手足间或因修甲伤肉，或因损足成疮，溃烂上脚。用绿矾置铁板上， 沸色赤如熔金色 \n者为真，沸定取起研末，以盐汤洗搽。 \n\\x坐板疮\\x（二九七）肿痛多脓者。 \n密陀僧 生矾 大黄 \n等分为极细末。敷之。 \n\\x 疮神效膏\\x（二九八）治 疮脚疮。 \n先看疮形大小，用棉纸裁成四框十二张，四角用小捻钉住听用。外以好香油二两，用 \n铜杓以文武火熬之，先下花椒四十九粒，煎黑取起。次下槐枝长一寸者四十九节，煎黑又取起。 \n再次下黄占一两，轻粉二分，枯矾一分溶清，却入前纸浸油内令透，不可令焦，取起听用。 \n凡贴疮时，先将槐枝、葱、椒煎汤洗疮令透，拭干，乃以此膏纸粘贴，外面再以油单纸盖护，乃 \n用软帛缚定，一日取下，揭去一层，复用汤药洗净，又贴之，尽十二张，无有不愈者。 \n\\x隔纸膏\\x（二九九） 治 疮神效。 \n黄 末（五钱） 轻粉 乳香 没药（各一钱） 银朱（一钱） 血竭（五分） 铜绿（二分） \n上为细末，真香油调成膏，摊油纸上。再用油单纸一层，以针刺孔数十，掩膏药上贴之， \n一日一易其膏。 \n\\x二味隔纸膏\\x（三百）治 疮湿毒疮。 \n石膏（ ） 枯矾（等分） \n上为末，用桐油调成膏，作隔纸膏贴之，更服荆防败毒散。如数剂不愈，再服黄 人参汤。 \n\\x烂腿疮久不愈方\\x（三百一） \n用米糖即胶饴也，以碗盛于饭锅内蒸化，先用花椒、荆芥、防风等药煎汤洗疮净，乃将 \n胶饴薄摊疮上，外以软竹箬盖定，用绢缚之，数日即愈，神效。 \n\\x冻疮方\\x（三百二） \n沥青末 黄蜡（各一两） 麻油（一两） \n上三味溶化。搽患处。 \n\\x汤火六方\\x（三百三） \n凡初被汤火所伤，速用冷灶柴草灰一二升，入盐少许，以凉水调如稀糊，尝味微咸为度， \n用以浓摊伤处，觉热则易之，连易数次，则火毒皆拔于灰中，必肿痛随散，结痂而愈，诚神妙 \n方也。 \n又方∶治溃烂肿痛者。用生桐油调人中白敷之即愈，亦妙方也。 \n又方∶用皂矾研细，和以冷水浇伤处，其疼立止，其肿即消。 \n又方∶用大黄、芒硝等分为末，鸡子清调贴之神效。 \n又方∶用石膏末香油调敷即愈。 \n又赤石脂散 治汤火伤肉烂赤痛。 \n赤石脂 寒水石 大黄（等分） \n上为末。新汲水调涂。 \n\\x汤火至圣膏\\x（三百四）治汤火伤疮，用鸡子黄置银石器内熬油，调胡粉敷之。锦衣杨永兴 \n厨下夜间回禄，凡睡此房已死将死者，灌以生萝卜汁，良久悉愈。凡遇此患者，以此治之， \n其应如响。 \n\\x汤火止痛散\\x（三百五）止痛生肌。 \n大黄末（微炒） 当归末（等分） \n上用麻油调搽，或干掺亦可。 \n\\x小儿丹毒\\x（三百六） \n此毒多生头面四肢，色赤或肿，游走不定，甚者宜用前瓷锋砭法，使毒血遇刺皆出，更以 \n神功散敷之，内服荆防败毒散，或五福化毒丹，若使毒瓦斯入腹则不治。或愈而复发，皆因母食 \n辛辣炙 以致肉热，宜于母药中加漏芦煎服，或令自服亦愈。 \n\\x小儿鹅口\\x（三百七） \n凡小儿口内白屑满口者为鹅口疮，则不能饮乳。用发或软绢缠指，醮井水拭舌上使净。 \n如屑不能脱，浓煮栗木汤以绵缠箸头拭洗，却用飞过黄丹搽之。 \n\\x加味太乙膏\\x（三百八）一切疮疡并宜贴之。先用隔蒜炙，更服活命饮以收全功。 \n当归 生地黄 芍药 玄参 大黄（各二两） 加甘草（四两） \n用麻油二斤煎，丹收。 \n\\x景岳会通膏\\x（三百九） 凡诸痈毒、痞块、风气，骨节疼痛，无所不治。 \n大黄 木鳖仁 当归 川芎 芍药 生地 麻黄 细辛 白芷 防风 荆芥 苍术 羌活 \n川乌 甘草 乌药 南星 半夏 香附 官桂 苍耳 骨碎补 草乌 艾叶 皂角 枳壳 三棱 \n蓬术 萝卜子 水红花子 巴豆 五倍 独活 桃仁 苏木 红花 续断 连翘 栀子 苦参 \n槐花 皂刺 干姜 蓖麻子 透骨草（晒干） 穿山甲 全蝎 僵蚕 蜂房（各一两） 蛇蜕（一 \n大条） 蜈蚣（十四根） 虾蟆（三只） 血余（一团） 独蒜（四头） \n上五十四味，用麻油五斤，浸三日，先煎血余、蓖麻、木鳖、桃仁、巴豆、虾蟆、独 \n蒜、待半枯，然后人余药煎黑，去滓丹收，后下细药十味。 \n阿魏（二两） 乳香（制） 没药（制，各一两） 木香 丁香 雄黄 朱砂 血竭 \n儿茶（各五钱） 麝香（不拘一二钱） \n上麝香、丁香、木香三味宜最后下之。以上收油法，凡熬成熟油一斤，下飞净好红丹八两； \n若欲微嫩，则止下七两五钱。 \n\\x神异膏\\x（三百十） 治痈疽疮毒及收口甚效，此疮疡中第一方也。 \n麻油（二斤） 黄丹（十二两） 黄 杏仁 玄参（名一两） 蛇蜕（半两） 男发（如鸡 \n子团） 蜂房（子多者佳，一两） \n上先以黄 、杏仁、玄参入油煎至将黑，乃入蛇蜕、蜂房、乱发再煎至黑，去 ，徐 \n徐下丹慢火煎收，黄丹不必拘数，但以得中为度。凡膏药用久，必至老硬，煎时预留嫩膏少许， \n如硬，量和之。 \n\\x清凉膏\\x（三一一） 治一切疮疡溃后宜用之。 \n当归（二两） 白芷 白芨 木鳖子 黄柏 白蔹 乳香 白胶香（各五钱） 黄丹（五两净） \n净麻油（十二两） \n上用油煎前六味，以槐柳枝顺搅油熟，丹收然后下乳香等二味。 \n\\x阿魏膏\\x（三一二）治一切痞块，更服胡连丸。 \n羌活 独活 玄参 官桂 赤芍药 穿山甲 生地黄 两头尖 大黄 白芷 天麻 \n红花（各半两） 木鳖（十枚，去壳） 乱发（一团） 槐柳桃枝（各半两） \n上用麻油二斤四两，煎药黑去 ，入发再煎，发化仍去 入上好真正黄丹煎收，软硬 \n得中，入后细药即成膏矣。 \n阿魏 芒硝 苏合油 乳香 没药（各五钱） 麝香（三钱） \n上凡贴膏药，须先用朴硝随患处铺半指浓，以纸盖用热熨斗熨良久，如硝耗再加熨之， \n二时许方贴膏药。若是肝积，加芦荟末同熨之。 \n\\x朱砂膏\\x（三一三）治一切顽疮破疮，杖疮痈疽，发背破伤者，最妙最佳。 \n麻油（一斤） 飞母（六两） 水银（一两） 朱砂（佳者一两半飞） 好黄蜡（四两） \n先下油熬数沸，下鸡子二枚，敲开连壳投之，熬焦捞去子，退火俟油定，下水银五钱， \n再加微火搅熬饭顷，即入丹渐收成膏，后下黄占再搅，候大温，下极细好朱砂一两五钱搅匀， \n瓷罐收贮。 \n\\x神效当归膏\\x（三一四）治一切发背疮疡，汤火疼痛等证，去腐肉，生新肉，其效如神。 \n凡洗拭换膏，必须预备即贴之，新肉畏风故也。如用白蜡尤好。此药生肌止痛，补血续筋， \n故与新肉相宜。 \n当归 生地黄 黄蜡（各二两。白蜡当减半） 麻油（六两） \n上先将当归、地黄各一两入油煎黑去 ，又将二味各入一两煎至微焦，复去滓，乃入蜡溶 \n化，候冷搅匀即成膏矣。用涂患处，以纸盖之，如有死肉，须用利刀剪去，则生肌尤速。 \n\\x攻坚败毒膏\\x（三一五）亦名乾坤一气膏。专攻痞块，诸疮毒，痔漏。 \n当归 熟地 生地 白芍药 赤芍药 南星 半夏 三棱 蓬术 木鳖 两头尖 穿山甲 \n巴豆仁 肉桂 五灵脂 桃仁 续断 玄参 玄胡索 蓖麻子仁 白芷 羌活 独活 大黄 \n红花 川乌 草乌 苏木 川芎 防风 杏仁（各一两） \n上用麻油四十两，浸诸药三日，桑柴火煎成，丹收后下细药。 \n乳香（制） 没药（制，各一两） 真阿魏（一两半） 麝香（三钱） \n上方于细药中加芦荟、木香各一两，蟾酥三钱，即名消痞大成膏。 \n\\x消痞膏\\x（三一六） \n三棱 蓬术 穿山甲 木鳖仁 杏仁 水红花子 萝卜子 透骨草（晒干） 大黄（各一两） \n独头蒜（四个） \n上用香油一斤，入前药十味煎油成，以飞丹收之，后下细药。 \n真阿魏 乳香 没药（各一两） 麝香（三钱） \n上先下乳、没、阿魏三味，后下麝香，搅匀待冷，倾水中浸数日，用瓷瓶收贮，勿使 \n泄气。用时以白布或坚白纸摊贴，八九日一换。或见大便去脓血，勿以为异，亦有不去脓血而 \n自愈者。若治泻痢，可贴脐腹。忌房事生冷。凡贴症积痞块，先用荞麦面和作一圈，围住患处 \n四边，其块上放皮硝二三两，盖浓纸以熨斗熨，令热气内达，然后去硝用膏药贴之。上原方用 \n白花菜同透骨草另煎膏二两，搅入膏内收用，但白花菜惟西北方间有之，求觅不易，故余用独 \n蒜、萝卜子代之，其功亦不减也。 \n\\x琥珀膏\\x（三一七）治颈项瘰 ，及腋下初结小核、渐加连珠，不消不溃，或溃而脓 \n水不绝，经久不瘥，或成漏证。 \n琥珀 白芷 防风 当归 木鳖子 木通（各一两） 丁香 桂心 朱砂 木香 松香（各半两） \n麻油（二斤） \n上先将琥珀等六味为末，其余药入油煎黑，滤去 ，徐入黄丹再煎，软硬得中，入前 \n药成膏贴之。 \n\\x贴痞琥珀膏\\x（三一八）贴症积痞块。 \n大黄、朴硝各一两为末，以大蒜同捣膏贴之。 \n\\x水红花膏\\x（三一九）贴痞块。 \n用水红花或子，每一碗以水三碗，用桑柴文武火熬成膏，量痞大小用纸摊贴，以无方为度， \n仍将膏用酒调服。忌荤腥油腻。不饮酒者，白汤下。 \n\\x火龙膏\\x（三百二十） 治风寒湿毒所袭，筋骨挛痛，及湿痰流注，经络壅痛，不能行步， \n并治历节风，鹤膝风，其效如神。 \n生姜（八两，取汁） 乳香（为末） 没药（为末，各五钱） 麝香（一钱） 真牛皮广胶（二两） \n上先将姜汁并胶熔化，方下乳香、没药调匀，待少温下麝香即成膏矣。摊贴患处，更 \n服五积散。如鹤膝风，须服大防风汤。 \n\\x赵府膏\\x（三二一） 专贴疼痛肿毒。 \n干虾蟆（三个） 全蝎 僵蚕（各一两） 蜈蚣（四条） 斑蝥（四十个） 商陆根（一两六钱） \n花椒（一钱） 童子发（六分） 鸡内金（二个） 槐枝（三寸长者各四十根） \n细药∶ \n儿茶 乳香 没药 血竭 龙骨 黄占 白占（各五钱） 麝香（一钱） \n上用麻油二斤煎，飞丹收。 \n\\x密陀膏\\x（三二二） 此膏治 湿诸疮，风漏等证神效。凡治疼痛，先以葱、姜擦患处， \n然后贴之。 \n先用密陀僧一二斤打碎，将童便煮之，觉其浊性去而童便气清乃可止矣。用便煮过则贴疮 \n不痛。晾干，研极细如面候用。 \n用桐油不拘几斤，熬至将黑为度，每熟油一斤，用陀僧六两收之，于将成膏之顷取起，离 \n火候稍凉，量膏多少，入冷水数碗徐搅之，恐其泛出，俟少定，即逼去其水，再上火熬化，复 \n入水数碗搅逼如前，或三次更妙，然后熬净其水，每油一斤，再入官粉二两熬收，其色方黑。 \n凡熬此者，铜锅须大方可用。 \n\\x八仙红玉膏\\x（三二三）治诸疮。 \n龙骨 赤石脂 儿茶 血竭 没药 乳香（各一钱） 轻粉（五分或一钱） 冰片（二分） \n上用麻油二两，入当归五钱煎枯去滓，入龙、石、茶、蝎四味，再煎一二沸，次入乳、没 \n略煎匀后，入黄占五钱溶化，冷定入轻、冰摊贴。 \n\\x碧油膏\\x（三二四）止痛排脓，灸后宜用之。 \n桃枝 柳枝 桑枝 槐枝（各二两） 乳香（另研） 血竭（各五钱） 黄丹（四两，净） \n上用麻油十两煎，膏成后下乳香、血竭。 \n\\x长肉膏\\x（三二五） \n人参 黄 当归 夜合树皮 玄参（各一两） 血余（三两） 老鼠（一个） \n细药∶ \n血竭 龙骨 赤石脂 白腊（各五钱） \n上用麻油一斤煎，飞丹收。 \n\\x保养元气膏\\x（三二六）此膏助元阳，补精髓，通血脉，镇玉池，养龟存精，百战百胜， \n待妇人经净之时，去膏而泄则可成孕，并治腰膝疼痛，五劳七伤，诸虚百损，半身不遂，膀胱 \n疝气，带浊淫淋，阴痿不举，无不效者。 \n此邵真人进御方也。 \n麻油一斤四两，入甘草二两，先熬六七滚，然后下诸药。 \n生地黄 熟地黄（俱酒洗） 麦门冬 肉苁蓉（酒洗） 远志肉 蛇床子（酒浸） \n菟丝子（酒浸） 牛膝（酒洗） 鹿茸 川续断 虎骨 紫梢花 木鳖仁 谷精草 大附子 \n肉桂（各五钱） \n上熬成，以煮过松香四两，飞丹半斤收之，次下细药。 \n次下龙骨 倭硫黄 赤石脂（各二钱） \n又次下乳香 沉香 丁香 木香（各一钱） \n又次下阳起石（三钱） 麝香（五分） 蟾酥 鸦片（各一钱） \n又次下黄占五两上煎成，入井中浸三四日。每用膏七八钱，红绢摊贴脐上，或腰眼间，每 \n帖五六十日再换。 \n\\x药煮松香法\\x（三二七）凡用松香收膏药者，必用水多煮一二遍，去其涩燥之性，方 \n可贴疮不痛。若用贴症痞血 \n块，则当加药如后法煮过用之方妙。 \n大都松香（三斤） 用皮硝（一碗） 水红花（四两） 大黄 当归 生地（各二两） \n三棱 蓬术（各一两） \n上药七味，用水一桶、先熬汁，去滓净，用煮松香，徐徐添入，以汁完为度，收用之极 \n佳。一、收油之法，凡煮过松香一斤，入熬熟药油五两，即成膏矣。 \n\n\n\n<目录>卷之六十四春集·外科钤古方\\外科\n\n<篇名>以下通用方\n\n属性：\\x四君子汤\\x（三二八）方在补阵一。 \n治疮疡脾胄虚弱，或因克伐，肿痛不散，溃敛不能，宜用此以补脾胃，诸证自愈。若误用攻 \n毒，则七恶随至。脾胃虚弱，饮食少思，或食而难化，或欲作呕，或大便不实。若脾胄气虚， \n疮口出血，吐血便血，尤其用之，盖气能摄血故也。凡气血俱虚之证，宜于此汤但加当归， \n脾胄既旺，饮食自进，阴血自生。若用沉阴之剂，脾胃复伤，诸症蜂起。 \n\\x六君子汤\\x（三二九）方在补阵五。 \n治脾胃虚弱，或寒凉克伐，肿痛不溃敛，宜服此汤以壮营气，则诸证自愈。 \n\\x加味四君子汤\\x（三百三十）方在补阵二。 \n治痔漏下血，面色痿黄，凡诸气虚脾虚不能摄血等证。 \n\\x四物汤\\x（三三一）方在补阵八。 \n治疮疡血虚发热，或因失血，或因克伐，或因溃后，致晡热内热，烦躁不安，皆宜服之。 \n盖血生于脾，脾虚不能生血者，宜用四君子加当归、酒炒白术以补脾。 \n\\x八珍汤\\x（三三二）方在补阵十九。 \n治疮疡脾胄损伤，恶寒发热，烦躁作渴，或疮疡溃后气血亏损，脓水清稀，久不能愈。 \n\\x十全大补汤\\x（三三三）方在补阵二十。 \n治疮疡气血虚弱，肿痛不愈，或溃疡脓清、寒热，自汗盗汗，食少体倦，发热作渴， \n头痛眩晕似中风状者。 \n\\x补中益气汤\\x（三三四）方在补阵三十。 \n治疮疡元气亏损，恶寒发热，或因克伐，肢体倦怠，饮食少思，或不能起发消散，生肌收 \n敛，或兼饮食劳倦，头痛身热，烦躁作渴，脉洪大弦虚，或微细软弱。 \n\\x归脾汤\\x（三三五）方在补阵三十二。 \n治疮疡忧思伤脾，血虚发热，食少体倦，或脾不摄血，以致妄行，或健忘怔忡，惊悸 \n少寐，或心脾作痛，自汗盗汗，或肢体肿痛，大便不调，或妇人经候不调，晡热内热，或唇疮 \n流注，及不能消散溃敛等症。 \n\\x独参汤\\x（三三六）方在补阵三十七。 \n治疮疡一切失血，或脓水出多，气血俱虚，恶寒发热，作渴烦躁。盖血生于气，故血脱者宜 \n补气，阳生阴长之理也。用人参一两，枣十枚、姜十片，水煎徐徐服。 \n\\x人参养营汤\\x（三三七）方在补阵二十一。 \n治疮疡脾胃亏损，发热恶寒，血气俱虚，四体倦怠，肌肉消瘦、面色痿黄、汲汲短气， \n食少作渴，凡大病后最宜用此。 \n\\x五味异功散\\x（三三八）方在补阵四。 \n治脾胃虚弱，饮食少思。即四君子汤加陈皮。 \n\\x生脉散\\x（三三九）方在补阵五六。 \n治疮疡胃气亏损，阴火上冲，口干喘促。或肢体倦怠，肌肉消瘦，面色痿黄，汲汲短气， \n汗出不止，食少作渴。或脓水出多，气血俱虚，烦躁不安，睡卧不宁。或湿热大行，火土合病， \n脾胃虚弱，身重气短。或金为火制，绝寒水生化之源，肢体痿软，脚欹眼黑等证。 \n\\x当归补血汤\\x（三百四十）方在补阵四四。 \n治疮疡脾胃虚损，或服峻剂致血气俱虚，肌热、大渴引饮，目赤而红，昼夜不息，其脉洪 \n大而虚，重按全无，此病多得于饥饱劳役者，若误服白虎汤必死。 \n\\x黄 六一汤\\x（三四一）方在补阵四九。 \n治疮疡阴阳俱虚，盗汗不止。 \n\\x参术膏\\x（三四二） 方在补阵三九。 \n治疮疡中气虚弱，诸药不应，或因用药失宜，耗伤元气，虚症蜂起，但用此药补其中气， \n诸症自愈。 \n（东垣）\\x圣愈汤\\x（三四三） 方在补阵九十。 \n治脾胃亏损，脓水不止，或金疮出血，心烦不安，眠睡不宁，五心烦热，饮食少思。 \n（钱氏）\\x七味白术散\\x（三四四）方在小儿七。 \n治疮疡胃气虚弱，或因克伐，或因吐泻，口干作渴，饮食少思。 \n（陈氏）\\x五味子汤\\x（三四五） 方在补阵五八。 \n治疮疡肾水枯涸，口燥咽干，喘促虚烦。 \n\\x参附汤\\x（三四六） 方在补阵三十七。 \n治疮疡失血过多，或脓瘀大泄、或寒凉汗下，真阳脱陷，上气喘急，自汗盗汗，气短头晕 \n等证，急服此汤以救元气，缓则不治。 \n\\x人参理中汤\\x（三四七）方在热阵一。 \n治疮疡脾胃虚寒，呕吐泄泻，饮食少思，肚腹作胀或痛、或胸膈虚痞，饮食不入。 \n\\x六味丸\\x（三四八） 方在补阵百二十。 \n此壮水之剂。夫人之生，以肾为主，凡病皆由肾虚而致，此方乃天一生水之剂，无有 \n不可用者。若肾虚发热作渴，小便淋秘，痰气壅盛，咳嗽吐血，头目眩晕，小便短少，眼花耳 \n聋，咽喉燥痛，口舌疮裂，齿不坚固，腰腿痿软，五脏齐损，肝经不足等症，尤多用之， \n水能生木故也。若肾虚发热，自汗盗汗，便血诸血，失喑。此水泛为痰之圣药，血虚发热之 \n神剂也。 \n\\x八味丸\\x（三四九） 方在补阵百二一。 \n治命门火衰，不能生土，以致脾胄虚寒，而患流注鹤膝等症，不能消溃收敛，或饮食少思， \n或食而不化，脐腹疼痛，夜多漩溺。 \n（陈氏）\\x加减八味丸\\x（三百五十）方在古补百二二。 \n治肾水不足，虚火上炎，发热作渴，咽喉疼痛，口舌生疮，寝汗憔悴等证。 \n\\x还少丹\\x（三五一）方在补阵一三五。 \n治足三阴经虚损，致患鹤膝风等证。又补脾肾，进饮食之良剂也。 \n\\x大防风汤\\x（三五二） 方在补阵九八。 \n治足三阴亏损，外邪乘虚内患，鹤膝风或附骨疽肿痛，或肿而不痛，不问已溃未溃，用三 \n五剂后，更全用调补之剂。 \n\\x十宣散\\x（三五三）方在痘疹十四。 \n治疮疡脉缓涩，体倦恶寒，或脉浮紧细，用之以散风助阳也。 \n（薛氏）\\x四神丸\\x（三五四）方在热阵一五一。 \n治疮疡脾肾虚弱，大便不实，饮食少思，或小腹作痛，或产后泄泻，肚腹作痛，不思饮食。 \n\\x五积散\\x（三五五）方在散阵三九。 \n治风寒湿毒客于经络，致筋挛骨痛，或腰脚酸疼，或拘急，或身重，并皆治之。 \n\\x二陈汤\\x（三五六）方在和阵一。 \n治疡痈中脘停痰，呕吐恶心，或头目不清，饮食少思等症。 \n\\x小柴胡汤\\x（三五七）方在散阵十九。 \n治肝胆经风热，瘰 结核，或肿痛色赤，或寒热往来，或日晡发热，或潮热身热，默默 \n不欲饮食，或怒火口苦，耳聋咳嗽，皆用此药。 \n\\x小青龙汤\\x（三五八）方在散阵八。 \n治肝肺受寒，咳嗽喘急，宜服此发散表邪。 \n\\x人参败毒散\\x（三五九）方在散阵三六。 \n治疮疡外有表邪， 痛寒热，或拘急头痛，脉紧有力。 \n\\x不换金正气散\\x（三百六十）方在和阵二二。 \n治疮疡脾气虚弱，寒邪相搏，痰停胸膈，致发寒热。服此以正脾气，则痰气自消，寒 \n热不作。 \n\\x加味道遥散\\x（三六一）方在补阵九三。 \n治疮疡肝脾血虚，内热发热，或遍身瘙痒，寒热，或肢体作痛，头目昏重，或怔忡颊 \n赤，口燥咽干，或发热盗汗，食少不寐，或口舌生疮，耳内作痛，或胸乳腹胀，小便欠利。 \n\\x防风通圣散\\x（三六二） 方在攻阵十六。 \n治时毒热毒，便秘热燥邪实等症，若非大满大实者，不可服用此药。 \n\\x消风散\\x（三六三） 方在散阵四七、四九。 \n治风热瘾疹瘙痒，及妇人血风瘙痒，或头皮肿痒，或诸风上攻，头目昏眩，项背拘急， \n鼻出清水，喷嚏声重，耳作蝉鸣。 \n\\x犀角散\\x（三六四）方在痘疹六三。 \n治时毒痈疡热盛，烦躁多渴，赤斑等症。 \n\\x黄连解毒汤\\x（三六五）方在寒阵一。 \n治疮疡 痛，烦躁饮冷，脉洪数，或发狂言。 \n\\x普济消毒饮\\x（三六六） 方在寒阵十三。 \n治天行时毒，头面肿痛，或咽喉不利，若饥馑之后患此者最宜用之，仍当兼固胃气。 \n\\x栀子清肝散\\x（三六七）方在寒阵六十。 \n治三焦、足少阳风热，耳内作痒生疮，或出水疼痛，或胸乳间作痛，或寒热往来。 \n\\x柴胡清肝散\\x（三六八）方在寒阵五九。 \n治鬓疽，及肝胆三焦风热怒火之症，或头胸作痛，或疮毒发热。 \n\\x加味龙胆泻肝汤\\x（三六九）方在寒阵六四。 \n治肝经湿热，或囊痈便毒，下疳悬痈， 肿作痛，或溃烂不愈，或睾丸悬挂，小便涩滞， \n或妇人阴疮痒痛，或男子阴挺，痔漏，肿痛，或出脓水。 \n\\x清心莲子饮\\x（三百七十）方在寒阵三二。 \n治膀胱阴虚湿热，玉茎肿痛，或茎窍涩滞，口苦咽干，小便色赤，或白浊，夜安静而昼发热。 \n\\x黄芩清肺饮\\x（三七一）方在寒阵三八。 \n治疮疡肺经阴虚火燥而小便不通。 \n（东垣）\\x清胃散\\x（三七二） 方在寒阵五四。 \n治膏粱积热，唇口肿痛，齿龈溃烂 痛，上连头面，或恶寒发热。 \n\\x竹叶石膏汤\\x（三七三）方在寒阵五。 \n治痈疽胃火盛，肿痛作渴。 \n\\x竹叶黄 汤\\x（三七四）方在寒阵七。 \n治痈疽气血虚，胃火盛而作渴。 \n\\x滋肾丸\\x（三七五）方在寒阵一六三。 \n治疮疡肾经阴虚发热，作渴便赤，足热腿软等证。凡不渴而小便秘，热在下焦血"}, {"n": 41, "text": "卷四十一\n\n分也，最宜此药。经云∶无阴则阳无以化，若脾肺燥热所移，此当清其化源。 \n\\x泻青丸\\x（三七六） 方在寒阵百五一。 \n治肝经实热，瘰 肿痛寒热，或胁乳作痛，大便秘结。 \n\\x大芦荟丸\\x（三七七）方在小儿百十五。 \n治肝火下疳溃烂，或 肿作痛，或治小儿疳膨食积，口鼻生疮，牙龈蚀烂等疮，并虫蚀 \n肛门痒痛。 \n\\x五苓散\\x（三七八）方在和阵一八二。 \n治疮毒下部湿热，小便短少。 \n\\x五淋散\\x（三七九）方在寒阵百十七。 \n治膀胱有热，水道不通，或尿如豆汁，或如砂石，或如膏油，或热沸便血。 \n\\x八正散\\x（三百八十）方在寒阵百十五。 \n治下疳便毒，小便淋漓，脉证俱实者。 \n\\x清肺饮\\x（三月八一） 方在和阵三五一。 \n治疮疡渴而小便不利，乃肺经有热，是绝寒水生化之源，宜用此药以清化源，其水自生而 \n便自利。 \n\\x益元散\\x（三八二） 方在寒阵百十二。 \n治疮疡小水不利，内生烦热作渴。 \n\\x四顺清凉饮\\x（三八二）方在攻阵二五。 \n治疮疡烦躁饮冷， 痛脉实，大便秘结，小便赤涩。 \n\\x玉烛散\\x（三八四）方在攻阵二四。 \n治便痈初起，肿痛发热，大小便秘，宜用此行散之。若邪实毒甚者，宜桃仁承气汤。 \n\\x人参平肺散\\x（三八五）方在寒阵三七。 \n治火克肺金，传为疽痿，咳嗽喘呕，痰涎壅盛，胸膈痞满，咽嗌不利。 \n\\x葶苈大枣泻肺汤\\x（三八六）方在和阵百四十。 \n治肺证胸膈胀痛，上气喘急，或身面浮肿，鼻塞声重。 \n\\x枳壳散\\x（三八七）方在寒阵百一。 \n治烦热便血。 \n\\x失笑散\\x（三八八）方在妇人百四。 \n治跌扑，产后心腹绞痛，或不知人事，或经行瘀血作痛成癃。 \n\\x槐角丸\\x（三八九）方在寒阵一七五。 \n治痔漏肿痛，便血脱肛。 \n\\x紫金锭\\x（三百九十）方在因阵二百二。 \n治痈疽诸毒。 \n（《良方》）\\x通关散\\x（三九一）方在古因九八。 \n搐鼻，开牙关。"}]);
})();
